"use strict";
const LESSONS = {
 "13": "═\n# पाठ-13: ऑनलाइन-योग्य उत्पाद — हरा, पीला, लाल श्रेणी\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर F/O · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nखंड-2 शुरू — उत्पाद, फ़ोटो और AI-सामग्री की दुनिया। पहला पाठ यह पक्का करता है कि आपका उत्पाद वाक़ई ऑनलाइन-योग्य है। पाठ के बाद आप तीन बातें कर पाएँगे — हरा-पीला-लाल तीन श्रेणी में किसी भी उत्पाद को छाँट पाएँगे; पाठ-11 के अपने चुने उत्पाद और सर्वे-सूची के बाक़ी उत्पादों को इसी नियम से दोबारा जाँच पाएँगे; और समझ पाएँगे कि \"योग्य\" का मतलब सिर्फ़ क़ानूनी नहीं, व्यावहारिक भी है।\n\n## 2. मुख्य बात\nहर उत्पाद ऑनलाइन नहीं बिकता — कुछ के लिए सफ़र लंबा है, कुछ के लिए यह रास्ता ही ग़लत है। एक-वाक्य बात — **हरा = आज से शुरू करो (टिकाऊ, सुरक्षित, आसान-पैकिंग); पीला = तैयारी के बाद (लाइसेंस, ख़ास पैकिंग, सावधानी चाहिए); लाल = ऑनलाइन कभी नहीं (ग़ैर-क़ानूनी, ख़तरनाक, या नियम-विरुद्ध) — रंग बदलते नहीं, तैयारी उत्पाद को हरे की ओर ले जा सकती है, पीले से आगे नहीं।**\n\n## हरा — आज से शुरू करने लायक़\nकपड़े, बर्तन, हस्तशिल्प, किताबें-स्टेशनरी, सूखा-राशन (चावल-दाल-मसाला पैक में), गहने-कॉस्मेटिक (सामान्य), खिलौने, इलेक्ट्रॉनिक-सामान (चार्जर, केबल), जूते-चप्पल — ये आम तौर पर बिना ख़ास लाइसेंस, सामान्य पैकिंग से, दिन-हफ़्ते ख़राब हुए बिना भेजे जा सकते हैं। पाठ-11 का सर्वे \"ढेर-1\" ज़्यादातर यहीं गिरेगा।\n\n## पीला — तैयारी के बाद\nखाने-पीने की चीज़ें (अचार, पापड़, मिठाई, मसाला) — FSSAI लाइसेंस चाहिए, ख़ास पैकिंग (हवा-नमी से बचाव), समाप्ति-तारीख़ लिखनी होती है (पाठ-30); दवा-सौंदर्य-प्रसाधन के कुछ भाग — अतिरिक्त लाइसेंस/नियम; बिजली-उपकरण के कुछ भाग — BIS निशान; बहुत नाज़ुक चीज़ें (काँच, मिट्टी के बर्तन) — ख़ास पैकिंग-हुनर चाहिए, नहीं तो टूट-रिटर्न में डूबेंगे। ये \"अभी नहीं\" नहीं हैं — तैयारी करके हरे की तरफ़ आते हैं; खंड-2 और 3 के आगे के पाठ यही तैयारी सिखाते हैं।\n\n## चित्र — तीन श्रेणी और तैयारी का रास्ता\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">हरा · पीला · लाल — उत्पाद कहाँ खड़ा है</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">तीर = तैयारी से रास्ता · लाल से कोई तीर नहीं निकलता</text>\n<rect x=\"40\" y=\"120\" width=\"220\" height=\"280\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"150\" y=\"155\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"bold\">🟢 हरा</text>\n<text x=\"150\" y=\"182\" text-anchor=\"middle\" font-size=\"16\">आज से शुरू</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"60\" y=\"215\">कपड़े · बर्तन</text><text x=\"60\" y=\"240\">हस्तशिल्प</text><text x=\"60\" y=\"265\">किताब-स्टेशनरी</text><text x=\"60\" y=\"290\">सूखा-राशन (पैक)</text><text x=\"60\" y=\"315\">गहने-कॉस्मेटिक</text><text x=\"60\" y=\"340\">खिलौने · जूते</text><text x=\"60\" y=\"365\">इलेक्ट्रॉनिक-सामान</text>\n</g>\n<rect x=\"290\" y=\"120\" width=\"220\" height=\"280\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"4\"/>\n<text x=\"400\" y=\"155\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"bold\">🟡 पीला</text>\n<text x=\"400\" y=\"182\" text-anchor=\"middle\" font-size=\"16\">तैयारी के बाद</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"310\" y=\"215\">खाना-पीना (FSSAI)</text><text x=\"310\" y=\"240\">अचार-पापड़-मिठाई</text><text x=\"310\" y=\"265\">दवा-सौंदर्य (कुछ)</text><text x=\"310\" y=\"290\">बिजली-उपकरण (BIS)</text><text x=\"310\" y=\"315\">नाज़ुक (काँच-मिट्टी)</text><text x=\"310\" y=\"345\">→ लाइसेंस+पैकिंग सीखो</text>\n</g>\n<rect x=\"540\" y=\"120\" width=\"220\" height=\"280\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"650\" y=\"155\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"bold\">🔴 लाल</text>\n<text x=\"650\" y=\"182\" text-anchor=\"middle\" font-size=\"16\">ऑनलाइन कभी नहीं</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"560\" y=\"215\">हथियार-पटाखे</text><text x=\"560\" y=\"240\">दवा (बिना नुस्ख़े)</text><text x=\"560\" y=\"265\">नशा-तंबाकू</text><text x=\"560\" y=\"290\">जानवर-पक्षी (ज़िंदा)</text><text x=\"560\" y=\"315\">जाली/नक़ली सामान</text><text x=\"560\" y=\"345\">प्रतिबंधित सूची</text>\n</g>\n<line x1=\"260\" y1=\"260\" x2=\"282\" y2=\"260\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><polygon points=\"290,260 274,250 274,270\" fill=\"#0B1F3A\"/>\n<text x=\"270\" y=\"245\" text-anchor=\"middle\" font-size=\"16\">पहले</text>\n<line x1=\"290\" y1=\"380\" x2=\"240\" y2=\"410\" stroke=\"#2E7D32\" stroke-width=\"4\"/><polygon points=\"234,414 244,398 254,412\" fill=\"#2E7D32\"/>\n<text x=\"265\" y=\"405\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">तैयारी</text>\n<rect x=\"60\" y=\"450\" width=\"680\" height=\"170\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"484\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">तीन सवाल — रंग तय करने के लिए</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"520\">1. क़ानूनी है? (कोई लाइसेंस-प्रतिबंध?) — नहीं तो लाल</text>\n<text x=\"90\" y=\"554\">2. कितने दिन टिकता है भेजने में? — घंटों में = quick-commerce या स्थानीय ही</text>\n<text x=\"90\" y=\"588\">3. पैक करके सुरक्षित भेजा जा सकता है? — नहीं तो पीला/लाल</text>\n</g>\n<rect x=\"60\" y=\"640\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"670\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">रंग बदलता नहीं, उत्पाद खिसकता है — तैयारी से पीला हरे की ओर</text>\n<text x=\"400\" y=\"697\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">लाल से कोई रास्ता नहीं — वहीं रुकना है</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## लाल — ऑनलाइन कभी नहीं\nहथियार-पटाखे, बिना डॉक्टर के नुस्ख़े वाली दवा, नशा-तंबाकू-जैसी चीज़ें, ज़िंदा जानवर-पक्षी (कुछ अपवाद अलग-अलग नियम से), जाली/नक़ली ब्रांड का सामान, हर मंच की अपनी \"प्रतिबंधित-सूची\" (पाठ-14 में सूची कहाँ मिलती है)। इन पर कोई तैयारी काम नहीं आती — यह कोर्स इनके लिए कोई रास्ता नहीं सिखाता। अगर आपकी सर्वे-सूची (पाठ-11) में कोई उत्पाद यहाँ गिरे, उसे \"ढेर-3, स्थायी\" में लिख दीजिए और आगे बढ़िए।\n\n## तीन सवाल — रंग तय करने का सादा तरीक़ा\nकिसी भी नए उत्पाद के लिए तीन सवाल पूछिए। **क़ानूनी?** — कोई लाइसेंस-प्रतिबंध रोकता तो नहीं (मंच की प्रतिबंधित-सूची पाठ-14 में)। **कितने दिन टिकता?** — घंटों में ख़राब हो जाए (ताज़ा दूध, गरम खाना) तो लंबी-दूरी की मार्केटप्लेस उपयुक्त नहीं, quick-commerce या स्थानीय-WhatsApp ही सही; दिन-हफ़्ते टिके तो हरा-पीला। **पैक करके सुरक्षित भेजा जा सकता?** — काँच-मिट्टी के बर्तन को ख़ास पैकिंग चाहिए (पाठ-234); न सीखी तो रिटर्न-टूटन में डूबेंगे। तीनों सवालों के जवाब \"हाँ-हाँ-हाँ\" = हरा; कहीं \"तैयारी चाहिए\" = पीला; कहीं \"नहीं, कभी नहीं\" = लाल।\n\n## अपने उत्पाद और सर्वे-सूची को दोबारा जाँचना\nपाठ-11 में जो तीन ढेर बनाए थे, वे अंदाज़े से थे — आज उन्हें इस पक्के तीन-सवाल नियम से दोबारा जाँचिए। कुछ \"ढेर-1\" वाले असल में \"पीला\" निकल सकते हैं (जैसे घर का अचार — FSSAI चाहिए, पर तैयारी करने लायक़); कुछ \"ढेर-3\" वाले शायद \"पीला\" ही हों, \"लाल\" नहीं। यह जाँच खंड-2 के आगे हर पाठ (फ़ोटो, कैटलॉग, लिस्टिंग) में उसी उत्पाद पर काम करने से पहले ज़रूरी है — ग़लत उत्पाद पर मेहनत मत डालिए।\n\n## हर खंड-9 से 14 में यह जाँच फिर आएगी\nयह हरा-पीला-लाल पहचान एक बार की चीज़ नहीं है — हर मार्केटप्लेस-खंड (9 Amazon, 10 Flipkart, 11 Meesho, 12 Quick-commerce, 13 JioMart/GeM, 14 ONDC) के शुरुआती पाठों में \"खाता बनाना/पात्रता\" वाला हिस्सा इसी सवाल को उस मंच के नाम से दोहराता है — \"क्या तुम्हारा सामान यहाँ चल सकता है?\" इसलिए आज की मेहनत आगे बार-बार समय बचाएगी; एक-एक मंच पर दोबारा शून्य से नहीं सोचना पड़ेगा, बस तीन सवाल दोहराने होंगे।\n\n## 3. आज का काम «काम-कार्ड»\nपाठ-11 की 20-उत्पाद सूची निकालिए। हर उत्पाद के लिए तीन-सवाल तालिका भरिए (क़ानूनी? कितने दिन टिकता? पैक-सुरक्षित?) और आख़िरी रंग (हरा/पीला/लाल) लिखिए। पुराने तीन-ढेर से आज के रंग-वर्गीकरण की तुलना कीजिए — कितने बदले, क्यों (एक-दो पंक्ति)। फिर अपने \"पहले उत्पाद\" (पाठ-11 में चुना) का रंग पक्का कीजिए — हरा है तो आगे बढ़िए; पीला है तो लिखिए कौन-सी तैयारी चाहिए और किस पाठ में सीखेंगे; लाल निकले तो दूसरा उत्पाद चुनिए (सूची से या नया)। जाँच-सूची: ☐ 20 उत्पादों का तीन-सवाल+रंग ☐ पुराने-नए ढेर की तुलना ☐ पहला-उत्पाद रंग पक्का ☐ ज़रूरत पड़ी तो नया उत्पाद चुना ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = 20 उत्पादों की तालिका पूरी, हर एक तीन सवाल+रंग; तुलना में ईमानदार अंतर लिखा; पहला-उत्पाद हरा (या पीला+तैयारी-योजना); लाल निकला उत्पाद आगे किसी पाठ में इस्तेमाल न हो। समय: 35 मिनट।\n\n## 5. सबूत\nसबूत-खाते में तालिका और पहले-उत्पाद के रंग-निर्णय की फ़ोटो। यह वर्गीकरण खंड-2 के बाक़ी पाठों (14-30) और खंड-9-11 (मार्केटप्लेस) में हर बार काम आएगा — \"यह उत्पाद इस मंच पर योग्य है?\" का पहला जवाब यहीं से।\n\n## 6. AI-सहायक\nAI से पूछिए — \"मेरा उत्पाद (नाम, संक्षिप्त विवरण) है — यह भारत में ऑनलाइन बेचने के लिए सामान्य तौर पर हरी, पीली या लाल श्रेणी में आता है, और क्यों?\" — जवाब को मंच की असली प्रतिबंधित-सूची (पाठ-14 की कड़ी) से मिलाइए, सिर्फ़ AI पर न रुकिए। दूसरा — \"पीली श्रेणी के (उत्पाद) के लिए आम तौर पर कौन-सा लाइसेंस चाहिए?\" — दिशा के लिए, पक्का सरकारी पेज से (पाठ-9)।\n\n## 7. आम ग़लती\nपहली — \"मेरा गाँव का उत्पाद तो हमेशा से बिकता है\" कहकर लाइसेंस को नज़रअंदाज़ करना — मंच पर बात अलग है, पकड़े जाने पर खाता बंद। दूसरी — पीले को लाल समझकर छोड़ देना — ज़्यादातर पीले उत्पाद तैयारी से हरे बन जाते हैं, यही इस कोर्स की सीख है। तीसरी — नाज़ुक सामान को बिना पैकिंग-हुनर सीधे हरे में डाल देना — पहला ही रिटर्न मुनाफ़ा खा जाता है। चौथी — किसी और मंच पर बिकते देखकर \"यह तो हरा ही होगा\" मान लेना — हर मंच की अपनी प्रतिबंधित-सूची, ख़ुद जाँचिए।\n\n## 8. सुरक्षा-पत्रक\nलाल-श्रेणी का सामान बेचने की कोशिश सिर्फ़ खाता-बंद नहीं, क़ानूनी नुक़सान भी ला सकती है — यह कोर्स इसमें कोई मदद नहीं देता। पीली श्रेणी में लाइसेंस के बिना शुरू करना — मंच पकड़ते ही रोकता है, कभी-कभी ज़ुर्माना; पहले लाइसेंस, फिर लिस्टिंग। सेवा-सहायक: दुकानदार का उत्पाद लाल निकले तो साफ़ मना कीजिए, चाहे पैसा मिल रहा हो — यह आपकी साख की रक्षा है (खंड-21)। 18 से कम: यह वर्गीकरण अभ्यास में सीखिए, असली पीली/लाल श्रेणी का कोई सामान न छुएँ।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। हरा-पीला-लाल ACS का सरल वर्गीकरण; असली प्रतिबंधित/लाइसेंस-सूची हर मंच व सरकार की अपनी। 📎 मूल-कोर्स-कड़ी: Amazon की \"Restricted products\" सूची — https://sell.amazon.in/seller-blog/restricted-products (या Seller University के भीतर) · FSSAI लाइसेंस — https://foscos.fssai.gov.in — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=product-eligibility · platform=multi · level=F,O · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं हरा-पीला-लाल तीन श्रेणी और तीन सवाल बता सकता हूँ।\n- [ ] मैंने अपनी 20-उत्पाद सूची को रंग-वर्गीकरण से दोबारा जाँचा है।\n- [ ] मैं जानता हूँ कि पीला तैयारी से हरा बनता है, लाल से कोई रास्ता नहीं।\n- [ ] मेरा पहला उत्पाद हरा है या उसकी पीली-तैयारी योजना बनी है।\n- [ ] मैं जानता हूँ कि प्रतिबंधित-सूची हर मंच की अपनी होती है और जाँचनी पड़ती है।",
 "14": "═\n# पाठ-14: प्रतिबंधित व जोखिम वाले उत्पाद — जो कभी नहीं\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर F/O · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nपाठ-13 का \"लाल\" रंग यहाँ गहराई से खुलता है। पाठ के बाद आप तीन बातें कर पाएँगे — किसी भी मंच की प्रतिबंधित-सूची कहाँ और कैसे खोजी जाती है, बता पाएँगे; पाँच सबसे आम \"जोखिम वाले लगते पर असल में योग्य\" उत्पादों की पहचान (ग़लतफ़हमी दूर) कर पाएँगे; और यह समझ पाएँगे कि \"प्रतिबंधित\" और \"जोखिम-भरा पर अनुमति-योग्य\" में फ़र्क़ क्या है।\n\n## 2. मुख्य बात\nहर मंच की अपनी प्रतिबंधित-सूची होती है, और कुछ बातें लगभग सब जगह एक-सी। एक-वाक्य बात — **प्रतिबंधित का मतलब मंच ने साफ़ मना किया है — कोशिश करने पर खाता ही बंद; जोखिम-भरा का मतलब बिक तो सकता है पर अतिरिक्त नियम-कड़ाई चाहिए — दोनों को गड्डमड्ड करना सबसे बड़ी ग़लती है।**\n\n## आम प्रतिबंधित सूची — जो लगभग हर मंच पर मना\nहथियार, गोला-बारूद, विस्फोटक (पटाखे भी अक्सर सीमित/मना); नशीले पदार्थ, कुछ जगह तंबाकू-उत्पाद; बिना नुस्ख़े की दवाइयाँ, कुछ चिकित्सा-उपकरण बिना लाइसेंस; जानवरों के अंग, संरक्षित जीव-जंतु; जाली मुद्रा, चोरी का सामान, नक़ली/जाली ब्रांड (असली जैसा दिखने वाला डुप्लिकेट); अश्लील सामग्री; मानव अंग/रक्त; कुछ रसायन (ख़तरनाक, ज्वलनशील बिना लाइसेंस)। हर मंच अपने पेज पर पूरी सूची देता है (कड़ी नीचे) — यह ACS की सामान्य झलक है, अंतिम फ़ैसला मंच के पेज से।\n\n## चित्र — प्रतिबंधित बनाम जोखिम-भरा-पर-योग्य\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">प्रतिबंधित बनाम जोखिम-भरा-पर-योग्य</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">बाएँ कभी नहीं · दाएँ नियम मानकर हाँ · सोना = सबसे आम ग़लतफ़हमी</text>\n<rect x=\"40\" y=\"120\" width=\"330\" height=\"330\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"205\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">🔴 प्रतिबंधित — कभी नहीं</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"60\" y=\"195\">हथियार-गोला-बारूद-पटाखे</text>\n<text x=\"60\" y=\"225\">नशीले पदार्थ</text>\n<text x=\"60\" y=\"255\">बिना-नुस्ख़े दवा</text>\n<text x=\"60\" y=\"285\">जानवरों के अंग</text>\n<text x=\"60\" y=\"315\">जाली मुद्रा-चोरी का सामान</text>\n<text x=\"60\" y=\"345\">नक़ली/जाली ब्रांड</text>\n<text x=\"60\" y=\"375\">अश्लील सामग्री</text>\n<text x=\"60\" y=\"405\">कोशिश = तुरंत खाता-बंद</text>\n</g>\n<rect x=\"430\" y=\"120\" width=\"330\" height=\"330\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"595\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">🟡 जोखिम-भरा — नियम मानकर हाँ</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"450\" y=\"195\">दूसरे हाथ का/पुराना सामान → साफ़ बताओ</text>\n<text x=\"450\" y=\"230\">हस्तनिर्मित हथियार जैसा दिखने वाला खिलौना → माप-सीमा</text>\n<text x=\"450\" y=\"265\">हर्बल/आयुर्वेदिक → दावा-सीमा, लाइसेंस</text>\n<text x=\"450\" y=\"300\">धार्मिक/जाति से जुड़ा सामान → सम्मान-नियम</text>\n<text x=\"450\" y=\"335\">आयातित ब्रांड जैसा नाम → असली-नक़ली स्पष्ट</text>\n<text x=\"450\" y=\"375\">= नियम मानकर बिक सकता है</text>\n</g>\n<rect x=\"60\" y=\"480\" width=\"680\" height=\"140\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"514\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">प्रतिबंधित-सूची कैसे खोजें (हर मंच पर)</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"550\">सेलर-ऐप → Help/Policy → \"Restricted/Prohibited Products\"</text>\n<text x=\"90\" y=\"584\">अपनी श्रेणी टाइप करके खोजो — \"यह चलेगा?\" का सीधा जवाब अक्सर वहीं</text>\n<text x=\"90\" y=\"614\">शक हो तो मंच के सहायता-चैट से पूछो, अंदाज़ा मत लगाओ</text>\n</g>\n<rect x=\"60\" y=\"640\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"670\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">डर से \"सब जोखिम-भरा है\" मत मानो — ज़्यादातर सामान बिना दिक़्क़त बिकता है</text>\n<text x=\"400\" y=\"697\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">बस यह सूची एक बार जाँच लो, फिर बेफ़िक्र</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## पाँच आम ग़लतफ़हमियाँ — असल में योग्य\n**दूसरे हाथ का/पुराना सामान** — साफ़-साफ़ \"used/second-hand\" बताकर कई मंच अनुमति देते हैं (श्रेणी-वार जाँचें), छिपाना ही मना है, बेचना नहीं। **हथियार-जैसा दिखने वाला खिलौना (तलवार-बंदूक-खिलौना)** — रंग-आकार-सामग्री की सीमा मानकर अक्सर योग्य। **हर्बल/आयुर्वेदिक उत्पाद** — \"बीमारी ठीक करता है\" जैसा दावा किए बिना, सही लाइसेंस के साथ योग्य। **धार्मिक/सांस्कृतिक सामान** (मूर्ति, तस्वीर, धागा) — सम्मान से प्रस्तुत करने पर योग्य, अपमानजनक उपयोग/तस्वीर नहीं। **किसी मशहूर ब्रांड जैसा नाम/डिज़ाइन** — \"inspired by\" कहकर भी बेचना जोखिम है; अपना अलग नाम-डिज़ाइन ही सुरक्षित (ब्रांड-नक़ल प्रतिबंधित के करीब है)। यही सूची पाठ-13 के \"पीला\" वर्गीकरण को और बारीक करती है।\n\n## प्रतिबंधित-सूची कैसे खोजें — हर मंच पर\nहर मंच की सेलर-ऐप/वेबसाइट में एक \"Prohibited/Restricted Products Policy\" पेज होता है — Help या Policy खंड में। वहाँ अपनी श्रेणी टाइप करके खोजिए; न मिले तो मंच के सहायता-चैट/हेल्पलाइन से सीधे पूछिए, अंदाज़ा न लगाएँ। यह जाँच पाठ-7 के \"9-कदम ऑडिट\" का कदम-2 (पात्रता) ही है — नए मंच पर जाने से पहले यही सबसे पहला काम। एक बार जाँच लेने के बाद हर उत्पाद के लिए बार-बार डरने की ज़रूरत नहीं — यह एक स्थायी जाँच है, हर बार नई नहीं (जब तक मंच नीति न बदले — इसलिए यह पाठ MEDIUM-volatility)।\n\n## प्रतिबंधित-सूची व Global-South\nअगर आप भविष्य में किसी दूसरे देश के मंच (Daraz, Jumia — खंड-22) पर भी काम करेंगे, याद रखिए — प्रतिबंधित-सूची की सोच एक-सी है (हथियार-नशा-नक़ली सब जगह मना), पर सटीक सूची और लाइसेंस-नाम हर देश में अलग। आज जो 9-कदम ऑडिट (पाठ-7) और यह प्रतिबंधित-जाँच का तरीक़ा सीखा, वही तरीक़ा किसी भी देश के किसी भी मंच पर दोहराया जा सकता है — बस स्थानीय पेज ढूँढना पड़ेगा।\n\n## एक असली उदाहरण — एक \"मामूली\" चीज़ जो लाल थी\nएक दुकानदार ने सोचा घर की बनी हर्बल-दवा \"मामूली\" है, लिस्ट कर दी — मंच ने लिस्टिंग हटाई और चेतावनी दी; दूसरी बार खाता जाता। उसी हफ़्ते उसने वही चीज़ \"पीले\" रास्ते से देखी — लाइसेंस/पंजीकरण की शर्तें पढ़ीं, \"दवा\" शब्द हटाकर पंजीकृत हर्बल-उत्पाद के नियम में आया, तब लिस्ट किया। सबक — \"मामूली\" आपकी नज़र में है, \"प्रतिबंधित\" मंच की सूची में; सूची पहले, अंदाज़ा बाद (पाठ-13-14 की छलनी हर नए उत्पाद पर)।\n\n## सूची कहाँ देखें, कितनी बार\nहर मंच का \"Restricted/Prohibited products\" पेज (सेलर-हेल्प में) — पहली बार पूरा पढ़ो, फिर हर नए उत्पाद-वर्ग पर उसी पेज पर खोज; तिमाही में एक बार पूरा पेज दोबारा (सूची बदलती है, पाठ-319)। मंच की सूची के ऊपर देश का क़ानून — जो क़ानूनन नहीं बिक सकता, वह मंच की सूची में न भी हो तो नहीं (पाठ-63-64 की सीमा)।\n\n## 3. आज का काम «काम-कार्ड»\nपाठ-13 में जो उत्पाद \"पीला\" या \"शक में\" निकले, उनके लिए एक मंच (जिस पर आप बेचना सोच रहे हैं) की आधिकारिक Prohibited-Products नीति खोलिए (कड़ी स्रोत में) और अपने उत्पाद को खोजकर देखिए वह वहाँ है या नहीं — कॉपी में लिखिए। पाँच ग़लतफ़हमियों में से जो आपकी सूची से मिलती हो, उसे चिह्नित कीजिए और लिखिए कैसे \"साफ़-साफ़ बताकर\" योग्य बनेगी। अगर सच में कोई उत्पाद प्रतिबंधित निकले, उसे पाठ-13 के अपने वर्गीकरण में \"लाल-पक्का\" लिखकर आगे कभी उस पर काम न करने का फ़ैसला दर्ज कीजिए। जाँच-सूची: ☐ एक मंच की नीति खोली ☐ अपने उत्पाद खोजे ☐ 5 ग़लतफ़हमी से मिलान ☐ प्रतिबंधित मिलने पर फ़ैसला दर्ज ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = मंच की असली नीति-पेज से जाँच (AI/अंदाज़ से नहीं); हर \"पीला/शक\" उत्पाद का साफ़ नतीजा (योग्य-नियम-सहित / प्रतिबंधित-कभी नहीं); कम-से-कम एक ग़लतफ़हमी अपने उदाहरण से समझी। समय: 30 मिनट।\n\n## 5. सबूत\nसबूत-खाते में नीति-पेज का स्क्रीनशॉट और अपना नतीजा। यह जाँच खंड-9-14 (हर मार्केटप्लेस) में \"आम अस्वीकृति\" पाठों से जुड़ेगी — वहाँ आप देखेंगे कि प्रतिबंधित-कोशिश ही सबसे बड़ी अस्वीकृति का कारण है।\n\n## 6. AI-सहायक\nAI से पूछिए — \"(मंच) पर (उत्पाद-श्रेणी) बेचना है — यह आम तौर पर योग्य है या प्रतिबंधित, और क्या अतिरिक्त नियम लगते हैं?\" — पर जवाब को मंच की असली नीति-पेज से मिलाइए (AI पुरानी/ग़लत सूची बता सकता है — यह HIGH नहीं पर फिर भी बदलती चीज़ है)। दूसरा — \"मेरा उत्पाद किसी मशहूर ब्रांड जैसा दिखता है, क्या यह जोखिम है?\" — AI से समझ लीजिए, अंतिम फ़ैसला अपना नाम-डिज़ाइन रखने का ही सुरक्षित है।\n\n## 7. आम ग़लती\nपहली — \"छोटा सामान है, कोई नहीं पकड़ेगा\" सोचकर प्रतिबंधित बेचने की कोशिश — मंच की मशीन-जाँच अक्सर पहले ही पकड़ लेती है, और मानव-रिपोर्ट भी। दूसरी — दूसरे हाथ के सामान को \"नया\" बताकर बेचना — यह प्रतिबंधित से भी बुरा (धोखा, खंड-20)। तीसरी — हर्बल-उत्पाद पर \"कैंसर ठीक करे\" जैसा झूठा दावा — यह उत्पाद को योग्य से प्रतिबंधित की ओर धकेलता है। चौथी — किसी और सेलर को उसी श्रेणी में बेचते देखकर बिना अपनी जाँच के कूद पड़ना।\n\n## 8. सुरक्षा-पत्रक\nप्रतिबंधित सामान बेचने की कोशिश सिर्फ़ खाता-बंद नहीं करती — कुछ श्रेणियों (हथियार, नशा, दवा) में यह क़ानूनी अपराध भी है; ACS किसी भी रूप में इसमें मदद नहीं करता और न सिखाता है कि \"कैसे बच निकलें\"। नक़ली-ब्रांड बेचना ख़रीदार और असली ब्रांड-मालिक दोनों के साथ धोखा है। सेवा-सहायक: दुकानदार अगर प्रतिबंधित सामान बेचने को कहे, साफ़ मना कीजिए और कारण समझाइए — यही आपकी सेवा की साख है। 18 से कम: यह पाठ सिर्फ़ समझ के लिए; प्रतिबंधित-सूची में कुछ भी छूना, खोजना, \"आज़माना\" नहीं।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। सूची सामान्य झलक है; हर मंच की अपनी पूरी, बदलती सूची आधिकारिक पेज पर देखें। 📎 मूल-कोर्स-कड़ी: Amazon Restricted Products Policy व Seller University (Policy section) — https://sell.amazon.in — Flipkart और Meesho के seller-help में भी \"Prohibited Items\" खंड — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=prohibited-items · platform=multi · level=F,O · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं आम प्रतिबंधित सूची (हथियार, नशा, बिना-नुस्ख़े दवा आदि) बता सकता हूँ।\n- [ ] मैंने एक मंच की असली नीति-पेज पर अपने उत्पाद जाँचे हैं।\n- [ ] मैं प्रतिबंधित और जोखिम-भरा-पर-योग्य का फ़र्क़ बता सकता हूँ।\n- [ ] मैं पाँच आम ग़लतफ़हमियों में से कम-से-कम दो उदाहरण बता सकता हूँ।\n- [ ] मैं जानता हूँ कि प्रतिबंधित-कोशिश खाता-बंद और क़ानूनी नुक़सान दोनों ला सकती है।",
 "15": "═\n# पाठ-15: दुकानदार से सहमति व उत्पाद-जानकारी फ़ॉर्म\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर F/O · रास्ता B · volatility LOW)*\n\n## 1. उद्देश्य\nयह पाठ ख़ासकर सेवा-सहायक (रास्ता-B) के लिए है — पर अपनी दुकान वाले (रास्ता-A) भी इसे अपनी दुकान के लिए हल्के रूप में करेंगे। किसी और के उत्पाद की फ़ोटो-जानकारी लेने से पहले क्या तय करना चाहिए, यह पाठ बताता है। पाठ के बाद आप तीन बातें कर पाएँगे — दुकानदार से सहमति लेने का सही, विनम्र तरीक़ा अपना पाएँगे; उत्पाद-जानकारी फ़ॉर्म भर पाएँगे जिससे आगे की फ़ोटो-लिस्टिंग में कोई सवाल न रह जाए; और समझ पाएँगे कि यह काग़ज़ी सहमति क्यों दोनों (सहायक व दुकानदार) को बचाती है।\n\n## 2. मुख्य बात\n\"मैं फ़ोटो खींच लूँ?\" कहकर मोबाइल उठा लेना काफ़ी नहीं — क्या दिखेगा, कहाँ जाएगा, कब तक रहेगा, यह साफ़ होना चाहिए। एक-वाक्य बात — **हर नए उत्पाद/दुकान पर काम शुरू करने से पहले एक छोटा फ़ॉर्म — दुकानदार का नाम-सहमति, उत्पाद की सच्ची जानकारी, फ़ोटो कहाँ इस्तेमाल होगी — दोनों के हस्ताक्षर (या WhatsApp-संदेश की पुष्टि) — यही एक काग़ज़ पूरे खंड-2 के काम को झगड़े से बचाता है।**\n\n## सहमति माँगने का सही तरीक़ा\nपाठ-11 में सर्वे के लिए विनम्र पहला वाक्य सीखा था; अब असली काम के लिए एक कदम आगे। बताइए — मैं क्या करूँगा (फ़ोटो, कैटलॉग, लिस्टिंग), कहाँ दिखेगा (WhatsApp/मंच का नाम), कब तक (एक बार या चलता काम), और बदले में क्या (सीखने का अभ्यास है तो मुफ़्त कहिए; सेवा है तो दाम — खंड-21)। दुकानदार के सवालों का ईमानदार जवाब दीजिए — \"मैं अभी सीख रहा हूँ\" कहने में शर्म नहीं, यह भरोसा बढ़ाता है। \"हाँ\" मिले तो फ़ॉर्म भरिए; \"नहीं\" मिले तो धन्यवाद कहकर आगे बढ़िए — ज़बरदस्ती कभी नहीं।\n\n## चित्र — सहमति-फ़ॉर्म का ढाँचा\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">उत्पाद-जानकारी व सहमति-फ़ॉर्म — एक पन्ना</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सोना = हस्ताक्षर/पुष्टि वाला हिस्सा · बाक़ी जानकारी</text>\n<rect x=\"60\" y=\"120\" width=\"680\" height=\"480\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"155\" font-weight=\"bold\" font-size=\"18\">भाग-अ: दुकान/दुकानदार</text>\n<text x=\"90\" y=\"185\">नाम · दुकान-नाम · इलाका · फ़ोन (निजी रिकॉर्ड में, सार्वजनिक नहीं)</text>\n<text x=\"90\" y=\"225\" font-weight=\"bold\" font-size=\"18\">भाग-ब: उत्पाद की सच्ची जानकारी</text>\n<text x=\"90\" y=\"255\">नाम · सामग्री/बनावट · नाप-वज़न-रंग-वेरिएशन</text>\n<text x=\"90\" y=\"283\">दाम (न्यूनतम-अधिकतम) · कितने दिन टिकता · बनाने की जगह</text>\n<text x=\"90\" y=\"323\" font-weight=\"bold\" font-size=\"18\">भाग-स: फ़ोटो-अनुमति</text>\n<text x=\"90\" y=\"353\">फ़ोटो कहाँ दिखेगी (WhatsApp/मंच-नाम) · कब तक</text>\n<text x=\"90\" y=\"381\">दुकानदार/परिवार का चेहरा फ़ोटो में: हाँ/नहीं</text>\n<rect x=\"90\" y=\"420\" width=\"620\" height=\"90\" rx=\"10\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"2\"/>\n<text x=\"110\" y=\"448\" font-weight=\"bold\" font-size=\"18\">भाग-द: सहमति</text>\n<text x=\"110\" y=\"476\">\"मैं ऊपर की जानकारी सही होने की पुष्टि करता/करती हूँ,</text>\n<text x=\"110\" y=\"500\">और फ़ोटो-उपयोग की अनुमति देता/देती हूँ\"</text>\n<text x=\"90\" y=\"540\">हस्ताक्षर/अँगूठा _____ तारीख़ _____ (या WhatsApp-संदेश की स्क्रीनशॉट)</text>\n<text x=\"90\" y=\"570\">सहायक का नाम व हस्ताक्षर _____</text>\n</g>\n<rect x=\"60\" y=\"620\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"650\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#2E7D32\">WhatsApp-संदेश भी काग़ज़ जितना ही मान्य</text>\n<text x=\"400\" y=\"677\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">\"हाँ, आप फ़ोटो ले सकते हैं, इस्तेमाल कर सकते हैं\" — स्क्रीनशॉट सहेजो</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## उत्पाद-जानकारी — सच्ची, पूरी, नाप-सहित\nफ़ॉर्म का दूसरा हिस्सा सबसे ज़रूरी है — यहीं आगे की लिस्टिंग की नींव बनती है। नाम (जैसे दुकानदार/स्थानीय भाषा में बुलाते हैं), सामग्री/बनावट (सूती/मिट्टी/लकड़ी), नाप-वज़न-रंग और वेरिएशन (कितने रंग-साइज़ में उपलब्ध), दाम की सीमा (कम-से-कम कितने में, बदलाव कब), कितने दिन टिकता (पाठ-13 का जवाब यहीं दर्ज), बनाने की जगह (गाँव-शहर — कहानी बनाने में काम आता है, पाठ-18)। यहाँ दुकानदार जो बताए, वही लिखिए — अंदाज़ा या \"अच्छा लगेगा\" वाली जानकारी नहीं; यह आगे \"AI reality-check\" (पाठ-28) की पहली नींव है — ग़लत नींव पर सही जाँच नहीं हो सकती।\n\n## फ़ोटो-अनुमति — कहाँ, कब तक, चेहरा हाँ/नहीं\nयह हिस्सा सुरक्षा-नियम (पाठ-10) से सीधे जुड़ता है। साफ़ लिखिए — फ़ोटो कहाँ दिखेगी (सिर्फ़ अभ्यास/सबूत-खाते में, या असली WhatsApp/मंच पर), कब तक (एक बार का अभ्यास, या चलता काम — तब महीने-दर-महीने का हिसाब खंड-21 में), और दुकानदार/परिवार का चेहरा फ़ोटो में आएगा या नहीं (आम तौर पर \"नहीं\" ही श्रेष्ठ — उत्पाद बोले, चेहरा नहीं)। यह वही अनुमति है जो पाठ-11 के सर्वे में मौखिक थी; अब लिखित/स्क्रीनशॉट-सहित, क्योंकि अब असली उपयोग शुरू हो रहा है।\n\n## यह काग़ज़ किसे बचाता है\nदो लोगों को। दुकानदार को — अगर फ़ोटो कहीं ग़लत जगह दिख जाए, वह दिखा सकता है \"मैंने यह अनुमति नहीं दी थी।\" सहायक को — अगर दुकानदार बाद में मुकर जाए (\"मैंने कभी हाँ नहीं कहा\"), स्क्रीनशॉट/हस्ताक्षर सबूत है। और सबसे बड़ी बात — यह आदत आपको हर आगे के काम में पेशेवर दिखाती है; जो सहायक पहले दिन यह काग़ज़ माँगता है, दुकानदार उसी पर सबसे ज़्यादा भरोसा करता है (व्यवहार-नैतिकता, खंड-18/20)।\n\n## एक असली उदाहरण — एक फ़ॉर्म जिसने दो झगड़े रोके\nसेवा-सहायक ने दुकानदार से बिना फ़ॉर्म काम शुरू किया — बाद में दुकानदार बोला \"मैंने अपनी दुकान की फ़ोटो Facebook पर डालने को कहा ही नहीं\"। दूसरा झगड़ा — उत्पाद के \"गुण\" सहायक ने अपनी समझ से लिखे, दुकानदार बोला \"यह तो सूती नहीं, मिश्रित है\"। एक-पन्ने का फ़ॉर्म (सहमति + सच्ची जानकारी + फ़ोटो कहाँ जाएगी) दोनों को पहले दिन रोक देता। फ़ॉर्म शक नहीं, साझा-याददाश्त है — और यही पाठ-28 के reality-check का \"मूल-फ़ॉर्म\" है।\n\n## फ़ॉर्म की तीन पंक्तियाँ जो हमेशा भरी हों\n(1) \"मैं (नाम) अपने उत्पाद (नाम) की जानकारी व फ़ोटो (कहाँ-कहाँ) पर उपयोग की अनुमति देता/देती हूँ — तारीख़, हस्ताक्षर/'हाँ' संदेश\"; (2) उत्पाद की सच्ची जानकारी दुकानदार के शब्दों में — कपड़ा/सामग्री, नाप, दाम-सीमा, क्या नहीं है (जैसे \"वाटरप्रूफ़ नहीं\"); (3) \"जो यहाँ नहीं लिखा, वह लिस्टिंग में नहीं जाएगा\" — यह पंक्ति AI-गढ़ावट (पाठ-28) पर पहला ताला है।\n\n## 3. आज का काम «काम-कार्ड»\nपाठ-11 में चुने अपने पहले उत्पाद (और दुकानदार) के लिए यह फ़ॉर्म Word/कॉपी में बनाइए — चारों भाग (दुकान, उत्पाद, फ़ोटो-अनुमति, सहमति)। दुकानदार के पास वापस जाइए (या अगर वह आपकी अपनी दुकान है तो ख़ुद भरिए), भाग-ब की जानकारी उनसे पूछकर सच्ची भरिए, भाग-स पर साथ में तय कीजिए, और भाग-द पर हस्ताक्षर/अँगूठा लीजिए या WhatsApp पर \"हाँ\" का संदेश लेकर स्क्रीनशॉट सहेजिए। अगर दुकानदार का फ़ोन-नंबर पहले नहीं लिया था, अब विनम्रता से माँगिए (निजी रिकॉर्ड के लिए)। जाँच-सूची: ☐ फ़ॉर्म बना (4 भाग) ☐ उत्पाद-जानकारी सच्ची-पूरी भरी ☐ फ़ोटो-अनुमति साफ़ ☐ हस्ताक्षर/WhatsApp-पुष्टि ☐ फ़ोटो सबूत-खाते में (फ़ॉर्म की, दुकानदार की नहीं)।\n\n## 4. नाप\nसफल = फ़ॉर्म के चारों भाग भरे; उत्पाद-जानकारी में कोई ख़ाली/अंदाज़ा-खाना नहीं (जो न पता चला, \"पता नहीं\" लिखा, गढ़ा नहीं); सहमति हस्ताक्षर या स्क्रीनशॉट-सहित; फ़ोटो-अनुमति में चेहरा हाँ/नहीं साफ़। समय: 30 मिनट (दुकानदार से मिलने का समय अलग)।\n\n## 5. सबूत\nसबूत-खाते में भरे फ़ॉर्म की फ़ोटो और सहमति का स्क्रीनशॉट/हस्ताक्षर। यही फ़ॉर्म पाठ-16-30 (फ़ोटो, कैटलॉग, लिस्टिंग) में बार-बार खुलेगा — हर बार जब कोई सवाल आए (\"दाम क्या रखूँ?\", \"कितने रंग हैं?\"), पहले इसी फ़ॉर्म में देखिए, दुकानदार को दोबारा तंग करने से पहले।\n\n## 6. AI-सहायक\nAI से पूछिए — \"छोटे दुकानदार से उसके उत्पाद की फ़ोटो-जानकारी लेने के लिए एक सादा, विनम्र सहमति-फ़ॉर्म — हिंदी में, 4 भाग\" — मसौदा लीजिए, अपनी बोली में सुधारिए (पाठ-207 के AI-ढाँचा नियम की तरह — मसौदा AI का, शब्द अपने)। दूसरा — \"दुकानदार से जानकारी माँगते समय कौन-से 5 सवाल सबसे ज़रूरी हैं?\" — अपने भाग-ब से मिलाइए। दुकानदार का असली नाम-फ़ोन AI को कभी नहीं।\n\n## 7. आम ग़लती\nपहली — मौखिक \"हाँ\" पर ही फ़ोटो खींचकर आगे बढ़ जाना, फ़ॉर्म कभी नहीं भरना — बाद में सवाल उठे तो कोई सबूत नहीं। दूसरी — उत्पाद-जानकारी ख़ुद अंदाज़ से भर लेना (\"शायद सूती होगा\") — यही आगे झूठी लिस्टिंग बन जाती है। तीसरी — फ़ोटो-अनुमति में \"कब तक\" न पूछना — छह महीने बाद दुकानदार पूछे \"मेरी फ़ोटो अभी क्यों है\" तो जवाब नहीं। चौथी — दुकानदार/परिवार का चेहरा फ़ोटो में शामिल कर लेना बिना सोचे — डिफ़ॉल्ट \"नहीं\" रखिए।\n\n## 8. सुरक्षा-पत्रक\nफ़ॉर्म में लिखी दुकानदार की निजी जानकारी (फ़ोन, पूरा नाम) सिर्फ़ आपके निजी रिकॉर्ड में — सबूत-खाते के सार्वजनिक/साझा हिस्से में नहीं। सहमति-फ़ॉर्म ख़ुद दुकानदार को भी एक प्रति दीजिए (फ़ोटो खींचकर उन्हें भेज दें) — यह पारदर्शिता है। अगर दुकानदार बाद में \"अब हटा दो\" कहे, तुरंत मानिए — फ़ोटो/लिस्टिंग हटाना अनुमति वापसी का हक़ है, बहस नहीं। 18 से कम: यह फ़ॉर्म अभ्यास में परिवार/परिचित दुकान के लिए, अभिभावक-साथ; असली सेवा-सौदा 18+।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। सहमति-फ़ॉर्म ACS का अपना साँचा — किसी मंच का नियम नहीं, पर DPDP (भारत के डेटा-सुरक्षा क़ानून) की भावना पर आधारित। 📎 मूल-कोर्स-कड़ी: DPDP अधिनियम की सामान्य समझ — https://www.meity.gov.in (Digital Personal Data Protection Act) — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=consent-and-data-form · platform=none · level=F,O · path=B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैंने सहमति व उत्पाद-जानकारी फ़ॉर्म के चारों भाग बनाए हैं।\n- [ ] मैंने असली दुकानदार से सच्ची जानकारी लेकर फ़ॉर्म भरा है।\n- [ ] मेरी फ़ोटो-अनुमति (कहाँ, कब तक, चेहरा हाँ/नहीं) साफ़ है।\n- [ ] मेरे पास हस्ताक्षर या WhatsApp-पुष्टि का सबूत है।\n- [ ] मैं जानता हूँ कि दुकानदार \"हटाओ\" कहे तो तुरंत मानना है।",
 "16": "═\n# पाठ-16: मोबाइल से उत्पाद-फ़ोटो — पाँच कोण, सफ़ेद पृष्ठभूमि, रोशनी\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर F/O · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nसहमति-फ़ॉर्म तैयार है (पाठ-15) — अब असली काम, फ़ोटो। ऑनलाइन बिक्री में फ़ोटो ही आपकी \"दुकान की खिड़की\" है — ग्राहक हाथ में उठाकर नहीं देख सकता, सिर्फ़ फ़ोटो से भरोसा करता है। पाठ के बाद आप तीन बातें कर पाएँगे — किसी भी उत्पाद की पाँच-कोण फ़ोटो बना पाएँगे; सफ़ेद पृष्ठभूमि और सही रोशनी का इंतज़ाम बिना महँगे सामान के कर पाएँगे; और यह समझ पाएँगे कि यह फ़ोटो-आदत हर मंच (WhatsApp से Amazon तक) पर एक-सी काम आती है — यह इस पाठ के core_skill की ताक़त है।\n\n## 2. मुख्य बात\nअच्छी फ़ोटो महँगे कैमरे से नहीं, सही रोशनी और सही तरीक़े से बनती है। एक-वाक्य बात — **हर उत्पाद की पाँच फ़ोटो चाहिए — सामने, बग़ल, ऊपर से, नज़दीक़ (बनावट दिखे), और उपयोग में — दिन की रोशनी में खिड़की के पास, सफ़ेद कपड़े/काग़ज़ के ऊपर, फ़ोन को स्थिर रखकर — यह एक तरीक़ा हर मंच पर, हर उत्पाद पर एक-सा चलता है।**\n\n## पाँच कोण — क्या और क्यों\n**1. सामने से (Front)** — जो ग्राहक सबसे पहले देखता है, पूरी लिस्टिंग की \"मुख्य फ़ोटो\" यही बनती है। **2. बग़ल से (Side)** — गहराई, मोटाई, ऊँचाई का अंदाज़ा; कपड़े में साइड-सिलाई, बर्तन में गहराई। **3. ऊपर से (Top)** — पूरा फैलाव, ढक्कन-मुँह, पैटर्न ऊपर से कैसा। **4. नज़दीक़ (Close-up)** — बनावट, सिलाई, बुनाई, धातु की चमक — यही फ़ोटो \"यह असली/अच्छी क्वालिटी है\" का भरोसा देती है। **5. उपयोग में (In-use/lifestyle)** — कोई इसे पहने/इस्तेमाल करे (चेहरा हो तो अनुमति-सहित, या हाथ-भर दिखे), या सामान के बगल में कोई नाप की चीज़ (सिक्का, स्केल) रखकर आकार का अंदाज़ा। पाँचों मिलकर ग्राहक को वही भरोसा देती हैं जो दुकान में हाथ में उठाकर मिलता।\n\n## चित्र — पाँच कोण और रोशनी का इंतज़ाम\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">पाँच कोण — एक उत्पाद, पाँच नज़र</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सोना = मुख्य फ़ोटो बनने वाला कोण</text>\n<g font-size=\"16\" fill=\"#0B1F3A\" text-anchor=\"middle\">\n<rect x=\"40\" y=\"120\" width=\"135\" height=\"130\" rx=\"10\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"107\" y=\"200\" font-size=\"30\">◼</text><text x=\"107\" y=\"245\" font-weight=\"bold\">1 सामने</text>\n<rect x=\"195\" y=\"120\" width=\"135\" height=\"130\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"262\" y=\"200\" font-size=\"30\">▤</text><text x=\"262\" y=\"245\">2 बग़ल</text>\n<rect x=\"350\" y=\"120\" width=\"135\" height=\"130\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"417\" y=\"200\" font-size=\"30\">▦</text><text x=\"417\" y=\"245\">3 ऊपर से</text>\n<rect x=\"505\" y=\"120\" width=\"135\" height=\"130\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"572\" y=\"200\" font-size=\"24\">🔍</text><text x=\"572\" y=\"245\">4 नज़दीक़</text>\n<rect x=\"660\" y=\"120\" width=\"105\" height=\"130\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"712\" y=\"200\" font-size=\"24\">🙂</text><text x=\"712\" y=\"245\">5 उपयोग</text>\n</g>\n<rect x=\"60\" y=\"290\" width=\"330\" height=\"290\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"225\" y=\"325\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">रोशनी — मुफ़्त इंतज़ाम</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"365\">✓ दिन में, खिड़की के पास</text>\n<text x=\"90\" y=\"398\">✓ रोशनी उत्पाद पर तिरछी</text>\n<text x=\"90\" y=\"431\">✓ फ़ोन-फ़्लैश बंद (पीला/तेज़ दाग)</text>\n<text x=\"90\" y=\"464\">✗ सीधी दोपहर की धूप</text>\n<text x=\"90\" y=\"497\">✗ पीली बल्ब की रोशनी (रंग बदलता)</text>\n<text x=\"90\" y=\"530\">✗ छाया उत्पाद पर गिरे</text>\n</g>\n<rect x=\"410\" y=\"290\" width=\"330\" height=\"290\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"575\" y=\"325\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">पृष्ठभूमि व स्थिरता</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"440\" y=\"365\">✓ सफ़ेद कपड़ा/काग़ज़/चादर</text>\n<text x=\"440\" y=\"398\">✓ फ़ोन दोनों हाथ से या टिकाकर</text>\n<text x=\"440\" y=\"431\">✓ उत्पाद बीच में, पूरा फ़्रेम में</text>\n<text x=\"440\" y=\"464\">✗ रंगीन/छपे कपड़े का पिछला भाग</text>\n<text x=\"440\" y=\"497\">✗ हिलता हुआ फ़ोन (धुँधली फ़ोटो)</text>\n<text x=\"440\" y=\"530\">✗ उत्पाद कटा हुआ/तिरछा</text>\n</g>\n<rect x=\"60\" y=\"600\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"632\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">यह तरीक़ा हर मंच पर एक-सा — WhatsApp से Amazon तक</text>\n<text x=\"400\" y=\"665\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">पाँच कोण एक बार खींचो, फिर सिर्फ़ काटो-छाँटो (पाठ 19-20)</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## रोशनी और पृष्ठभूमि — बिना ख़र्च के अच्छा इंतज़ाम\nसबसे अच्छी और मुफ़्त रोशनी दिन की खिड़की-रोशनी है — दोपहर की सीधी तेज़ धूप नहीं (उससे कड़ी काली छाया बनती है), बल्कि सुबह-शाम की तिरछी रोशनी या खिड़की के पास छाँव वाली जगह। फ़ोन का फ़्लैश बंद रखिए — वह पीला/सफ़ेद दाग़ और ग़लत रंग देता है। पृष्ठभूमि के लिए सफ़ेद चादर, बड़ा काग़ज़, या सफ़ेद दीवार काफ़ी है — पीछे कोई रंगीन/छपा कपड़ा, बर्तन, दूसरा सामान न दिखे। फ़ोन को दोनों हाथों से पकड़िए या किसी चीज़ पर टिकाइए (किताबों का ढेर भी चलेगा) ताकि फ़ोटो धुँधली न आए — यही \"स्थिरता\" गाँव के हर विद्यार्थी के लिए बिना ट्राइपॉड के भी मुमकिन है।\n\n## दिखाने वाला बनाम सजाने वाला — फ़ोटो का असली काम\nहर फ़ोटो का एक काम होना चाहिए — कुछ दिखाना, कुछ साबित करना; सिर्फ़ सुंदर दिखने के लिए नहीं। \"उपयोग में\" वाली फ़ोटो में अगर फूल-सजावट या नक़ली माहौल डाला, पर उत्पाद ख़ुद धुँधला हो गया — यह फ़ोटो बेकार है। नियम — पहले उत्पाद साफ़-साफ़, ठीक फ़्रेम में, फिर सजावट (पाठ-18 में AI-lifestyle चित्र में यही नियम और गहराई से)। और एक जाँच — फ़ोटो खींचकर तुरंत फ़ोन पर बड़ा करके देखिए (ज़ूम करके) — धुँधली, तिरछी, या कटी हुई तो दोबारा।\n\n## नाबालिग व सेवा-सहायक दोनों की आँख से यह पाठ\nअगर आप रास्ता-A (अपनी दुकान) पर हैं, तो यह फ़ोटो-हुनर सीधे आपके काम आएगा — हर नए उत्पाद पर यही पाँच कोण दोहराइए। अगर आप रास्ता-B (सेवा-सहायक) पर हैं, तो सोचिए — यह वह पहला हुनर है जो आप दुकानदार को \"दिखाकर\" बेच सकते हैं; \"पहले-बाद\" फ़ोटो की एक जोड़ी (उनकी अपनी पुरानी धुँधली फ़ोटो बनाम आपकी साफ़ फ़ोटो) आपकी सबसे असरदार पहली-मुलाक़ात-सामग्री है। दोनों रास्तों के लिए यह हुनर एक-सा सीखा जाता है — बस उपयोग अलग।\n\n## एक असली उदाहरण — पाँच कोण, एक रिटर्न कम\nएक चप्पल-विक्रेता सिर्फ़ ऊपर से एक फ़ोटो देता था — ग्राहक \"तला कैसा है?\" पूछते, कुछ ने बिना पूछे मँगाई और लौटाई। पाँच कोण जोड़े — सामने, बग़ल (एड़ी की ऊँचाई), ऊपर, नज़दीक (सिलाई), और पैर में पहनी हुई (उपयोग) — खिड़की की रोशनी, सफ़ेद चादर। सवाल घटे, रिटर्न घटा; कैमरा वही पुराना फ़ोन था। फ़ोटो में पैसा नहीं, कोण और रोशनी लगती है।\n\n## पाँच कोण का क्रम — मंच पर कौन-सी पहली\nमार्केटप्लेस पर पहली फ़ोटो (मुख्य) = सामने, सफ़ेद-पृष्ठभूमि, पूरा उत्पाद, कोई text/लोगो नहीं (मंच-नियम, पाठ-19); दूसरी = उपयोग में (आकार का अंदाज़ा); तीसरी = नज़दीक (बनावट/गुणवत्ता); चौथी-पाँचवीं = बग़ल/ऊपर। WhatsApp-कैटलॉग में भी पहली वही सामने वाली — क्रम बदलिए मत, ग्राहक की आँख इसी क्रम की आदी है।\n\n## 3. आज का काम «काम-कार्ड»\nपाठ-15 के अपने उत्पाद की पाँच-कोण फ़ोटो लीजिए — दिन की रोशनी में, सफ़ेद पृष्ठभूमि पर, फ़ोन स्थिर करके। हर फ़ोटो के बाद ज़ूम करके जाँचिए — धुँधली/तिरछी हो तो दोबारा। फिर पाँचों को फ़ोन में एक फ़ोल्डर \"उत्पाद-फ़ोटो-(संकेत)-कच्चा\" में रखिए, साफ़ नाम से (front.jpg, side.jpg, top.jpg, close.jpg, use.jpg)। कॉपी में लिखिए — कौन-सा कोण सबसे अच्छा आया (यही मुख्य फ़ोटो बनेगा), कौन-सा दोबारा लेना पड़ा और क्यों। जाँच-सूची: ☐ पाँचों कोण, दिन-रोशनी, सफ़ेद पृष्ठभूमि ☐ ज़ूम-जाँच हर फ़ोटो पर ☐ फ़ोल्डर + साफ़ नाम ☐ मुख्य-फ़ोटो चुनी ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = पाँचों कोण मौजूद, साफ़ (धुँधली नहीं), सफ़ेद/सादी पृष्ठभूमि पर, उत्पाद पूरा फ़्रेम में और बीच में; फ़ाइल-नाम साफ़; मुख्य-फ़ोटो का चुनाव कारण-सहित। समय: 40 मिनट।\n\n## 5. सबूत\nसबूत-खाते में पाँचों फ़ोटो और फ़ोल्डर का स्क्रीनशॉट। ये \"कच्ची\" फ़ोटो हैं — पाठ-17 (पृष्ठभूमि-सफ़ाई) और 19-20 (मंच-मानक, AI-लिस्टिंग) में इन्हीं को सुधारा-काटा-इस्तेमाल किया जाएगा; इसलिए मूल फ़ोटो कभी न मिटाएँ, हमेशा प्रति पर काम करें।\n\n## 6. AI-सहायक\nफ़ोटो खींचते समय AI का उपयोग नहीं — यह हाथ-आँख का हुनर है। बाद में AI से पूछिए — \"इस उत्पाद (नाम बताइए) के लिए मार्केटप्लेस-फ़ोटो में और कौन-सा कोण/एंगल अच्छा हो सकता है, जो मैंने भूल दिया?\" — पर फ़ोटो ख़ुद AI को न भेजें अगर उसमें दुकानदार/परिवार का चेहरा या निजी पृष्ठभूमि (घर का अंदर, दस्तावेज़) दिखे। पृष्ठभूमि-हटाने का असली AI-काम पाठ-17 में।\n\n## 7. आम ग़लती\nपहली — फ़्लैश जलाकर फ़ोटो — रंग और चमक दोनों बिगड़ते हैं। दूसरी — रंगीन/छपे कपड़े की पृष्ठभूमि — उत्पाद खो जाता है, ग्राहक का ध्यान भटकता है। तीसरी — सिर्फ़ एक फ़ोटो लेकर \"काफ़ी है\" मान लेना — ग्राहक बग़ल-नज़दीक़ न देखे तो भरोसा नहीं करता। चौथी — फ़ोटो तिरछी/कटी हुई, पर बिना ज़ूम-जाँचे आगे बढ़ जाना। पाँचवीं — बहुत महँगा फ़ोटो-सामान (लाइट-बॉक्स, बड़ा कैमरा) ख़रीदने की सोचकर काम टाल देना — दिन की रोशनी और सफ़ेद चादर काफ़ी है।\n\n## 8. सुरक्षा-पत्रक\n\"उपयोग में\" फ़ोटो में किसी का चेहरा हो तो पाठ-15 की सहमति फिर जाँच लीजिए (चेहरा-अनुमति अलग से \"हाँ\" होनी चाहिए)। बच्चों के चेहरे कभी नहीं — नियम-4 (पाठ-10) यहाँ भी। दुकान के अंदर की फ़ोटो लेते समय पीछे किसी और ग्राहक का चेहरा, कोई निजी काग़ज़-दस्तावेज़, नक़द-गल्ला न दिखे — फ़्रेम में सिर्फ़ उत्पाद। 18 से कम विद्यार्थी फ़ोटो-अभ्यास स्वतंत्र रूप से कर सकते हैं (यह सिर्फ़ हुनर है, खाता नहीं) — पर उपयोग-फ़ोटो में अपना ही चेहरा हो तो सावधानी।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। फ़ोटो-मानक सामान्य अच्छी-प्रथा है; हर मंच के सटीक पिक्सेल-आकार पाठ-19 में। 📎 मूल-कोर्स-कड़ी: Amazon के उत्पाद-फ़ोटो दिशा-निर्देश — https://sell.amazon.in/learn/seller-university (Product images module) — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=product-photography · platform=none · level=F,O · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं पाँच कोण के नाम और हर एक का काम बता सकता हूँ।\n- [ ] मैंने अपने उत्पाद की पाँच-कोण फ़ोटो सफ़ेद पृष्ठभूमि, दिन-रोशनी में ली हैं।\n- [ ] मैंने हर फ़ोटो ज़ूम करके जाँची है।\n- [ ] मेरा फ़ोल्डर साफ़ नाम से बना है और मुख्य-फ़ोटो चुनी है।\n- [ ] मैं जानता हूँ कि मूल फ़ोटो कभी नहीं मिटानी, प्रति पर काम करना है।",
 "17": "═\n# पाठ-17: AI से पृष्ठभूमि हटाना व फ़ोटो साफ़ करना\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर F/O · रास्ता A,B · volatility HIGH Δ)*\n\n## 1. उद्देश्य\nपाठ-16 की पाँच \"कच्ची\" फ़ोटो अब AI-कारख़ाने में जाएँगी। यह पाठ कोर्स का पहला \"AI हाथ से काम\" पाठ है — जहाँ AI आपकी मेहनत को घंटों से मिनटों में बदल देता है, बशर्ते जाँच आपकी बनी रहे। पाठ के बाद आप तीन बातें कर पाएँगे — किसी भी फ़ोटो की पृष्ठभूमि AI से मुफ़्त हटा पाएँगे; फ़ोटो की चमक-सफ़ाई हल्के AI-सुधार से बेहतर बना पाएँगे; और यह जान पाएँगे कि सुधार कितना करना है, कहाँ रुकना है — ताकि उत्पाद असली दिखे, झूठा नहीं।\n\n## 2. मुख्य बात\nपाँच साल पहले पृष्ठभूमि हटाने के लिए महँगा सॉफ़्टवेयर और घंटों का हुनर चाहिए था — आज मुफ़्त AI-औज़ार 10 सेकंड में करते हैं। एक-वाक्य बात — **AI से पृष्ठभूमि सफ़ेद/पारदर्शी करो, हल्की चमक-सफ़ाई करो — पर उत्पाद का असली आकार, रंग, बनावट कभी मत बदलो; \"साफ़ करना\" ठीक है, \"झूठ बनाना\" कभी नहीं।**\n\n## पृष्ठभूमि हटाना — तीन कदम\n(1) कच्ची फ़ोटो (पाठ-16) को AI पृष्ठभूमि-हटाने वाले औज़ार में डालिए — यह उत्पाद के किनारे पहचानकर पीछे की हर चीज़ मिटा देता है, बचता है सिर्फ़ उत्पाद, पारदर्शी या सफ़ेद पृष्ठभूमि पर। (2) नतीजा ज़ूम करके जाँचिए — कहीं उत्पाद का हिस्सा भी कट तो नहीं गया (झालरदार कपड़े, बालों जैसी बारीक चीज़ में AI कभी-कभी ग़लती करता है), या पृष्ठभूमि का कोई टुकड़ा बच तो नहीं गया — दोबारा कोशिश करें, या ऐसे कोण चुनें जो AI के लिए आसान हों। (3) साफ़ पृष्ठभूमि पर उत्पाद को नई सफ़ेद (या मंच-मानक के अनुसार) पृष्ठभूमि पर रखिए — यह अब \"मुख्य फ़ोटो\" के लिए मंच-तैयार है (पाठ-19 में मंच-मानक)।\n\n## चित्र — AI-सफ़ाई के तीन कदम और सीमा-रेखा\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">AI से पृष्ठभूमि हटाना व फ़ोटो साफ़ करना</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">बाएँ से दाएँ तीन कदम · सोना = सीमा-रेखा — यहाँ रुको</text>\n<g font-size=\"16\" fill=\"#0B1F3A\" text-anchor=\"middle\">\n<rect x=\"40\" y=\"120\" width=\"210\" height=\"220\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"145\" y=\"150\" font-size=\"18\" font-weight=\"bold\">1. कच्ची फ़ोटो</text>\n<rect x=\"65\" y=\"170\" width=\"160\" height=\"120\" rx=\"6\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/>\n<circle cx=\"145\" cy=\"230\" r=\"35\" fill=\"#F9A825\"/>\n<text x=\"145\" y=\"310\">रंगीन/असली पृष्ठभूमि</text>\n<rect x=\"295\" y=\"120\" width=\"210\" height=\"220\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"150\" font-size=\"18\" font-weight=\"bold\">2. AI-हटाना</text>\n<rect x=\"320\" y=\"170\" width=\"160\" height=\"120\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-dasharray=\"4 4\"/>\n<circle cx=\"400\" cy=\"230\" r=\"35\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"310\">पीछे पारदर्शी/सफ़ेद</text>\n<rect x=\"550\" y=\"120\" width=\"210\" height=\"220\" rx=\"12\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"655\" y=\"150\" font-size=\"18\" font-weight=\"bold\">3. जाँचो + रखो</text>\n<rect x=\"575\" y=\"170\" width=\"160\" height=\"120\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/>\n<circle cx=\"655\" cy=\"230\" r=\"35\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"2\"/>\n<text x=\"655\" y=\"310\">किनारे साबुत? रंग सही?</text>\n</g>\n<line x1=\"250\" y1=\"230\" x2=\"285\" y2=\"230\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><polygon points=\"293,230 277,220 277,240\" fill=\"#0B1F3A\"/>\n<line x1=\"505\" y1=\"230\" x2=\"540\" y2=\"230\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><polygon points=\"548,230 532,220 532,240\" fill=\"#0B1F3A\"/>\n<rect x=\"60\" y=\"380\" width=\"330\" height=\"230\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"225\" y=\"415\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#2E7D32\">✓ ठीक — साफ़ करना</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"450\">पृष्ठभूमि हटाना/बदलना (सफ़ेद)</text>\n<text x=\"90\" y=\"480\">हल्की चमक-कंट्रास्ट सुधार</text>\n<text x=\"90\" y=\"510\">सीधा करना (तिरछा फ़्रेम)</text>\n<text x=\"90\" y=\"540\">धूल/दाग़ का धब्बा हटाना</text>\n<text x=\"90\" y=\"570\">आकार 1:1/मंच-नाप में काटना</text>\n</g>\n<rect x=\"410\" y=\"380\" width=\"330\" height=\"230\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"575\" y=\"415\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">✗ मना — झूठ बनाना</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"440\" y=\"450\">रंग बदलना (नीला को लाल)</text>\n<text x=\"440\" y=\"480\">नाप/आकार बड़ा-छोटा दिखाना</text>\n<text x=\"440\" y=\"510\">दाग़-ख़राबी छिपाकर नया दिखाना</text>\n<text x=\"440\" y=\"540\">नक़ली चमक/नई-जैसी चीज़ बनाना</text>\n<text x=\"440\" y=\"570\">कोई और सामान जोड़ना (छेड़छाड़)</text>\n</g>\n<rect x=\"60\" y=\"630\" width=\"680\" height=\"65\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"662\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">जो ग्राहक को घर आकर मिले, फ़ोटो वैसी ही दिखनी चाहिए</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## हल्की सफ़ाई — चमक, सीधापन, दाग़-धब्बा\nपृष्ठभूमि हटाने के बाद फ़ोटो में और तीन हल्के सुधार आम तौर पर AI-औज़ार में साथ मिलते हैं — **चमक-कंट्रास्ट** (बहुत गहरी/धुँधली फ़ोटो को सामान्य करना), **सीधा करना** (अगर फ़ोन तिरछा था तो फ़ोटो को सीधा घुमाना), **धूल-दाग़ हटाना** (फ़ोटो में धूल का कण या फ़ोन-लेंस का दाग़, उत्पाद का दाग़ नहीं)। ये तीनों \"साफ़ करना\" हैं — असली उत्पाद वैसा ही दिखता है, बस फ़ोटो बेहतर बनी। इसके आगे मत जाइए।\n\n## सीमा-रेखा — कहाँ रुकना है\nयही इस पाठ की सबसे बड़ी सीख है। **कभी न करें:** रंग बदलना (कपड़ा असल में हल्का नीला है, फ़ोटो में गहरा नीला बना देना), नाप-आकार बड़ा दिखाना (छोटा बैग बड़ा दिखे), उत्पाद का असली दाग़/ख़राबी छिपाकर \"नया-जैसा\" बना देना, नक़ली चमक जोड़ना (पुराने बर्तन को चमकदार नया दिखाना), या फ़ोटो में कुछ ऐसा जोड़ना जो उत्पाद के साथ नहीं आता (मुफ़्त उपहार दिखाना जो असल में नहीं मिलता)। सादा नियम — **जो ग्राहक को घर आकर मिले, फ़ोटो वैसी ही दिखनी चाहिए।** इस सीमा को पार करना \"AI reality-check\" के उल्टा काम है — यहाँ आप ख़ुद वह ग़लती कर रहे हैं जो पाठ-28 में पकड़नी सिखाई जाएगी। इस सीमा-रेखा का उल्लंघन मंच-नीति में \"भ्रामक फ़ोटो\" के तहत आता है और खाता-बंद तक ले जा सकता है (खंड-20)।\n\n## यह पाठ HIGH-volatility क्यों — औज़ार बदलते हैं, नियम नहीं\nकौन-सा मुफ़्त AI-फ़ोटो-औज़ार सबसे अच्छा है, यह हर कुछ महीनों में बदलता है — नए औज़ार आते हैं, पुराने पैसे माँगने लगते हैं। इसलिए इस पाठ पर Δ है और औज़ार का कोई एक नाम पाठ में स्थायी नहीं लिखा — छह-सवाल छलनी (पाठ-26) से अपने समय का सबसे अच्छा मुफ़्त औज़ार चुनिए, कोर्स-index पर \"आज के सुझाए औज़ार\" सूची भी देखिए (तिमाही ताज़ा होती है)। जो नहीं बदलता — तीन-कदम तरीक़ा और साफ़ करना बनाम झूठ बनाना की सीमा-रेखा।\n\n## एक छोटी जाँच — साफ़ हुआ या बदल गया?\nहर AI-सफ़ाई के बाद मूल-फ़ोटो और साफ़-फ़ोटो को साथ रखकर तीन सवाल — रंग वही? आकार/अनुपात वही? कोई निशान/दाग़ जो असल में है, ग़ायब तो नहीं? तीसरा सबसे ज़रूरी — असली दाग़ छिपाना \"सफ़ाई\" नहीं, झूठ है (पाठ-18, 284)। सेवा-सहायक फ़ोटो दुकानदार को दिखाकर \"यही सामान है?\" पूछे — दुकानदार का \"हाँ\" ही मंज़ूरी।\n\n## 3. आज का काम «काम-कार्ड»\nपाठ-16 की पाँच कच्ची फ़ोटो में से मुख्य फ़ोटो (सामने वाली) लीजिए। किसी मुफ़्त AI-पृष्ठभूमि-हटाने वाले औज़ार में डालिए (छह-सवाल छलनी लगाकर चुनिए), पृष्ठभूमि हटाइए/सफ़ेद कीजिए। ज़ूम करके जाँचिए — किनारे साबुत हैं? रंग बदला तो नहीं? फिर हल्की चमक-सफ़ाई कीजिए अगर ज़रूरत हो। \"पहले\" और \"बाद\" दोनों फ़ोटो साथ रखिए और कॉपी में तीन पंक्ति लिखिए — क्या सुधरा, क्या सीमा-रेखा के अंदर रहा (जाँच), और क्या इसे \"साफ़ किया\" कह सकते हैं ईमानदारी से। बाक़ी चार फ़ोटो पर भी यही दोहराइए अगर समय हो, वरना अगले पाठ में जारी रखें। जाँच-सूची: ☐ छह-सवाल छलनी से औज़ार चुना ☐ पृष्ठभूमि हटाई/सफ़ेद की ☐ किनारे-रंग जाँचे ☐ पहले-बाद साथ रखे ☐ ईमानदारी-जाँच लिखी ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = मुख्य फ़ोटो की पृष्ठभूमि साफ़ सफ़ेद/पारदर्शी, किनारे साबुत (कोई हिस्सा कटा नहीं), रंग असली जैसा; \"पहले-बाद\" तुलना में कोई झूठ-बनाना नहीं (नाप/रंग/दाग़ नहीं बदला); तीन पंक्ति ईमानदार जाँच। समय: 35 मिनट।\n\n## 5. सबूत\nसबूत-खाते में \"पहले\" और \"बाद\" दोनों फ़ोटो साथ। यह जोड़ी पाठ-28 (AI reality-check) में एक नमूने की तरह वापस आएगी — तब आप ख़ुद अपने काम को जाँचेंगे कि कहीं सीमा-रेखा पार तो नहीं हुई।\n\n## 6. AI-सहायक\nयह पूरा पाठ AI-सहायक पर है। अतिरिक्त उपयोग — फ़ोटो-औज़ार में \"पृष्ठभूमि सफ़ेद करो\" के अलावा कुछ औज़ार टेक्स्ट-निर्देश भी लेते हैं (\"halka background, product clear\") — सरल अंग्रेज़ी में लिखिए। एक जाँच-सवाल AI से भी पूछ सकते हैं — \"इस फ़ोटो में पृष्ठभूमि हटाने के बाद कहीं उत्पाद का हिस्सा कटा दिख रहा है?\" (फ़ोटो साथ देकर, बशर्ते उसमें निजी बात न हो) — पर अंतिम जाँच आपकी आँख से।\n\n## 7. आम ग़लती\nपहली — पृष्ठभूमि हटाने के बाद किनारे न जाँचना — बारीक झालर/धागे कटे रह जाते हैं, ग्राहक को अधूरा उत्पाद दिखता है। दूसरी — \"थोड़ा और चमकीला/सुंदर\" करने के लालच में रंग बदल देना — यह भ्रामक है। तीसरी — पुराने/इस्तेमाल किए सामान का दाग़ AI से मिटाकर \"नया\" दिखाना — धोखा, पकड़े जाने पर रिटर्न-भरमार और ख़राब रिव्यू। चौथी — हर फ़ोटो पर बहुत ज़्यादा सुधार करके फ़ोटो नक़ली/कार्टून जैसी बना देना। पाँचवीं — मूल कच्ची फ़ोटो मिटा देना — हमेशा प्रति सुरक्षित रखिए।\n\n## 8. सुरक्षा-पत्रक\nAI-फ़ोटो-औज़ार को फ़ोटो अपलोड करने से पहले देख लीजिए कि उसमें दुकानदार का चेहरा, घर का अंदर का दृश्य, कोई दस्तावेज़ न दिखे — सिर्फ़ उत्पाद। मुफ़्त औज़ार अक्सर आपकी अपलोड की फ़ोटो अपने सर्वर पर रखते हैं — नीति पढ़िए (छह-सवाल छलनी में यही सवाल)। सीमा-रेखा पार करना (नाप-रंग-दाग़ झूठ) सिर्फ़ नैतिक ग़लती नहीं, कई मंचों पर सीधा नीति-उल्लंघन है और उपभोक्ता-कानून के तहत शिकायत का कारण बन सकता है (खंड-20)। 18 से कम: फ़ोटो-सुधार अभ्यास ठीक है, पर असली दुकानदार की फ़ोटो पर काम अभिभावक/उस्ताद की निगरानी में।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। AI-फ़ोटो-औज़ारों के नाम/सुविधाएँ बदलते रहते हैं — कोर्स में कोई एक नाम स्थायी नहीं; कोर्स-index पर \"आज के सुझाए मुफ़्त औज़ार\" तिमाही ताज़ा होते हैं। 📎 मूल-कोर्स-कड़ी: भ्रामक फ़ोटो पर मंच-नीति की समझ के लिए Amazon Seller University का \"Image guidelines/Prohibited image content\" हिस्सा — https://sell.amazon.in/learn/seller-university — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=ai-photo-cleanup · platform=none · level=F,O · path=A,B · volatility=HIGH · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैंने AI से एक फ़ोटो की पृष्ठभूमि हटाई/सफ़ेद की है।\n- [ ] मैंने किनारे और रंग की जाँच ज़ूम करके की है।\n- [ ] मैं \"साफ़ करना\" और \"झूठ बनाना\" में पाँच-पाँच उदाहरण बता सकता हूँ।\n- [ ] मेरे पास \"पहले-बाद\" की जोड़ी सबूत-खाते में है।\n- [ ] मैं जानता हूँ कि यह पाठ Δ क्यों है और औज़ार कैसे चुनना है।",
 "18": "═\n# पाठ-18: AI से lifestyle व infographic चित्र — मर्यादा व disclosure\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर F/O · रास्ता A,B · volatility HIGH Δ)*\n\n## 1. उद्देश्य\nपाठ-17 में असली फ़ोटो साफ़ की; अब AI से दो नए तरह के चित्र बनाना सीखेंगे — \"lifestyle\" (उत्पाद किसी माहौल/उपयोग में सजा हुआ दिखे) और \"infographic\" (उत्पाद के गुण चित्र में लिखे-दिखे)। पाठ के बाद आप तीन बातें कर पाएँगे — AI से एक lifestyle पृष्ठभूमि और एक infographic बना पाएँगे; समझ पाएँगे कि इन दोनों की मर्यादा असली-फ़ोटो से अलग क्यों है; और हर ऐसे चित्र पर \"AI-सहायता से बना\" कैसे और कब लिखना है (disclosure) — यह जान पाएँगे।\n\n## 2. मुख्य बात\nlifestyle और infographic चित्र \"कल्पना\" हैं, \"सबूत\" नहीं — यही फ़र्क़ पूरी मर्यादा तय करता है। एक-वाक्य बात — **असली फ़ोटो सबूत है (उत्पाद वैसा ही मिलेगा), AI-lifestyle/infographic सजावट और समझ है (माहौल कल्पना है, गुण-लिखावट सच्ची हो) — दोनों एक-दूसरे की जगह नहीं ले सकते, मुख्य फ़ोटो हमेशा असली रहेगी।**\n\n## Lifestyle चित्र — माहौल की कल्पना, उत्पाद असली\nLifestyle का मतलब — उत्पाद को किसी सुंदर माहौल में दिखाना (कुर्ती किसी हरे-भरे आँगन में लटकी, बर्तन किसी सजी रसोई में)। AI से यह बनता है — असली उत्पाद-फ़ोटो (पाठ-17 वाली, पृष्ठभूमि-रहित) को AI किसी बनाए हुए माहौल में \"बैठा\" देता है। मर्यादा — उत्पाद ख़ुद असली फ़ोटो से आना चाहिए (AI से गढ़ा हुआ उत्पाद नहीं), सिर्फ़ पीछे का माहौल AI का; माहौल ऐसा हो जो ग्राहक को ग़लत उम्मीद न दे (जैसे बहुत महंगे घर का माहौल दिखाकर सस्ता उत्पाद बेचना ठीक है, पर \"यह उत्पाद इस बड़े घर के साथ मिलेगा\" जैसा भ्रम नहीं)। lifestyle चित्र हमेशा \"अतिरिक्त\" फ़ोटो होती है — मुख्य/पहली फ़ोटो असली सफ़ेद-पृष्ठभूमि वाली ही रहती है (पाठ-19 मंच-मानक)।\n\n## चित्र — दो नए चित्र-प्रकार और उनकी मर्यादा\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Lifestyle व Infographic — कल्पना अलग, सच अलग</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सोना = असली भाग (कभी न बदले) · बाक़ी = AI की कल्पना/मदद</text>\n<rect x=\"40\" y=\"120\" width=\"340\" height=\"280\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"210\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">Lifestyle चित्र</text>\n<rect x=\"70\" y=\"175\" width=\"90\" height=\"90\" rx=\"8\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"115\" y=\"225\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">असली उत्पाद</text>\n<rect x=\"170\" y=\"175\" width=\"150\" height=\"90\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-dasharray=\"4 4\"/>\n<text x=\"245\" y=\"215\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">AI-माहौल</text>\n<text x=\"245\" y=\"235\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">(आँगन/रसोई/कल्पना)</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"70\" y=\"300\">उत्पाद असली फ़ोटो से — कभी AI-गढ़ा नहीं</text>\n<text x=\"70\" y=\"330\">माहौल कल्पना — ग़लत उम्मीद न बने</text>\n<text x=\"70\" y=\"360\">हमेशा \"अतिरिक्त\" फ़ोटो, मुख्य नहीं</text>\n</g>\n<rect x=\"420\" y=\"120\" width=\"340\" height=\"280\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"590\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">Infographic चित्र</text>\n<rect x=\"450\" y=\"175\" width=\"90\" height=\"90\" rx=\"8\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"495\" y=\"225\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">असली उत्पाद</text>\n<rect x=\"550\" y=\"175\" width=\"150\" height=\"90\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-dasharray=\"4 4\"/>\n<text x=\"625\" y=\"200\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">\"100% कॉटन\"</text>\n<text x=\"625\" y=\"220\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">\"धुलने में आसान\"</text>\n<text x=\"625\" y=\"240\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">(सच्चे गुण-लिखावट)</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"450\" y=\"300\">गुण-लिखावट AI बनाए, सच आप जाँचें</text>\n<text x=\"450\" y=\"330\">गढ़ा गुण/झूठा दावा — सख़्त निषेध</text>\n<text x=\"450\" y=\"360\">A+ Content-जैसी जगह पर उपयोगी</text>\n</g>\n<rect x=\"60\" y=\"440\" width=\"680\" height=\"160\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"474\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">Disclosure — कब और कैसे लिखें</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"510\">जहाँ माहौल/पृष्ठभूमि AI-बनी — विवरण में एक पंक्ति: \"पृष्ठभूमि AI-सहायता से बनी;</text>\n<text x=\"90\" y=\"538\">उत्पाद असली फ़ोटो में देखें\"</text>\n<text x=\"90\" y=\"572\">कुछ मंच अब AI-बने विज्ञापन-चित्र पर नीति-लेबल माँगते हैं — मंच-पेज देखें (पाठ-98)</text>\n</g>\n<rect x=\"60\" y=\"620\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"652\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">मुख्य फ़ोटो हमेशा असली — Lifestyle/Infographic सहायक, बदली नहीं</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## Infographic चित्र — गुण चित्र में लिखे, सच्चे\nInfographic का मतलब — उत्पाद की फ़ोटो के साथ उसके गुण चित्र में ही छोटे-छोटे शब्दों/आइकन से लिखे हों (जैसे \"100% कॉटन\", \"मशीन-धुलाई\", \"3 रंगों में उपलब्ध\")। AI यह ढाँचा (चित्र + लिखावट की जगह) जल्दी बना देता है — पर हर लिखा गुण पाठ-15 के \"उत्पाद-जानकारी फ़ॉर्म\" से सच्चा होना चाहिए। यही जगह है जहाँ पाठ-28 (AI reality-check) का काम सबसे ज़्यादा ज़रूरी है — AI कभी-कभी ख़ुद से गुण जोड़ देता है (\"सबसे बेहतरीन क्वालिटी\", \"वाटरप्रूफ़\") जो आपने बताया ही नहीं; हर शब्द फ़ॉर्म से मिलाकर जाँचिए, न मिले तो हटाइए। Infographic बड़े मार्केटप्लेस पर \"A+ Content\" जैसी जगहों में बहुत उपयोगी है (खंड-9)।\n\n## Disclosure — कब, क्यों, कैसे लिखें\n\"Disclosure\" का मतलब है साफ़ बताना कि यह चित्र AI-सहायता से बना है। दो कारण — पहला, ईमानदारी: ग्राहक को धोखा न लगे कि माहौल असली है; दूसरा, मंच-नीति: 2026 में कई बड़े मंच AI-बने विज्ञापन/चित्र पर लेबल माँगने लगे हैं (नीति बदलती रहती है — इसलिए यह पाठ Δ)। सादा तरीक़ा — विवरण में एक पंक्ति \"पृष्ठभूमि AI-सहायता से बनी है; उत्पाद असली फ़ोटो में देखें\" या मंच जो टैग/चेकबॉक्स दे, वह भरना। यह disclosure खंड-20 के AI-Commerce-Safety पाठों (287-289) से सीधे जुड़ता है — वहाँ इसका पूरा नियम-रूप है।\n\n## AI-Commerce-Safety की पहली झलक\nइस पाठ में जो disclosure-नियम सीखा, वह खंड-20 के तीन AI-Commerce-Safety पाठों (287-289) का पहला बीज है — वहाँ इसी बात को \"गढ़ा गुण\", \"भ्रामक AI-चित्र\", \"मानव-मंज़ूरी\" जैसे बड़े नियमों में फैलाया जाएगा। अभी बस इतना याद रखिए — जो नियम आज दो चित्रों पर सीखा, वही नियम आगे विज्ञापन-रचना (पाठ-90), Amazon-सुझाव (113), और हर जगह जहाँ AI तस्वीर या शब्द बनाए, वहाँ लागू होगा।\n\n## एक असली उदाहरण — सुंदर चित्र, ग़लत उम्मीद\nएक विक्रेता ने AI से \"आलीशान बैठक में सोफ़े पर सजा कुशन\" बनवाया — कुशन असली था, पर चित्र में उसका आकार बड़ा दिखा; ग्राहक ने छोटा पाकर लौटाया। अगली बार वही lifestyle-चित्र, पर उसके बगल में असली-फ़ोटो (पाठ-16) पहले, और चित्र पर छोटा नोट \"सजावटी चित्र — असली आकार 40×40 सेमी\"। रिटर्न रुका। नियम सादा — सजावट दिखाओ, पर सबूत पहले और सच का नोट साथ।\n\n## disclosure की तीन पंक्ति-शैलियाँ\n(1) \"सजावटी/AI-निर्मित चित्र — उत्पाद असली फ़ोटो जैसा मिलेगा\"; (2) infographic पर — \"आकार/गुण असली माप से (नीचे तालिका)\"; (3) कैटलॉग-विवरण में एक बार — \"पहली फ़ोटो असली उत्पाद की है\"। तीनों कक्षा-6 भाषा में, छोटी; मंच के AI-चित्र-नियम (कुछ मंच AI-मुख्य-फ़ोटो मना करते हैं) पाठ-19 के साथ तिमाही देखिए।\n\n## 3. आज का काम «काम-कार्ड»\nअपने उत्पाद (पाठ-16-17 की साफ़ फ़ोटो) के लिए एक lifestyle चित्र बनाइए — AI-औज़ार में असली उत्पाद-फ़ोटो डालकर एक सादा, सच्चा माहौल बनवाइए (न बहुत महंगा, न भ्रामक)। फिर एक infographic बनाइए — उत्पाद-फ़ोटो के साथ तीन गुण (पाठ-15 के फ़ॉर्म से लेकर) चित्र में लिखवाइए। दोनों के विवरण में disclosure-पंक्ति लिखिए। कॉपी में एक जाँच-सूची भरिए — lifestyle का माहौल भ्रामक तो नहीं? infographic के तीनों गुण फ़ॉर्म से मिलते हैं? disclosure लिखा? जाँच-सूची: ☐ lifestyle चित्र बना ☐ infographic बना, गुण फ़ॉर्म-मिलान ☐ दोनों में disclosure-पंक्ति ☐ भ्रामकता-जाँच ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = दोनों चित्र बने; lifestyle का माहौल सादा-सच्चा (कोई झूठा वादा नहीं); infographic के गुण शब्दशः पाठ-15 फ़ॉर्म से मिलते (एक भी गढ़ा शब्द नहीं); दोनों में disclosure-पंक्ति मौजूद। समय: 35 मिनट।\n\n## 5. सबूत\nसबूत-खाते में दोनों चित्र और disclosure-पंक्ति की फ़ोटो। ये चित्र खंड-9 (Amazon A+ Content) और खंड-7 (Meta विज्ञापन-रचना) में फिर काम आएँगे — वहाँ यही तरीक़ा दोहराया जाएगा, बस मंच का नाम अलग।\n\n## 6. AI-सहायक\nयह पूरा पाठ AI-सहायक पर है। एक और उपयोग — infographic बनाने के बाद AI से ही पूछिए \"इस चित्र में लिखे गुणों में से कौन-सा मैंने अपने फ़ॉर्म में नहीं बताया था?\" (गुण-सूची और फ़ॉर्म दोनों देकर) — यह ख़ुद-जाँच में मदद करता है, पर अंतिम फ़ैसला आपका। AI को असली फ़ोटो देते समय भी पाठ-17 की सुरक्षा (चेहरा-निजी-दृश्य न हो) याद रखिए।\n\n## 7. आम ग़लती\nपहली — lifestyle माहौल इतना महँगा/भव्य बनाना कि सस्ते उत्पाद की छवि ख़राब हो या ग्राहक को ग़लत उम्मीद बने। दूसरी — infographic में AI का जोड़ा हुआ गढ़ा गुण (\"बेस्ट क्वालिटी\", \"गारंटीड\") बिना जाँचे रख देना — यह पाठ-28 और खंड-20 दोनों का उल्लंघन। तीसरी — disclosure न लिखना, यह सोचकर \"किसी को पता नहीं चलेगा\" — मंच की मशीन-जाँच अक्सर AI-चित्र पहचान लेती है। चौथी — lifestyle/infographic को मुख्य फ़ोटो बना देना और असली फ़ोटो पीछे धकेल देना — मुख्य हमेशा असली।\n\n## 8. सुरक्षा-पत्रक\nAI-lifestyle में किसी असली, पहचाने जा सकने वाले व्यक्ति (चेहरे) का उपयोग बिना उसकी अनुमति के नहीं — AI से \"किसी जैसा चेहरा\" बनवाना भी सम्मान-नियम का उल्लंघन हो सकता है, इससे बचें। बच्चों को lifestyle-चित्रों में (असली या AI-बने) कभी नहीं। infographic में स्वास्थ्य/सुरक्षा से जुड़े झूठे दावे (जैसे \"बीमारी ठीक करे\") सिर्फ़ भ्रामक नहीं, कुछ मामलों में क़ानूनी जोखिम भी। 18 से कम: यह अभ्यास ठीक है, पर असली उत्पाद पर बनाए चित्र दुकानदार को दिखाकर उनकी सहमति के बाद ही कहीं इस्तेमाल हों।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। AI-चित्र-नीति (लेबल/disclosure) मंचों पर तेज़ी से बदल रही है। 📎 मूल-कोर्स-कड़ी: Google Merchant Center की AI-बनी सामग्री की नीति-जानकारी — https://support.google.com/merchants (Policy section) · Amazon A+ Content guidelines — Seller University — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=ai-lifestyle-infographic · platform=none · level=F,O · path=A,B · volatility=HIGH · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं lifestyle और infographic चित्र का फ़र्क़ बता सकता हूँ।\n- [ ] मैंने अपने उत्पाद के लिए दोनों बनाए हैं।\n- [ ] मेरे infographic के गुण फ़ॉर्म से शब्दशः मिलते हैं।\n- [ ] मैंने दोनों में disclosure-पंक्ति लिखी है।\n- [ ] मैं जानता हूँ कि मुख्य फ़ोटो हमेशा असली रहती है, बदली नहीं जाती।",
 "19": "═\n# पाठ-19: मंच-वार फ़ोटो-मानक — आकार, अनुपात, वज़न (KB)\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर F/O · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nफ़ोटो अच्छी बन गई (पाठ 16-18) — अब हर मंच के अपने \"फ़िट होने\" के मानक समझेंगे, जैसे अलग-अलग दरवाज़े की अलग चौड़ाई। पाठ के बाद आप तीन बातें कर पाएँगे — किसी भी फ़ोटो को किसी भी मंच के आकार-मानक में ढाल पाएँगे; फ़ोटो का वज़न (KB/MB) घटा पाएँगे बिना धुँधली किए; और एक \"मास्टर फ़ोटो-सेट\" बना पाएँगे जो सब मंचों के लिए एक बार तैयार हो।\n\n## 2. मुख्य बात\nहर मंच की माँग अलग है — कोई वर्गाकार (1:1) चाहता है, कोई 1000×1000 से बड़ा, कोई 2MB से कम। एक-वाक्य बात — **एक \"मास्टर फ़ोटो\" (बड़ी, साफ़, चौकोर, सफ़ेद-पृष्ठभूमि) बनाओ, फिर हर मंच के लिए उसी से काटो-छोटा करो — शुरू से अलग-अलग फ़ोटो बनाने से यह तरीक़ा दस गुना तेज़ है।**\n\n## आम मानक — क्या-क्या पूछा जाता है\n**आकार (Resolution)** — ज़्यादातर मंच कम-से-कम 1000×1000 पिक्सेल माँगते हैं (कुछ 1080×1080, कुछ बड़े) — छोटी फ़ोटो को बड़ा करने से धुँधली हो जाती है, इसलिए शुरू से बड़ी खींचिए (आजकल के फ़ोन-कैमरे यह आराम से देते हैं)। **अनुपात (Aspect ratio)** — ज़्यादातर 1:1 (वर्गाकार) मुख्य फ़ोटो के लिए; कुछ जगह 4:5 (थोड़ा लंबा, Instagram जैसा) भी चलता है। **वज़न (File size)** — आम तौर पर 2MB से कम प्रति फ़ोटो (कुछ मंच 5MB तक); बहुत भारी फ़ोटो अपलोड धीमा करती है और कभी-कभी अस्वीकार होती है। **पृष्ठभूमि** — मुख्य फ़ोटो के लिए शुद्ध सफ़ेद (RGB 255,255,255) अक्सर ज़रूरी होता है — पाठ-17 का काम यहीं इस्तेमाल होता है।\n\n## चित्र — मास्टर फ़ोटो से हर मंच का नाप\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">एक मास्टर फ़ोटो — हर मंच का अपना नाप</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सोना = मास्टर (सबसे बड़ी-साफ़) · बाक़ी उसी से काटे-घटाए</text>\n<rect x=\"290\" y=\"120\" width=\"220\" height=\"220\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"400\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\">मास्टर फ़ोटो</text>\n<text x=\"400\" y=\"185\" text-anchor=\"middle\" font-size=\"16\">2000×2000+, सफ़ेद, साफ़</text>\n<rect x=\"330\" y=\"210\" width=\"140\" height=\"100\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/>\n<text x=\"400\" y=\"335\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">यहाँ से हर मंच के लिए काटो</text>\n<g font-size=\"16\" fill=\"#0B1F3A\" text-anchor=\"middle\">\n<rect x=\"40\" y=\"400\" width=\"150\" height=\"90\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/>\n<text x=\"115\" y=\"428\" font-weight=\"bold\">WhatsApp</text><text x=\"115\" y=\"452\">1024×1024</text><text x=\"115\" y=\"472\">~100 KB</text>\n<rect x=\"210\" y=\"400\" width=\"150\" height=\"90\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/>\n<text x=\"285\" y=\"428\" font-weight=\"bold\">Amazon</text><text x=\"285\" y=\"452\">1000×1000+, 1:1</text><text x=\"285\" y=\"472\">&lt;10 MB</text>\n<rect x=\"380\" y=\"400\" width=\"150\" height=\"90\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/>\n<text x=\"455\" y=\"428\" font-weight=\"bold\">Meesho</text><text x=\"455\" y=\"452\">1080×1080, 1:1</text><text x=\"455\" y=\"472\">&lt;2 MB</text>\n<rect x=\"550\" y=\"400\" width=\"150\" height=\"90\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/>\n<text x=\"625\" y=\"428\" font-weight=\"bold\">Instagram</text><text x=\"625\" y=\"452\">1080×1080 या 4:5</text><text x=\"625\" y=\"472\">&lt;8 MB</text>\n</g>\n<line x1=\"360\" y1=\"340\" x2=\"150\" y2=\"392\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><line x1=\"390\" y1=\"340\" x2=\"320\" y2=\"392\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><line x1=\"420\" y1=\"340\" x2=\"480\" y2=\"392\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><line x1=\"450\" y1=\"340\" x2=\"640\" y2=\"392\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<rect x=\"60\" y=\"520\" width=\"680\" height=\"170\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"554\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">वज़न घटाने का तरीक़ा — बिना धुँधली किए</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"590\">1. आकार पहले घटाओ (2000px से 1080px) — वज़न अपने-आप कम होगा</text>\n<text x=\"90\" y=\"624\">2. Compress/संपीड़न-औज़ार से 80-85% गुणवत्ता — आँख से फ़र्क़ नहीं दिखता</text>\n<text x=\"90\" y=\"658\">3. हर बार save-करने से पहले साइज़ देखो — मंच की सीमा से कम है?</text>\n</g>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## वज़न घटाना — बिना गुणवत्ता खोए\nबड़ी, साफ़ फ़ोटो का वज़न (MB) भी बड़ा होता है — पर मंच की सीमा से ज़्यादा होने पर अपलोड नहीं होती। तरीक़ा — पहले आकार घटाइए (जो 1000-1080px से बड़ा है, उतना ही काफ़ी, ज़्यादा बड़ा रखने का कोई फ़ायदा नहीं), फिर किसी Compress/संपीड़न-औज़ार से 80-85% गुणवत्ता पर सहेजिए — आँख को फ़र्क़ लगभग नहीं दिखता, पर फ़ाइल का आकार काफ़ी घट जाता है। हर बार सहेजने के बाद फ़ाइल का साइज़ देख लीजिए (फ़ोन में फ़ोटो पर देर तक दबाने से \"विवरण/जानकारी\" में KB/MB दिखता है)। यह मानक हर मंच-खंड (9-14) में फिर काम आएगा — इसलिए यहाँ पक्का सीख लेना फ़ायदेमंद है।\n\n## मास्टर फ़ोटो-सेट — एक बार बनाओ, बार-बार बरतो\nपाठ-16-18 से आपके पास अब सामने-बग़ल-ऊपर-नज़दीक़-उपयोग की पाँच साफ़ फ़ोटो, एक lifestyle, एक infographic हैं। इन्हें एक \"मास्टर फ़ोटो-सेट\" फ़ोल्डर में रखिए — सबसे बड़े, साफ़ आकार में (2000×2000 या जो फ़ोन दे सके)। जब भी किसी मंच पर लिस्टिंग बनानी हो (खंड 3-4, 9-11), इसी सेट से काटिए/घटाइए — शुरू से फिर फ़ोटो खींचने की ज़रूरत नहीं। यही आदत मॉडल-3 सेवा-सहायक के लिए सबसे बड़ी समय-बचत है — एक दिन फ़ोटो-शूट, हफ़्तों कई मंचों पर काम।\n\n## एक असली उदाहरण — एक मास्टर-फ़ोटो, तीन मंच\nएक बर्तन-विक्रेता ने पहले हर मंच के लिए अलग-अलग फ़ोटो खींचीं — तीन गुना मेहनत, फिर भी Amazon पर \"आकार छोटा\", WhatsApp पर \"फ़ाइल भारी\" की शिकायत। फिर एक मास्टर-फ़ोटो (बड़ी, चौकोर, सफ़ेद-पृष्ठभूमि, पाठ-16-17) बनाई और उसी से तीन रूप काटे — Amazon के लिए बड़ा, WhatsApp-कैटलॉग के लिए ~1024 चौकोर, Meesho के लिए मंच-निर्देश अनुसार। मेहनत एक-तिहाई, शिकायत शून्य। मंच के आकार-वज़न-नियम बदलते रहते हैं — इसलिए हर तिमाही मंच-पेज से ताज़ा (पाठ-319)।\n\n## फ़ोटो-फ़ोल्डर का नियम — एक उत्पाद, एक फ़ोल्डर, तीन उप-फ़ोल्डर\nफ़ोन/कंप्यूटर में हर उत्पाद का फ़ोल्डर (SKU-नाम, पाठ-27), उसमें \"मास्टर\", \"whatsapp\", \"marketplace\" उप-फ़ोल्डर — मास्टर-शीट (पाठ-26) के फ़ोटो-कड़ी स्तंभ में यही पता। नया रूप चाहिए तो मास्टर से काटो, दोबारा खींचो मत। सेवा-सहायक हर दुकान का फ़ोल्डर उसी ढाँचे में — दुकान बदलने पर सौंपना एक क्लिक।\n\n## वज़न (KB) घटाना — गुणवत्ता खोए बिना\nमंच अक्सर फ़ाइल-आकार की सीमा रखते हैं और भारी फ़ोटो धीमे नेटवर्क पर खुलती नहीं (गाँव का ग्राहक 2G/3G पर भी है)। मास्टर बड़ी रखिए, पर हर मंच-रूप में \"compress\" (छवि-दबाव) से KB घटाइए — आँख से फ़र्क़ न दिखे तो ठीक; धुँधली हो तो कम दबाइए। कोई भी दबाने वाला औज़ार पाठ-30 की छह-सवाल छलनी से — फ़ोटो किसी अनजान सर्वर पर न भेजिए।\n\n## 3. आज का काम «काम-कार्ड»\nअपने मास्टर फ़ोटो-सेट (पाठ 16-18 की सब फ़ोटो) को एक फ़ोल्डर \"मास्टर-फ़ोटो-(संकेत)\" में जमा कीजिए। फिर तीन अलग-अलग मंच-मानक चुनकर (कॉपी में लिखे — जैसे WhatsApp 1024×1024, Amazon 1000×1000+, Meesho 1080×1080) अपनी मुख्य फ़ोटो को उन तीन नापों में ढालिए (काटकर/छोटा करके) और हर एक का वज़न (KB/MB) जाँचकर तालिका में लिखिए। जाँच-सूची: ☐ मास्टर-सेट फ़ोल्डर बना ☐ 3 मंच-नाप में ढाला ☐ हर एक का वज़न जाँचा ☐ सब मंच-सीमा में ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = मास्टर-फ़ोल्डर में 7 फ़ोटो (5 कोण + lifestyle + infographic) साफ़-बड़ी; तीन मंच-नापों की फ़ाइलें सही आकार-अनुपात में; हर एक की KB/MB मंच-सीमा से कम; फ़ोटो में कोई धुँधलापन नहीं (compress के बाद भी)। समय: 35 मिनट।\n\n## 5. सबूत\nसबूत-खाते में मास्टर-फ़ोल्डर और तीन मंच-नाप की तालिका। यही मास्टर-सेट पूरे कोर्स में हर मंच-खंड के \"लिस्टिंग बनाना\" पाठ में सीधे इस्तेमाल होगा — खंड-23 के Capstone में \"20 फ़ोटो\" यहीं से बड़े रूप में आएँगे।\n\n## 6. AI-सहायक\nAI से पूछिए — \"मेरे पास 2000×2000 की एक फ़ोटो है; इसे WhatsApp, Amazon और Meesho के लिए किस आकार-अनुपात में बदलना होगा — तालिका दीजिए\" — फिर अपनी बनाई तालिका से मिलाइए (मानक बदल सकते हैं — Δ नहीं पर MEDIUM है, इसलिए हर तिमाही एक बार दोबारा जाँचिए)। तस्वीर बदलने का असली काम फ़ोन/कंप्यूटर के औज़ार से — AI सिर्फ़ नाप बताने के लिए।\n\n## 7. आम ग़लती\nपहली — छोटी फ़ोटो को ज़बरदस्ती बड़ा करना (stretch) — धुँधली, टेढ़ी हो जाती है; हमेशा बड़ी से छोटी करें, कभी उल्टा नहीं। दूसरी — सब मंचों के लिए एक ही नाप की फ़ोटो भेज देना — कहीं फ़ोटो कटी दिखेगी, कहीं छोटा-सा दिखेगी। तीसरी — वज़न घटाने के लिए गुणवत्ता बहुत कम कर देना (40-50%) — फ़ोटो धुँधली-दानेदार दिखती है, ग्राहक भरोसा खो देता है। चौथी — मास्टर-सेट न बनाकर हर मंच के लिए दोबारा फ़ोटो खींचना — समय की बर्बादी। पाँचवीं — फ़ाइल-नाम \"IMG_1234.jpg\" जैसे रखना — कुछ महीनों बाद कौन-सी किस उत्पाद की, याद नहीं रहता।\n\n## 8. सुरक्षा-पत्रक\nफ़ोटो-संपीड़न औज़ार चुनते समय भी छह-सवाल छलनी (पाठ-26) — कुछ औज़ार अपलोड की फ़ोटो अपने पास रखते हैं। मास्टर-फ़ोटो-सेट में अगर कोई फ़ोटो ग़लती से दुकानदार का चेहरा/निजी दृश्य ले आई हो, उसे यहीं हटा दीजिए, आगे न बढ़ाएँ। फ़ाइल-नाम में दुकानदार का निजी नाम/फ़ोन नहीं — उत्पाद-संकेत काफ़ी है। 18 से कम: यह पूरी तरह तकनीकी अभ्यास है, सुरक्षित।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। सटीक आकार-वज़न हर मंच अपने पेज पर बदलता रहता है — यहाँ दी संख्याएँ सामान्य दिशा हैं, अंतिम संख्या मंच-पेज से। 📎 मूल-कोर्स-कड़ी (कड़ियाँ): Amazon Image Requirements — Seller University · WhatsApp Business catalog image guidelines — https://faq.whatsapp.com/ (Business/Catalog) · Meesho Supplier image guidelines — https://supplier.meesho.com/ — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=platform-image-standards · platform=multi · level=F,O · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं आकार, अनुपात, वज़न — तीनों मानक बता सकता हूँ।\n- [ ] मेरा मास्टर फ़ोटो-सेट बड़े-साफ़ आकार में तैयार है।\n- [ ] मैंने तीन मंच-नापों में फ़ोटो ढालकर वज़न जाँचा है।\n- [ ] मैं जानता हूँ कि बड़ी फ़ोटो को छोटा करना ठीक, छोटी को बड़ा करना ग़लत।\n- [ ] मेरी फ़ाइलों के नाम साफ़ और समझने-योग्य हैं।",
 "20": "═\n# पाठ-20: एक फ़ोटो से पूरी लिस्टिंग — AI से शीर्षक, बुलेट, विवरण\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर F/O · रास्ता A,B · volatility HIGH Δ)*\n\n## 1. उद्देश्य\nअब तक फ़ोटो तैयार हुई; इस पाठ में पहली बार AI उत्पाद की \"बात\" लिखेगा — शीर्षक, बुलेट-पॉइंट, विवरण। यह इस कोर्स का सबसे शक्तिशाली AI-हुनर है — जो काम पहले घंटों लेता था, अब मिनटों में होता है। पाठ के बाद आप तीन बातें कर पाएँगे — एक फ़ोटो और उत्पाद-जानकारी से AI से पूरी लिस्टिंग का मसौदा बनवा पाएँगे; शीर्षक-बुलेट-विवरण तीनों को अपनी सच्ची जानकारी से मिलाकर सुधार पाएँगे; और समझ पाएँगे कि AI यहाँ सबसे ज़्यादा गढ़ता क्यों है — और उसे कैसे रोकना है।\n\n## 2. मुख्य बात\nAI फ़ोटो देखकर उत्पाद पहचान सकता है, पर उसे आपके उत्पाद की सच्ची कहानी नहीं पता — वह अंदाज़ा लगाता है, और अंदाज़ा कभी-कभी ग़लत होता है। एक-वाक्य बात — **AI को फ़ोटो + अपनी सच्ची जानकारी (पाठ-15 का फ़ॉर्म) दोनों दो, \"मत गढ़ो\" साफ़ लिखो, तीन विकल्प माँगो — फिर हर शब्द अपने फ़ॉर्म से मिलाकर रखो, बाक़ी काटो; मसौदा AI का, लिस्टिंग आपकी।**\n\n## लिस्टिंग के तीन हिस्से — क्या-क्या चाहिए\n**शीर्षक (Title)** — छोटा, साफ़, मुख्य जानकारी पहले (उत्पाद-नाम, सामग्री, रंग/साइज़, ब्रांड अगर है) — \"बहुत बढ़िया\", \"सबसे अच्छा\" जैसे शब्दों की जगह ठोस तथ्य। **बुलेट-पॉइंट (Bullet points)** — 4-5 छोटी पंक्तियाँ, हर एक एक गुण — सामग्री, नाप, देखभाल, उपयोग, ख़ासियत। **विवरण (Description)** — 3-4 वाक्य की कहानी — यह कहाँ बना, कैसे इस्तेमाल हो, क्यों ख़ास है (पाठ-15 के \"बनाने की जगह\" वाले जवाब यहाँ काम आते हैं)। तीनों मिलकर पाठ-2 के \"AI-ख़रीदार के लिए लिखना\" के काम आते हैं — इसलिए यहाँ जो लिखेंगे, वही बाद में AI-सहायकों को समझ आएगा।\n\n## चित्र — फ़ोटो से लिस्टिंग तक, पाँच-कड़ी से\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">एक फ़ोटो से पूरी लिस्टिंग — पाँच-कड़ी से</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सोना = आपका काम · बाक़ी AI का मसौदा</text>\n<g font-size=\"16\" fill=\"#0B1F3A\" text-anchor=\"middle\">\n<rect x=\"30\" y=\"120\" width=\"150\" height=\"90\" rx=\"10\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"105\" y=\"150\" font-weight=\"bold\">1. पूछो</text><text x=\"105\" y=\"175\">फ़ोटो+फ़ॉर्म दो</text><text x=\"105\" y=\"195\">\"मत गढ़ो\" लिखो</text>\n<rect x=\"205\" y=\"120\" width=\"150\" height=\"90\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"280\" y=\"150\" font-weight=\"bold\">2. जाँचो</text><text x=\"280\" y=\"175\">हर शब्द फ़ॉर्म से</text><text x=\"280\" y=\"195\">मिलाओ</text>\n<rect x=\"380\" y=\"120\" width=\"150\" height=\"90\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"455\" y=\"150\" font-weight=\"bold\">3. सुधारो</text><text x=\"455\" y=\"175\">गढ़ा हटाओ</text><text x=\"455\" y=\"195\">अपनी बोली</text>\n<rect x=\"555\" y=\"120\" width=\"215\" height=\"90\" rx=\"10\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"662\" y=\"150\" font-weight=\"bold\">4. सौंपो</text><text x=\"662\" y=\"175\">आपकी लिस्टिंग</text><text x=\"662\" y=\"195\">5. ज़िम्मेदारी आपकी</text>\n</g>\n<line x1=\"180\" y1=\"165\" x2=\"200\" y2=\"165\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><polygon points=\"208,165 192,155 192,175\" fill=\"#0B1F3A\"/>\n<line x1=\"355\" y1=\"165\" x2=\"375\" y2=\"165\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><polygon points=\"383,165 367,155 367,175\" fill=\"#0B1F3A\"/>\n<line x1=\"530\" y1=\"165\" x2=\"550\" y2=\"165\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><polygon points=\"558,165 542,155 542,175\" fill=\"#0B1F3A\"/>\n<rect x=\"40\" y=\"250\" width=\"720\" height=\"330\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"284\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">तीन हिस्से — नमूना</text>\n<rect x=\"70\" y=\"305\" width=\"660\" height=\"60\" rx=\"8\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/>\n<text x=\"90\" y=\"328\" font-size=\"16\" font-weight=\"bold\">शीर्षक:</text><text x=\"90\" y=\"352\" font-size=\"16\">हाथ की कढ़ाई वाली कॉटन कुर्ती — नीला — मीडियम साइज़</text>\n<rect x=\"70\" y=\"375\" width=\"660\" height=\"110\" rx=\"8\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/>\n<text x=\"90\" y=\"398\" font-size=\"16\" font-weight=\"bold\">बुलेट-पॉइंट:</text>\n<text x=\"90\" y=\"420\" font-size=\"16\">• 100% कॉटन कपड़ा  • हाथ की कढ़ाई, गाँव की कारीगर बहनों द्वारा</text>\n<text x=\"90\" y=\"442\" font-size=\"16\">• मशीन में हल्के धोएँ  • साइज़: M (छाती 38\")  • रंग: गहरा नीला</text>\n<text x=\"90\" y=\"464\" font-size=\"16\">• 5-7 दिन में डिलीवरी</text>\n<rect x=\"70\" y=\"495\" width=\"660\" height=\"70\" rx=\"8\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/>\n<text x=\"90\" y=\"518\" font-size=\"16\" font-weight=\"bold\">विवरण:</text><text x=\"90\" y=\"540\" font-size=\"16\">बिहार के खगड़िया ज़िले की कारीगर बहनों द्वारा हाथ से कढ़ी</text><text x=\"90\" y=\"558\" font-size=\"16\">यह कुर्ती रोज़ पहनने और त्योहार दोनों के लिए उपयुक्त है।</text>\n<rect x=\"60\" y=\"600\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"632\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">हर शब्द पाठ-15 के फ़ॉर्म से मिलाओ — न मिले तो काटो</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## AI-प्रॉम्प्ट — क्या-क्या शामिल करें\n\"इस उत्पाद के लिए लिस्टिंग लिखो\" कहना काफ़ी नहीं — पाँच बातें दीजिए: फ़ोटो (या फ़ोटो का वर्णन), उत्पाद-जानकारी फ़ॉर्म की बातें (सामग्री, नाप, दाम-सीमा, बनने की जगह), किस मंच के लिए (शीर्षक-लंबाई अलग-अलग मंच पर अलग — पाठ-21), कक्षा-6 सरल हिंदी/जो भाषा चाहिए, और सबसे ज़रूरी पंक्ति — \"जो जानकारी मैंने नहीं दी, वह मत जोड़ना/मत गढ़ना; वहाँ (यहाँ भरें) लिखकर छोड़ दो\"। यह आख़िरी पंक्ति पाठ-207 (DCA-कोर्स से मिली सीख) जैसी ही है — AI को गढ़ने से पहले ही रोकना।\n\n## जाँचो-सुधारो — हर शब्द फ़ॉर्म से मिलाओ\nमसौदा मिलते ही चार चीज़ें ढूँढिए — (1) गढ़ी बात: कोई गुण/संख्या जो फ़ॉर्म में नहीं थी (\"वाटरप्रूफ़\", \"प्रीमियम क्वालिटी\") — हटाइए या फ़ॉर्म में जोड़कर दुकानदार से पक्का कीजिए; (2) भारी शब्द: \"उत्कृष्ट\", \"बेहतरीन\" जैसे दिखावटी शब्द — सादे शब्दों में बदलिए; (3) ग़लत/उलटी जानकारी: AI कभी-कभी रंग-नाप उलट देता है — फ़ॉर्म से मिलाइए; (4) मंच-बेमेल: बहुत लंबा शीर्षक WhatsApp के लिए, बहुत छोटा विवरण Amazon के लिए — मंच का ध्यान रखिए। यही चार जाँच \"पाँच-कड़ी नियम\" के दूसरे-तीसरे कदम हैं (पूछो-जाँचो-सुधारो-सौंपो-ज़िम्मेदारी)।\n\n## एक असली उदाहरण — तीन विकल्प, एक चुना, चार शब्द बदले\nएक साड़ी-विक्रेता ने AI को फ़ोटो + फ़ॉर्म दिया, \"मत गढ़ो\" लिखा, तीन शीर्षक-विकल्प माँगे। पहला \"प्रीमियम डिज़ाइनर सिल्क साड़ी…\" (फ़ॉर्म में \"सूती\" था — गढ़ा); दूसरा \"हाथ-करघे की सूती साड़ी, 5.5 मीटर, नीली, पूजा-त्योहार के लिए\" (सब फ़ॉर्म से — चुना); तीसरा बहुत लंबा। दूसरे में भी \"बेस्ट क्वालिटी\" शब्द था — हटाया; \"मुफ़्त ब्लाउज़-पीस\" (नहीं आता) — हटाया। नतीजा: AI ने 80% मेहनत बचाई, इंसान ने 20% में सच रखा। बिना फ़ॉर्म के वही AI पहला विकल्प देता और वही छपता।\n\n## तीन विकल्प क्यों — एक नहीं\nएक विकल्प माँगने पर आप उसे \"ठीक ही होगा\" मानकर रख लेते हैं; तीन में तुलना होती है — कौन सच के सबसे पास, कौन सबसे साफ़, कौन बोली (पाठ-23) के सबसे नज़दीक। तीनों में से टुकड़े जोड़कर चौथा बनाना सबसे अच्छा — पर हर टुकड़ा फ़ॉर्म से। पाठ-28 का पाँच-सवाल reality-check यहीं पहली बार पूरे रूप में लगता है।\n\n## AI को क्या दें, क्या न दें — निर्देश की चार पंक्तियाँ\nदें: (1) फ़ोटो; (2) फ़ॉर्म की पूरी सच्ची जानकारी; (3) \"जो जानकारी में नहीं, वह मत लिखो — 'पता नहीं' लिखो\"; (4) \"तीन विकल्प, कक्षा-6 हिंदी, कोई 'बेस्ट/प्रीमियम/गारंटी' नहीं\"। न दें: ग्राहक की कोई जानकारी, दुकानदार का फ़ोन/पता, प्रतिस्पर्धी का नाम — AI को दुकान का सच चाहिए, बाक़ी कुछ नहीं (पाठ-283)।\n\n## 3. आज का काम «काम-कार्ड»\nअपने उत्पाद की मुख्य फ़ोटो (पाठ-19 से) और पाठ-15 का उत्पाद-जानकारी फ़ॉर्म साथ रखिए। AI से ऊपर की पाँच बातों के साथ शीर्षक (2 विकल्प), 5 बुलेट-पॉइंट, और 4-वाक्य विवरण माँगिए। मिले मसौदे को Word/कॉपी में परत-1 (कच्चा AI-मसौदा) की तरह सहेजिए। फिर चार जाँच (गढ़ा, भारी, ग़लत, मंच-बेमेल) करके परत-2 में सुधारिए (हर बदलाव अलग रंग/चिह्न से)। अंतिम, साफ़ लिस्टिंग परत-3 में। जाँच-सूची: ☐ पाँच बातों के साथ AI से माँगा ☐ परत-1 सहेजी ☐ चार जाँच से परत-2 सुधारी ☐ परत-3 अंतिम लिस्टिंग ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = तीन परतें अलग-अलग मौजूद; परत-3 में कोई ऐसा गुण/संख्या नहीं जो फ़ॉर्म में न हो; शीर्षक-बुलेट-विवरण तीनों मौजूद, सादी सच्ची भाषा में; कम-से-कम 3 बदलाव परत-1 से परत-2 में चिह्नित। समय: 40 मिनट।\n\n## 5. सबूत\nसबूत-खाते में तीनों परतें साथ। यह तीन-परत आदत पूरे कोर्स में बार-बार आएगी (हर मंच की अपनी लिस्टिंग, खंड 9-11) — परत-1 और परत-3 की तुलना ही आपके \"AI-हुनर\" का सबसे पक्का पोर्टफ़ोलियो-सबूत है।\n\n## 6. AI-सहायक\nयह पूरा पाठ AI-सहायक पर है; एक अतिरिक्त उपयोग — मसौदा मिलने के बाद फिर से AI से पूछिए \"इस विवरण में कोई ऐसा दावा है जो मैंने नहीं बताया?\" (अपनी फ़ॉर्म-जानकारी देकर) — AI कभी-कभी ख़ुद अपनी ग़लती पकड़ने में मदद करता है, पर अंतिम भरोसा नहीं, अंतिम जाँच आपकी आँख।\n\n## 7. आम ग़लती\nपहली — बिना फ़ॉर्म दिए सिर्फ़ फ़ोटो से \"लिस्टिंग लिखो\" कहना — AI पूरी कहानी गढ़ लेता है। दूसरी — \"मत गढ़ो\" पंक्ति भूल जाना — यह इस पूरे पाठ की जान है। तीसरी — मसौदा जस-का-तस बिना जाँचे कॉपी-पेस्ट करना — गढ़ी बात सीधे ग्राहक तक जाती है, रिटर्न-शिकायत में लौटती है। चौथी — परत-1 सहेजे बिना सीधे सुधारना — बाद में \"इसमें मेरा योगदान क्या\" का जवाब नहीं बचता।\n\n## 8. सुरक्षा-पत्रक\nAI को उत्पाद-जानकारी बताना ठीक है, पर दुकानदार का नाम, फ़ोन, दुकान का पूरा पता — नहीं (सिर्फ़ \"बिहार के एक ज़िले की\" जैसा सामान्य)। गढ़े दावे (स्वास्थ्य-लाभ, \"100% असली\", झूठी गारंटी) रह जाना सिर्फ़ नैतिक भूल नहीं — उपभोक्ता-कानून और मंच-नीति दोनों का उल्लंघन (खंड-20)। सेवा-सहायक: यह लिस्टिंग दुकानदार को दिखाकर पढ़वाइए, उनकी सहमति के बाद ही मंच पर चढ़ाइए — यह पाँच-कड़ी का \"सौंपना\" कदम है। 18 से कम: अभ्यास ठीक, असली उत्पाद पर लिस्टिंग चढ़ाना अभिभावक/उस्ताद के साथ।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। AI-लिस्टिंग-जनरेटर औज़ार व उनकी सुविधाएँ तेज़ी से बदल रही हैं। 📎 मूल-कोर्स-कड़ी: Amazon \"AI-generated listing\" व Enhance My Listing सुविधा — Seller University (Catalog section) — https://sell.amazon.in/learn/seller-university — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=ai-listing-generation · platform=none · level=F,O · path=A,B · volatility=HIGH · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं AI से लिस्टिंग माँगते समय पाँच बातें (फ़ोटो, फ़ॉर्म, मंच, भाषा, \"मत गढ़ो\") शामिल करता हूँ।\n- [ ] मैंने शीर्षक, बुलेट, विवरण तीनों का मसौदा बनवाया है।\n- [ ] मैंने चार जाँच (गढ़ा, भारी, ग़लत, मंच-बेमेल) से सुधारा है।\n- [ ] मेरी तीन परतें (कच्चा-सुधार-अंतिम) अलग-अलग सहेजी हैं।\n- [ ] मैं जानता हूँ कि मसौदा AI का, ज़िम्मेदारी मेरी है।",
 "21": "═\n# पाठ-21: एक सामग्री, तीन ढंग — Amazon/Flipkart/Meesho-रूप (Skill→Platform अमल)\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर O · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nपाठ-20 में एक लिस्टिंग बनाई; आज सीखेंगे कि वही सामग्री (शीर्षक-बुलेट-विवरण) तीन अलग मंचों के तीन अलग ढाँचों में कैसे ढलती है। पाठ के बाद आप तीन बातें कर पाएँगे — Amazon, Flipkart, Meesho के शीर्षक-ढाँचे का फ़र्क़ बता पाएँगे; अपनी एक लिस्टिंग को तीनों रूपों में बदल पाएँगे; और समझ पाएँगे कि यह \"Skill→Platform अमल\" पैटर्न (पाठ-7 का ढाँचा-नियम) यहाँ कैसे काम करता है — एक हुनर, कई पहनावे।\n\n## 2. मुख्य बात\nशीर्षक लिखना एक हुनर है; उस हुनर को हर मंच के अपने कपड़े पहनाने पड़ते हैं। एक-वाक्य बात — **Amazon का शीर्षक लंबा और सब जानकारी-भरा होता है, Flipkart का संतुलित, Meesho का छोटा-सीधा — सामग्री (सच्ची जानकारी) एक रहती है, सिर्फ़ लंबाई-क्रम-शैली मंच के अनुसार बदलती है।**\n\n## तीन ढाँचे — एक-नज़र तुलना\n**Amazon** — शीर्षक में ब्रांड + उत्पाद-नाम + मुख्य गुण + नाप/रंग, अक्सर 150-200 अक्षर तक; बुलेट-पॉइंट लंबे, हर एक में एक फ़ायदा समझाया हुआ; विवरण में कहानी और उपयोग-तरीक़ा। **Flipkart** — शीर्षक थोड़ा छोटा, ज़रूरी जानकारी पहले; बुलेट संक्षिप्त; category-वार अलग फ़ील्ड (साइज़-चार्ट जैसी चीज़ें अलग खाने में)। **Meesho** — शीर्षक सबसे छोटा-सीधा (बजट-ग्राहक जल्दी तय करता है), बुलेट कम (2-3), विवरण छोटा — यहाँ फ़ोटो और दाम ज़्यादा बोलते हैं, शब्द कम। तीनों में सामग्री (सच्चे गुण) वही, बस \"पैकिंग\" अलग — जैसे एक ही मिठाई अलग-अलग डिब्बों में।\n\n## चित्र — एक सामग्री, तीन ढाँचे\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">एक सामग्री, तीन ढाँचे</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सोना = साझा सच्ची सामग्री · नीचे तीन मंच-रूप</text>\n<rect x=\"220\" y=\"120\" width=\"360\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"400\" y=\"152\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\">साझा सामग्री (फ़ॉर्म से)</text>\n<text x=\"400\" y=\"182\" text-anchor=\"middle\" font-size=\"16\">नाम · सामग्री · नाप-रंग · दाम · उपयोग</text>\n<line x1=\"330\" y1=\"210\" x2=\"150\" y2=\"270\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<line x1=\"400\" y1=\"210\" x2=\"400\" y2=\"270\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<line x1=\"470\" y1=\"210\" x2=\"650\" y2=\"270\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"280\" width=\"220\" height=\"230\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"150\" y=\"310\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\">Amazon</text>\n<text x=\"60\" y=\"340\">शीर्षक: लंबा, 150-200 अक्षर</text>\n<text x=\"60\" y=\"365\">ब्रांड+नाम+गुण+नाप सब</text>\n<text x=\"60\" y=\"400\">बुलेट: 5, हर एक फ़ायदा-सहित</text>\n<text x=\"60\" y=\"440\">विवरण: कहानी+उपयोग</text>\n<text x=\"60\" y=\"480\">AI-ख़रीदार के लिए Q&amp;A अलग</text>\n<rect x=\"290\" y=\"280\" width=\"220\" height=\"230\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"310\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\">Flipkart</text>\n<text x=\"310\" y=\"340\">शीर्षक: संतुलित</text>\n<text x=\"310\" y=\"365\">ज़रूरी जानकारी पहले</text>\n<text x=\"310\" y=\"400\">बुलेट: संक्षिप्त</text>\n<text x=\"310\" y=\"440\">category-फ़ील्ड अलग</text>\n<text x=\"310\" y=\"480\">(साइज़-चार्ट आदि)</text>\n<rect x=\"540\" y=\"280\" width=\"220\" height=\"230\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"650\" y=\"310\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\">Meesho</text>\n<text x=\"560\" y=\"340\">शीर्षक: सबसे छोटा-सीधा</text>\n<text x=\"560\" y=\"365\">बजट-ग्राहक जल्दी तय करे</text>\n<text x=\"560\" y=\"400\">बुलेट: 2-3 ही</text>\n<text x=\"560\" y=\"440\">फ़ोटो-दाम ज़्यादा बोलते</text>\n<text x=\"560\" y=\"480\">शब्द कम रखो</text>\n</g>\n<rect x=\"60\" y=\"540\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"572\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">यही \"Skill→Platform अमल\" — एक हुनर (शीर्षक-लेखन), तीन पहनावे</text>\n<text x=\"400\" y=\"597\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">खंड-9-11 में इसी तरह गहराई से — यहाँ बुनियाद</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## बदलते समय क्या साथ रखें, क्या बदलें\n**साथ रखें (कभी न बदले):** सामग्री-रंग-नाप-दाम की सच्चाई; ब्रांड/उत्पाद का असली नाम। **बदलें (मंच के अनुसार):** शीर्षक की लंबाई और शब्दों का क्रम; बुलेट-पॉइंट की संख्या और गहराई; विवरण का लंबा/छोटा रूप। एक सादा तरीक़ा — पाठ-20 की \"परत-3\" (अंतिम, सबसे पूरी लिस्टिंग, Amazon-जैसी लंबी) को \"मास्टर लिस्टिंग\" मानिए; बाक़ी दो मंचों के लिए उसी में से काटिए-छाँटिए, फिर से मत लिखिए। यही तरीक़ा पाठ-19 के \"मास्टर फ़ोटो\" जैसा है — एक बड़ा-पूरा बनाओ, बाक़ी उसी से निकालो।\n\n## AI से तीन रूप एक साथ माँगना\nपाठ-20 का प्रॉम्प्ट अब एक कदम आगे — \"यह मास्टर लिस्टिंग (चिपकाइए) है; इसे Amazon, Flipkart और Meesho के लिए तीन अलग रूपों में ढालो — हर मंच की सामान्य शैली (लंबाई-क्रम) के अनुसार; कोई नई जानकारी मत जोड़ो, सिर्फ़ काटो-छाँटो-क्रम बदलो\" — यह AI के लिए आसान काम है (गढ़ने का ख़तरा कम, क्योंकि सामग्री पहले से तय)। फिर भी तीनों रूपों को एक बार पढ़िए — कहीं कोई गुण छूट तो नहीं गया जो उस मंच पर ज़रूरी है (जैसे Flipkart के category-फ़ील्ड)।\n\n## सेवा-सहायक के लिए यह हुनर सबसे बड़ी ताक़त है\nअगर आप कई दुकानदारों का काम करते हैं (मॉडल-3), तो यही \"एक सामग्री, तीन ढंग\" तरीक़ा आपकी सबसे बड़ी गति है — एक दुकानदार का उत्पाद एक बार अच्छे से लिखकर, तीन-चार मंचों पर बेच सकते हैं, बिना हर मंच के लिए शुरू से सोचे। यही कारण है कि अनुभवी सेवा-सहायक एक दिन में दस उत्पादों को कई मंचों पर चढ़ा सकते हैं — राज़ नई-नई रचनात्मकता नहीं, यही एक-मास्टर-से-कई-रूप का अनुशासन है।\n\n## एक असली उदाहरण — एक फ़ॉर्म, तीन लिस्टिंग, दस मिनट\nएक विक्रेता के पास सूती दुपट्टे का पाठ-15 का फ़ॉर्म था। Amazon के लिए: लंबा शीर्षक (कपड़ा, नाप, रंग, उपयोग, ब्रांड-नाम), पाँच बुलेट, विवरण में प्रश्न-उत्तर (पाठ-22)। Flipkart के लिए: वही, शीर्षक थोड़ा छोटा, बुलेट चार। Meesho के लिए: शीर्षक एक पंक्ति, विवरण तीन पंक्ति, कीवर्ड बोली में। तीनों में दाम-नाप-कपड़ा एक-सा (एक चीज़ = एक जगह — फ़ॉर्म/मास्टर-शीट स्रोत)। दस मिनट, क्योंकि सामग्री पहले से थी, सिर्फ़ ढंग बदला। जो सामग्री हर मंच के लिए नए सिरे से लिखता है, वह तीन गुना समय लगाकर तीन असंगत लिस्टिंग बनाता है।\n\n## मंच-रूप का एक नियम — \"मंच का ढंग, आपकी सच्चाई\"\nहर मंच अपने ढंग (लंबाई, बुलेट-संख्या, कीवर्ड-जगह) का मालिक है — उसकी शैली-गाइड मानिए; पर हर वाक्य की सच्चाई आपके फ़ॉर्म की है — मंच \"प्रीमियम\" शब्द नहीं माँगता, वह AI/आदत की भराई है। हर मंच-रूप बनाने के बाद पाठ-28 का reality-check एक बार — तीन रूप, तीन जाँच।\n\n## Skill→Platform Bridge — यही पूरे कोर्स का ढंग\nयह पाठ पहला \"Skill→Platform Bridge\" है — हुनर (लिस्टिंग लिखना, पाठ-20) एक बार, मंच-रूप तीन बार। आगे यही ढंग हर हुनर पर लौटेगा — फ़ोटो (19), Feed (25), भुगतान (41/61), AI-सहायक (57), शिपिंग (खंड-17) — हुनर सीखो एक बार, मंच बदलो नाम भर। पाठ-7 का \"ढाँचा वही, नाम बदले\" यहाँ हाथों में आता है।\n\n## 3. आज का काम «काम-कार्ड»\nपाठ-20 की अपनी \"परत-3\" (अंतिम) लिस्टिंग निकालिए। AI से तीन रूप बनवाइए — Amazon-शैली (लंबी), Flipkart-शैली (संतुलित), Meesho-शैली (छोटी) — ऊपर के प्रॉम्प्ट-तरीक़े से। तीनों को कॉपी/Word में साथ-साथ रखिए और एक तालिका बनाइए — शीर्षक-लंबाई (अक्षर-गिनती), बुलेट-संख्या, विवरण-लंबाई — तीनों मंचों की तुलना में। जाँच-सूची: ☐ मास्टर लिस्टिंग से तीन रूप बनाए ☐ सामग्री-सच्चाई तीनों में एक ☐ तुलना-तालिका (लंबाई-बुलेट-विवरण) ☐ हर रूप में कुछ छूटा तो नहीं जाँचा ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = तीनों रूप बने, सामग्री (गुण-नाप-दाम) तीनों में एक-सी सच्ची; Amazon-रूप सबसे लंबा, Meesho सबसे छोटा (क्रम सही); तुलना-तालिका भरी। समय: 30 मिनट।\n\n## 5. सबूत\nसबूत-खाते में तीनों रूप और तुलना-तालिका। यह अभ्यास खंड-9-11 (असली Amazon/Flipkart/Meesho लिस्टिंग बनाना) में सीधे दोहराया जाएगा — वहाँ असली मंच के फ़ॉर्म में यही तीन रूप भरे जाएँगे।\n\n## 6. AI-सहायक\nयह पूरा पाठ AI-सहायक पर आधारित है (ऊपर प्रॉम्प्ट-तरीक़ा)। अतिरिक्त — AI से पूछिए \"इन तीन मंचों में शीर्षक-लंबाई की सामान्य समझ क्या है?\" — दिशा के लिए; ठीक-ठीक अक्षर-सीमा (जो बदलती रहती है) मंच के पेज से (पाठ-19 जैसी MEDIUM-volatility सूचना)।\n\n## 7. आम ग़लती\nपहली — तीनों मंचों के लिए एक ही लिस्टिंग कॉपी-पेस्ट करना — Meesho पर बहुत लंबा शीर्षक अजीब दिखता है, Amazon पर बहुत छोटा शीर्षक जानकारी-कम लगता है। दूसरी — रूप बदलते समय सामग्री भी बदल देना (एक रूप में रंग \"नीला\", दूसरे में \"आसमानी\") — भ्रम और अस्वीकृति। तीसरी — हर मंच के लिए शुरू से नई लिस्टिंग लिखना — समय की बर्बादी, मास्टर से काटना तेज़ है। चौथी — Meesho-शैली को \"कम मेहनत\" समझकर लापरवाही से लिखना — छोटा होना आसान नहीं, सही शब्द चुनना कठिन हुनर है।\n\n## 8. सुरक्षा-पत्रक\nतीनों रूपों में सामग्री की सच्चाई एक-सी रहनी चाहिए — अगर एक मंच पर \"100% कॉटन\" और दूसरे पर \"कॉटन-मिक्स\" लिख दिया (ग़लती से), यह भ्रामक लिस्टिंग का उल्लंघन बन सकता है। तीनों रूप सहेजते समय फ़ाइल-नाम साफ़ रखिए (listing-amazon.docx, listing-flipkart.docx) ताकि आगे भ्रम न हो। सेवा-सहायक: दुकानदार को तीनों रूप दिखाकर पुष्टि कराइए, फिर मंच पर चढ़ाइए।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। सटीक शीर्षक-लंबाई-सीमा हर मंच बदलता रहता है — यहाँ सामान्य दिशा। 📎 मूल-कोर्स-कड़ी (कड़ियाँ): Amazon listing style guide (Seller University) · Flipkart Seller Hub listing guidelines · Meesho Supplier catalog guidelines — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=cross-platform-listing-format · platform=multi · level=O · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं तीनों मंचों के शीर्षक-ढाँचे का फ़र्क़ बता सकता हूँ।\n- [ ] मैंने अपनी मास्टर-लिस्टिंग से तीन रूप बनाए हैं।\n- [ ] मेरी सामग्री (गुण-नाप-दाम) तीनों रूपों में एक-सी है।\n- [ ] मेरी तुलना-तालिका भरी है।\n- [ ] मैं जानता हूँ कि \"एक हुनर, कई पहनावे\" का मतलब क्या है।",
 "22": "═\n# पाठ-22: AI-ख़रीदार के लिए लिखना — प्राकृतिक भाषा, प्रश्न-उत्तर शैली\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर O · रास्ता A,B · volatility HIGH Δ)*\n\n## 1. उद्देश्य\nपाठ-2 में समझा था कि ग्राहक अब AI से बातचीत-खोज करता है; आज उसी समझ को अपनी लिस्टिंग में उतारेंगे। पाठ के बाद आप तीन बातें कर पाएँगे — अपनी लिस्टिंग में \"प्रश्न-उत्तर\" खंड जोड़ पाएँगे जो AI-ख़रीदार पढ़ सके; प्राकृतिक-भाषा वाक्य और keyword-भरे वाक्य में फ़र्क़ बता पाएँगे; और पाठ-2 के अपने तीन ज़रूरत-वाक्यों को आज असली लिस्टिंग में जोड़ पाएँगे।\n\n## 2. मुख्य बात\nपुरानी सलाह थी \"जितने ज़्यादा keyword भरो, उतना अच्छा\"; आज की सलाह अलग है। एक-वाक्य बात — **लिस्टिंग को इंसान की तरह पढ़िए और लिखिए — जैसे कोई ग्राहक दुकान पर आकर पूछे \"यह धुलेगा कैसे?\", वैसा ही एक सवाल-जवाब लिस्टिंग में डालिए; AI-सहायक इन्हीं सवाल-जवाबों से आपके उत्पाद को सही ग्राहक तक पहुँचाता है।**\n\n## प्राकृतिक-भाषा बनाम keyword-भराई — उदाहरण से\n**keyword-भराई (पुराना, कमज़ोर तरीक़ा):** \"कुर्ती कॉटन कुर्ती लेडीज़ कुर्ती नीली कुर्ती सस्ती कुर्ती।\" **प्राकृतिक-भाषा (आज का सही तरीक़ा):** \"यह हल्की कॉटन कुर्ती गर्मी में आराम देती है और मशीन में आसानी से धुल जाती है — रोज़ पहनने और छोटे त्योहार दोनों के लिए उपयुक्त।\" दूसरा वाक्य पढ़ने में भी अच्छा लगता है और AI-सहायक भी इसे बेहतर समझता है, क्योंकि यह असली इंसान की भाषा है। पाठ-20-21 में जो लिस्टिंग बनाई, अगर उसमें अब भी keyword-भराई की झलक हो, आज उसे प्राकृतिक बनाइए।\n\n## चित्र — प्रश्न-उत्तर खंड कैसे जोड़ें\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">AI-ख़रीदार के लिए लिखना</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सोना = लिस्टिंग में नया जोड़ — प्रश्न-उत्तर खंड</text>\n<rect x=\"40\" y=\"120\" width=\"330\" height=\"200\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"205\" y=\"152\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">✗ keyword-भराई</text>\n<text x=\"205\" y=\"185\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">\"कुर्ती कॉटन कुर्ती लेडीज़</text>\n<text x=\"205\" y=\"208\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">कुर्ती नीली कुर्ती सस्ती\"</text>\n<text x=\"205\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">पढ़ने में अजीब · AI-समझ कम</text>\n<text x=\"205\" y=\"280\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">आज कम असरदार</text>\n<rect x=\"430\" y=\"120\" width=\"330\" height=\"200\" rx=\"12\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"595\" y=\"152\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">✓ प्राकृतिक-भाषा</text>\n<text x=\"595\" y=\"185\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">\"हल्की कॉटन कुर्ती —</text>\n<text x=\"595\" y=\"205\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">गर्मी में आराम,</text>\n<text x=\"595\" y=\"225\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">मशीन में धुल जाती है\"</text>\n<text x=\"595\" y=\"260\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">इंसान भी पढ़े, AI भी समझे</text>\n<text x=\"595\" y=\"290\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">आज सही तरीक़ा</text>\n<rect x=\"60\" y=\"350\" width=\"680\" height=\"300\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"384\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">प्रश्न-उत्तर खंड — पाठ-2 के तीन वाक्य लौटे</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"420\" font-weight=\"bold\">प्र: क्या यह मशीन में धुल सकती है?</text>\n<text x=\"90\" y=\"445\">उ: हाँ, हल्के पानी में मशीन-धुलाई कर सकते हैं।</text>\n<text x=\"90\" y=\"480\" font-weight=\"bold\">प्र: यह कितने साइज़ में मिलती है?</text>\n<text x=\"90\" y=\"505\">उ: S, M, L — छाती-नाप 34″-40″।</text>\n<text x=\"90\" y=\"540\" font-weight=\"bold\">प्र: यह कितने दिन में पहुँचेगी?</text>\n<text x=\"90\" y=\"565\">उ: आम तौर पर 5-7 दिन (मंच के अनुसार बदल सकता है)।</text>\n<text x=\"90\" y=\"610\" fill=\"#2E7D32\">ये तीनों सवाल पाठ-2 के \"ज़रूरत-वाक्य\" अभ्यास से आए</text>\n</g>\n<rect x=\"60\" y=\"670\" width=\"680\" height=\"40\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"2\"/>\n<text x=\"400\" y=\"696\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">8-12 प्रश्न-उत्तर का सुझाव — खंड-9 में Amazon के लिए गहराई से</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## प्रश्न-उत्तर खंड कैसे बनाएँ\nतीन तरीक़ों से सवाल इकट्ठा कीजिए — (1) पाठ-2 के अपने ज़रूरत-वाक्य (वहाँ आपने ग्राहक-भाषा में तीन सवाल लिखे थे — आज उन्हीं को यहाँ इस्तेमाल कीजिए); (2) अपनी दुकान पर ग्राहक जो असली सवाल पूछते हैं, याद कीजिए या दुकानदार से पूछिए; (3) AI से पूछिए \"इस उत्पाद के लिए ग्राहक सबसे ज़्यादा कौन-से 5 सवाल पूछ सकता है\" — फिर हर सवाल का सच्चा, छोटा जवाब पाठ-15 के फ़ॉर्म से लिखिए। शुरुआत में 3-5 प्रश्न-उत्तर काफ़ी हैं; खंड-9 (Amazon) में इसे 8-12 तक बढ़ाना सीखेंगे।\n\n## यह पाठ HIGH-volatility क्यों\nAI-ख़रीदार किस तरह के वाक्य/शब्द को \"बेहतर\" समझता है, यह हर कुछ महीनों में सुधरता-बदलता है — क्योंकि AI-सहायक ख़ुद सीखते रहते हैं। जो आज सबसे अच्छा तरीक़ा है (सच्चे प्रश्न-उत्तर, सादी भाषा), वह कल भी काम आएगा — पर मंच के सुझाव (कितने प्रश्न-उत्तर अच्छे, कहाँ रखें) समय-समय पर बदलते हैं। इसलिए मूल-कोर्स-कड़ी और जाँच-तारीख़ यहाँ ख़ासकर ज़रूरी हैं।\n\n## एक असली उदाहरण — दो लिस्टिंग, दो नतीजे\nमान लो एक ही सूती कुर्ती दो विक्रेता बेचते हैं। पहला लिखता है — \"कुर्ती लेडीज़ कुर्ती कॉटन कुर्ती ऑफ़िस कुर्ती\" — शब्द दस बार दोहराए, पर एक भी सवाल का जवाब नहीं। दूसरा लिखता है — \"क्या यह गर्मी में चलेगी? हाँ, हल्का सूती कपड़ा है, पसीना सोखता है। धोने पर रंग जाता है? पहली दो धुलाई अलग करें, फिर नहीं। ऑफ़िस के लिए ठीक है? हाँ, सादा रंग और घुटने तक लंबाई है।\" जब ग्राहक AI-सहायक से पूछता है \"गर्मी के ऑफ़िस के लिए सूती कुर्ती जो धुलने में झंझट न दे\", सहायक दूसरी लिस्टिंग को पकड़ता है — क्योंकि उसमें ग्राहक के सवाल के सीधे जवाब हैं। पहली लिस्टिंग में शब्द तो थे, समझ नहीं थी।\n\n## तीन तरह के सवाल जो हर उत्पाद में होते हैं\nहर उत्पाद के प्रश्न-उत्तर तीन ढाँचों में आते हैं — (1) **उपयोग-सवाल** — \"यह किस काम आएगा, किस मौसम/उम्र/मौक़े में?\"; (2) **देखभाल-सवाल** — \"धोना, रखना, चार्ज करना, कितने दिन चलेगा?\"; (3) **मेल-सवाल** — \"मेरे पास जो है उसके साथ चलेगा? साइज़ बड़ा-छोटा तो नहीं?\" शुरुआत में हर ढाँचे से एक-एक सवाल लीजिए — तीन सवाल तैयार। जवाब हमेशा पाठ-15 के फ़ॉर्म से — जो फ़ॉर्म में नहीं, वह जवाब में भी नहीं (पाठ-28 का reality-check यहीं से शुरू होता है)।\n\n## बोली का ध्यान — ग्राहक जैसा पूछता है, वैसा लिखो\nग्राहक \"क्या यह वस्त्र ग्रीष्म-ऋतु में उपयुक्त है\" नहीं पूछता — वह पूछता है \"गर्मी में चलेगा?\" प्रश्न-उत्तर में सवाल ग्राहक की असली बोली में लिखिए, जवाब सादी हिंदी में। Roman-हिंदी में पूछे जाने वाले सवाल (\"machine me dhul jayega?\") का जवाब भी देवनागरी में ठीक है — AI-सहायक दोनों जोड़ लेता है, पर सवाल का ढंग ग्राहक जैसा रहे तो मेल बेहतर बैठता है।\n\n## 3. आज का काम «काम-कार्ड»\nपाठ-20-21 की अपनी लिस्टिंग निकालिए। हर वाक्य पढ़िए — कहीं keyword-भराई (एक ही शब्द बार-बार, अजीब क्रम) दिखे तो प्राकृतिक-भाषा में बदलिए। फिर पाठ-2 के तीन ज़रूरत-वाक्यों को प्रश्न-उत्तर के रूप में लिखिए (सवाल + सच्चा जवाब), और दो और सवाल AI/दुकानदार से जोड़कर कुल 5 प्रश्न-उत्तर बनाइए। इन्हें अपनी लिस्टिंग के अंत में \"अक्सर पूछे जाने वाले सवाल\" खंड की तरह जोड़िए। जाँच-सूची: ☐ keyword-भराई ढूँढी-सुधारी ☐ पाठ-2 के 3 वाक्य प्रश्न-उत्तर बने ☐ 2 नए सवाल जोड़े (कुल 5) ☐ लिस्टिंग में जोड़ा ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = लिस्टिंग में keyword-भराई शून्य, हर वाक्य पढ़ने में सहज; 5 प्रश्न-उत्तर मौजूद, हर जवाब फ़ॉर्म से सच्चा और छोटा (एक-दो वाक्य); पाठ-2 के तीनों वाक्य पहचाने जा सकें। समय: 30 मिनट।\n\n## 5. सबूत\nसबूत-खाते में पहले-बाद की लिस्टिंग (keyword-भराई बनाम प्राकृतिक) और प्रश्न-उत्तर खंड। खंड-9 (पाठ-125) में यही प्रश्न-उत्तर 8-12 तक बढ़ेंगे — आज की नींव वहाँ सीधे इस्तेमाल होगी।\n\n## 6. AI-सहायक\nAI से पूछिए — \"इस लिस्टिंग (चिपकाइए) में कहीं keyword-भराई या अजीब वाक्य हैं जो इंसान नहीं बोलता?\" — निशान लगवाइए, ख़ुद सुधारिए। दूसरा — \"इस उत्पाद के लिए ग्राहक 5 सबसे आम सवाल क्या पूछेगा?\" — मिले सवालों को अपनी सूची से मिलाइए, नए जोड़िए। जवाब हमेशा अपने फ़ॉर्म से जाँचकर लिखिए, AI का जवाब सीधे कॉपी न करें।\n\n## 7. आम ग़लती\nपहली — प्रश्न-उत्तर खंड में AI का पूरा जवाब बिना जाँचे रख देना — गढ़ी जानकारी लिस्टिंग में घुस जाती है। दूसरी — keyword-भराई पूरी तरह हटाकर लिस्टिंग को इतना \"साहित्यिक\" बना देना कि मुख्य जानकारी (नाप-दाम) पीछे छिप जाए — संतुलन चाहिए। तीसरी — प्रश्न-उत्तर बहुत लंबे लिखना — सवाल छोटा, जवाब छोटा-सच्चा, यही सही। चौथी — पाठ-2 के अपने ज़रूरत-वाक्यों को भूल जाना/दोबारा न देखना — वे आपकी सबसे असली सामग्री हैं, इसलिए पीछे से जोड़ना ज़रूरी।\nपाँचवीं — हर सवाल के जवाब में \"हाँ, बिल्कुल, सबसे अच्छा\" जैसा बिक्री-भाषण जोड़ना; जवाब तथ्य हो, तारीफ़ नहीं। छठी — दस-बारह सवाल एक साथ ठूँस देना और हर जवाब आधा-अधूरा छोड़ना; तीन पूरे, सच्चे जवाब दस अधूरे जवाबों से बेहतर हैं। सातवीं — प्रश्न-उत्तर एक बार लिखकर भूल जाना; जब ग्राहक नया सवाल बार-बार पूछे, वही अगला प्रश्न-उत्तर बनना चाहिए।\n\n## 8. सुरक्षा-पत्रक\nप्रश्न-उत्तर में स्वास्थ्य/सुरक्षा से जुड़े दावे (जैसे \"यह एलर्जी नहीं करता\") बिना ठोस आधार के न लिखें — यह गढ़ी बात से भी ज़्यादा जोखिम भरी है। ग्राहक के असली पुराने सवाल (शिकायत वाले) को प्रश्न-उत्तर में डालते समय ग्राहक का नाम/पहचान न आए — सिर्फ़ सवाल-जवाब, सामान्य रूप में।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। AI-ख़रीदार-समझ की गहराई तेज़ी से बदल रही है। 📎 मूल-कोर्स-कड़ी: Amazon के AI-ख़रीद-सहायक हेतु लिस्टिंग-सुझाव — Seller University · Google का \"Conversational\" उत्पाद-विवरण सुझाव — support.google.com/merchants — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=natural-language-listing · platform=none · level=O · path=A,B · volatility=HIGH · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं keyword-भराई और प्राकृतिक-भाषा का फ़र्क़ उदाहरण से बता सकता हूँ।\n- [ ] मैंने अपनी लिस्टिंग से keyword-भराई हटाई है।\n- [ ] मेरी लिस्टिंग में 5 सच्चे प्रश्न-उत्तर हैं।\n- [ ] मैंने पाठ-2 के तीन ज़रूरत-वाक्य आज इस्तेमाल किए हैं।\n- [ ] मैं जानता हूँ कि यह पाठ Δ क्यों है।",
 "23": "═\n# पाठ-23: कीवर्ड बनाम बोली — \"बच्चों की ड्रेस\" कैसे खोजा जाता है\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर O · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nपाठ-22 में \"प्राकृतिक-भाषा\" सीखी; आज देखेंगे कि उसी भाषा में सही keyword (जो ग्राहक टाइप/बोलता है) कैसे पिरोए जाएँ — क्योंकि प्राकृतिक होना और keyword-रहित होना एक बात नहीं है। पाठ के बाद आप तीन बातें कर पाएँगे — अपने उत्पाद के लिए ग्राहक की असली बोली में 5-8 खोज-शब्द ढूँढ पाएँगे; उन्हें प्राकृतिक वाक्यों में स्वाभाविक तरीक़े से पिरो पाएँगे; और समझ पाएँगे कि \"बच्चों की ड्रेस\" जैसा उदाहरण कैसे अलग-अलग तरीक़ों से खोजा जाता है।\n\n## 2. मुख्य बात\nपाठ-22 में keyword-भराई को ग़लत बताया — इसका मतलब keyword छोड़ना नहीं है, उसे सही जगह, सही मात्रा में, सही भाषा में रखना है। एक-वाक्य बात — **ग्राहक जो शब्द टाइप/बोलता है, वही शब्द आपकी लिस्टिंग में स्वाभाविक वाक्य के भीतर होने चाहिए — न बार-बार दोहराए (keyword-भराई), न बिल्कुल ग़ायब (तो खोज में मिलेगा ही नहीं)।**\n\n## \"बच्चों की ड्रेस\" — कई तरह से खोजी जाती है\nGoogle का एक मशहूर उदाहरण है — \"bacho ke liye dress\" टाइप करने पर मशीन समझती है ग्राहक \"dress for kids\" ढूँढ रहा है। एक ही चीज़ को ग्राहक अलग-अलग तरीक़ों से खोजता है — हिंदी में (\"बच्चों के कपड़े\"), Roman-हिंदी में (\"bachon ke kapde\"), अंग्रेज़ी में (\"kids dress\"), बोलचाल में (\"छोटे बच्चे का फ्रॉक\"), उम्र-सहित (\"2 साल के बच्चे के कपड़े\"), मौक़े-सहित (\"बर्थडे पार्टी ड्रेस बच्चों के लिए\")। आपकी लिस्टिंग में जितने ज़्यादा (पर स्वाभाविक) ऐसे रूप आएँ, उतने ज़्यादा तरीक़ों से ग्राहक आपको ढूँढ पाता है — यह \"कीवर्ड सोच\" कहलाती है।\n\n## चित्र — एक उत्पाद, कई खोज-रास्ते\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">एक उत्पाद, कई खोज-रास्ते — \"बच्चों की ड्रेस\"</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सोना = आपकी लिस्टिंग जहाँ सब रास्ते मिलें</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"180\" height=\"60\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/><text x=\"130\" y=\"155\" text-anchor=\"middle\">\"बच्चों के कपड़े\"</text>\n<rect x=\"240\" y=\"120\" width=\"180\" height=\"60\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/><text x=\"330\" y=\"155\" text-anchor=\"middle\">\"bachon ke kapde\"</text>\n<rect x=\"440\" y=\"120\" width=\"150\" height=\"60\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/><text x=\"515\" y=\"155\" text-anchor=\"middle\">\"kids dress\"</text>\n<rect x=\"610\" y=\"120\" width=\"150\" height=\"60\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/><text x=\"685\" y=\"155\" text-anchor=\"middle\">\"छोटे बच्चे का फ्रॉक\"</text>\n<rect x=\"140\" y=\"200\" width=\"200\" height=\"60\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/><text x=\"240\" y=\"235\" text-anchor=\"middle\">\"2 साल के बच्चे के कपड़े\"</text>\n<rect x=\"380\" y=\"200\" width=\"260\" height=\"60\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/><text x=\"510\" y=\"235\" text-anchor=\"middle\">\"बर्थडे पार्टी ड्रेस बच्चों के लिए\"</text>\n</g>\n<line x1=\"130\" y1=\"180\" x2=\"330\" y2=\"290\" stroke=\"#0B1F3A\" stroke-width=\"2\"/>\n<line x1=\"330\" y1=\"180\" x2=\"360\" y2=\"290\" stroke=\"#0B1F3A\" stroke-width=\"2\"/>\n<line x1=\"515\" y1=\"180\" x2=\"420\" y2=\"290\" stroke=\"#0B1F3A\" stroke-width=\"2\"/>\n<line x1=\"685\" y1=\"180\" x2=\"450\" y2=\"290\" stroke=\"#0B1F3A\" stroke-width=\"2\"/>\n<line x1=\"240\" y1=\"260\" x2=\"360\" y2=\"290\" stroke=\"#0B1F3A\" stroke-width=\"2\"/>\n<line x1=\"510\" y1=\"260\" x2=\"430\" y2=\"290\" stroke=\"#0B1F3A\" stroke-width=\"2\"/>\n<rect x=\"220\" y=\"300\" width=\"360\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"400\" y=\"335\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">आपकी लिस्टिंग</text>\n<text x=\"400\" y=\"365\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">स्वाभाविक वाक्यों में सब रास्ते समाहित</text>\n<rect x=\"60\" y=\"420\" width=\"680\" height=\"200\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"454\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">कीवर्ड कैसे ढूँढें — तीन मुफ़्त तरीक़े</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"490\">1. मंच के अपने खोज-बक्से में उत्पाद टाइप करके देखो — नीचे \"सुझाव\" में और शब्द दिखेंगे</text>\n<text x=\"90\" y=\"524\">2. ग्राहक/परिवार से पूछो — \"अगर तुम्हें यह चाहिए होता, तो क्या टाइप करते?\"</text>\n<text x=\"90\" y=\"558\">3. AI से पूछो — \"इस उत्पाद के लिए ग्राहक हिंदी/Roman/अंग्रेज़ी में कैसे खोजेगा?\"</text>\n</g>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## कीवर्ड ढूँढने के तीन मुफ़्त तरीक़े\n**(1) मंच का अपना खोज-बक्सा** — Amazon/Flipkart/Meesho के ऐप में अपने उत्पाद का नाम टाइप करना शुरू कीजिए, नीचे जो \"सुझाव\" (auto-suggest) दिखते हैं, वही ग्राहक सबसे ज़्यादा खोजते हैं — यह सबसे सटीक, मुफ़्त तरीक़ा है। **(2) असली लोगों से पूछना** — परिवार, पड़ोसी, ग्राहक से पूछिए \"अगर तुम्हें यह उत्पाद चाहिए होता, तुम क्या टाइप/बोलते?\" — गाँव-शहर, उम्र, इलाके के हिसाब से जवाब अलग-अलग आते हैं, यही आपकी असली कीवर्ड-सूची है। **(3) AI से पूछना** — \"इस उत्पाद के लिए ग्राहक हिंदी, Roman-हिंदी, अंग्रेज़ी में किन-किन शब्दों से खोजेगा?\" — पर AI का सुझाव भी असली मंच-खोज (तरीक़ा-1) से मिलाइए।\n\n## पिरोना — स्वाभाविक जगह, सही मात्रा\n5-8 कीवर्ड मिलने के बाद उन्हें शीर्षक, बुलेट, विवरण और प्रश्न-उत्तर (पाठ-22) में इस तरह पिरोइए कि वाक्य स्वाभाविक बना रहे। जैसे — शीर्षक में मुख्य 2-3 (जैसे \"बच्चों के कपड़े\", \"kids dress\"), विवरण में बाक़ी स्वाभाविक रूप से आ जाएँ (\"यह ड्रेस बर्थडे पार्टी और रोज़ के लिए दोनों उपयुक्त है\")। एक कीवर्ड को 3-4 बार से ज़्यादा दोहराना फिर से keyword-भराई बन जाता है (पाठ-22) — संतुलन यही है।\n\n## एक असली उदाहरण — मिट्टी की सुराही, चार बोली\nगाँव का कुम्हार सुराही बेचना चाहता है। खोज-बक्से में टाइप करने पर सुझाव आए — \"मिट्टी की सुराही\", \"clay water pot\", \"matka bottle\", \"गर्मी में ठंडा पानी बर्तन\"। परिवार से पूछने पर एक बुज़ुर्ग ने कहा \"मटका\", एक युवा ने \"clay pot with tap\", एक बच्चे ने \"मिट्टी वाली बोतल\"। AI ने जोड़ा \"eco-friendly earthen pot\", \"देसी फ़्रिज\"। अब सूची में सात रूप हैं — शीर्षक में \"मिट्टी की सुराही (Clay Water Pot) — नल सहित\"; विवरण में \"गर्मी में बिना बिजली ठंडा पानी — देसी फ़्रिज जैसा; मटका-शैली, पर नल लगा\"। हर रूप एक-एक बार, स्वाभाविक जगह — यही सही पिरोना है। ध्यान दीजिए, \"eco-friendly\" जैसा दावा तभी लिखा जब फ़ॉर्म में \"बिना रसायन, सिर्फ़ मिट्टी\" दर्ज था।\n\n## बोली बनाम भाषा — दोनों अलग हैं\nभाषा = हिंदी/अंग्रेज़ी/Roman-हिंदी; बोली = उसी भाषा में लोग असल में क्या शब्द चुनते हैं। \"बच्चों की ड्रेस\" हिंदी है, \"बच्चा-पार्टी वाला फ्रॉक\" बोली है। मंच का खोज-बक्सा भाषा दिखाता है, असली लोग बोली दिखाते हैं — इसलिए तरीक़ा-1 और तरीक़ा-2 दोनों ज़रूरी हैं, एक से काम नहीं चलता। इलाक़ा बदलते ही बोली बदलती है — बिहार में \"फ्रॉक\", कहीं \"झबला\", कहीं \"फ़्रॉक-सूट\" — अगर आप एक से ज़्यादा राज्य में बेचते हैं, हर राज्य का एक शब्द जोड़िए।\n\n## कीवर्ड की जाँच-सूची — पिरोने के बाद\nलिस्टिंग लिखने के बाद तीन बार पढ़िए — पहली बार ग्राहक बनकर (क्या यह मुझे मिलेगी अगर मैं \"kids party frock\" टाइप करूँ?), दूसरी बार AI-सहायक बनकर (क्या वाक्य समझ आते हैं, या शब्दों का ढेर है?), तीसरी बार दुकानदार बनकर (क्या हर शब्द सच है?)। तीनों में पास = तैयार।\n\n## 3. आज का काम «काम-कार्ड»\nअपने उत्पाद के लिए तीनों तरीक़ों से 5-8 कीवर्ड जुटाइए — मंच के खोज-बक्से में टाइप करके सुझाव देखिए (या Google में), किसी परिवार-सदस्य से पूछिए, AI से पूछिए। सबको कॉपी में एक सूची में लिखिए — भाषा-रूप (हिंदी/Roman/अंग्रेज़ी) के साथ। फिर पाठ-20-22 की अपनी लिस्टिंग में देखिए कौन-से कीवर्ड पहले से हैं, कौन-से छूटे — छूटे हुए को स्वाभाविक वाक्यों में जोड़िए। जाँच-सूची: ☐ तीनों तरीक़ों से कीवर्ड जुटाए ☐ सूची भाषा-रूप सहित ☐ लिस्टिंग में स्वाभाविक जोड़ा ☐ किसी कीवर्ड को 4 से ज़्यादा नहीं दोहराया ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = 5-8 कीवर्ड की सूची, कम-से-कम दो भाषा-रूप (हिंदी+Roman या अंग्रेज़ी); लिस्टिंग में जोड़े गए कीवर्ड वाक्य में स्वाभाविक लगें (ज़ोर से पढ़कर जाँचिए — अजीब लगे तो सुधारिए); कोई एक शब्द 4 से ज़्यादा बार नहीं। समय: 30 मिनट।\n\n## 5. सबूत\nसबूत-खाते में कीवर्ड-सूची और सुधरी लिस्टिंग। यह हुनर खंड-9 (पाठ-100, AI-ख़रीदार के लिए) में \"backend search terms\" (छुपे कीवर्ड-खाने) के साथ और गहराई से लौटेगा।\n\n## 6. AI-सहायक\nAI से पूछिए — \"मेरा उत्पाद (नाम) है, ग्राहक भारत में इसे किन-किन शब्दों/तरीक़ों (हिंदी, Roman, अंग्रेज़ी, बोलचाल) से खोज सकता है?\" — मिली सूची को मंच के असली खोज-सुझाव से मिलाइए (AI कभी-कभी शहरी/अंग्रेज़ी-भारी शब्द ज़्यादा सुझाता है — आपके ग्राहक की असली भाषा ज़्यादा भरोसेमंद है)।\n\n## 7. आम ग़लती\nपहली — सिर्फ़ अंग्रेज़ी कीवर्ड जुटाना, हिंदी/Roman-हिंदी छोड़ देना — भारत के बहुत-से ग्राहक अपनी भाषा में खोजते हैं। दूसरी — कीवर्ड ढूँढकर उन्हें अलग से \"keyword: xyz\" जैसे लिख देना — यह फिर वही keyword-भराई है, वाक्य में पिरोना ज़रूरी। तीसरी — कीवर्ड-खोज एक बार करके भूल जाना — त्योहार/मौसम बदलने पर खोज-शब्द भी बदलते हैं (जैसे \"राखी गिफ्ट\" सिर्फ़ त्योहार में)। चौथी — बहुत दूर के, बेमेल कीवर्ड जोड़ना (ग्राहक को लुभाने के लिए बेमेल शब्द) — यह ग़लत ग्राहक लाता है, रिटर्न बढ़ता है।\nपाँचवीं — सिर्फ़ अंग्रेज़ी कीवर्ड भरना और सोचना \"मंच अंग्रेज़ी में चलता है\"; भारत का बड़ा ग्राहक हिंदी/Roman-हिंदी में खोजता है। छठी — किसी बड़े ब्रांड का नाम कीवर्ड की तरह डालना (\"Fabindia जैसी कुर्ती\") — यह नीति-उल्लंघन है और खाता ख़तरे में डालता है। सातवीं — कीवर्ड-सूची एक बार बनाकर सालों न बदलना; मौसम, त्योहार, नया चलन — हर तीन महीने खोज-बक्सा दोबारा देखिए।\n\n## 8. सुरक्षा-पत्रक\nकिसी और की मशहूर ब्रांड का नाम कीवर्ड की तरह चुपके से जोड़ना (जैसे अपने सामान्य जूते में \"जैसा Nike\" लिखना) — यह ब्रांड-उल्लंघन और भ्रामक दोनों है, मना। कीवर्ड-खोज करते समय मंच के खोज-बक्से में सिर्फ़ देखना है, कुछ ख़रीदना/चढ़ाना नहीं।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। \"bacho ke liye dress\" जैसे उदाहरण मंचों की सार्वजनिक जानकारी पर आधारित। 📎 मूल-कोर्स-कड़ी: Amazon \"Search terms/Backend keywords\" सुझाव — Seller University · Google Keyword समझ (सामान्य) — support.google.com/merchants — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=keyword-research · platform=multi · level=O · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं keyword-भराई और सही कीवर्ड-उपयोग का फ़र्क़ बता सकता हूँ।\n- [ ] मैंने तीनों तरीक़ों से 5-8 कीवर्ड जुटाए हैं।\n- [ ] मैंने कीवर्ड को स्वाभाविक वाक्यों में पिरोया है।\n- [ ] मैं जानता हूँ कि हिंदी/Roman/अंग्रेज़ी तीनों भाषा-रूप क्यों ज़रूरी हैं।\n- [ ] मैं जानता हूँ कि त्योहार-मौसम के साथ कीवर्ड बदलते हैं।",
 "24": "═\n# पाठ-24: HSN और GST-दर — AI-सुझाव लो, आधिकारिक सूची से मिलाओ\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर O · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nलिस्टिंग की \"बात\" (शीर्षक-विवरण) तैयार हो गई; अब उसके पीछे का एक तकनीकी पर ज़रूरी हिस्सा — HSN कोड और GST-दर। पाठ के बाद आप तीन बातें कर पाएँगे — HSN कोड क्या है और क्यों चाहिए, बता पाएँगे; अपने उत्पाद का सही HSN और GST-दर आधिकारिक सूची से ढूँढ पाएँगे; और समझ पाएँगे कि AI यहाँ सिर्फ़ \"सुझाव\" दे सकता है, \"फ़ैसला\" नहीं।\n\n## 2. मुख्य बात\nहर मार्केटप्लेस-लिस्टिंग में एक खाना होता है — HSN कोड — जो बताता है आपका सामान किस \"श्रेणी\" का है, टैक्स की दृष्टि से। एक-वाक्य बात — **HSN कोड = सामान की टैक्स-श्रेणी की पहचान-संख्या; ग़लत HSN = ग़लत GST-दर = बाद में जुर्माना या रिफ़ंड की झंझट; AI से सुझाव लो, पर आख़िरी जाँच सरकार की आधिकारिक HSN-सूची या GST-सुविधा-केंद्र से।**\n\n## HSN कोड क्या है — सादी समझ\nHSN का मतलब है \"Harmonized System of Nomenclature\" — दुनिया-भर में सामान को एक जैसे कोड-नंबर से पहचानने की व्यवस्था (जैसे \"6109\" कपड़ों की एक श्रेणी के लिए)। भारत में हर उत्पाद बेचते समय बिल/लिस्टिंग में यह कोड लिखना होता है, और इसी कोड से तय होता है कि GST कितने प्रतिशत लगेगा (0%, 5%, 12%, 18%, 28% — श्रेणी अनुसार)। कपड़ा, खाना, इलेक्ट्रॉनिक्स, हस्तशिल्प — हर श्रेणी का अपना HSN और अपनी GST-दर। यह जानकारी पाठ-9 के \"GST या छूट\" वाले दस्तावेज़ से जुड़ी है — वहाँ आपने तय किया था GST-नंबर चाहिए या नहीं; आज उसी नंबर के साथ सही HSN चुनना है।\n\n## चित्र — HSN कैसे ढूँढें, कैसे जाँचें\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">HSN कोड ढूँढना और जाँचना</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सोना = अंतिम पक्का स्रोत</text>\n<g font-size=\"16\" fill=\"#0B1F3A\" text-anchor=\"middle\">\n<rect x=\"40\" y=\"120\" width=\"220\" height=\"120\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"150\" y=\"155\" font-size=\"18\" font-weight=\"bold\">1. AI से सुझाव</text><text x=\"150\" y=\"185\">\"मेरा उत्पाद (नाम) है,</text><text x=\"150\" y=\"207\">सामान्य HSN क्या हो सकता?\"</text>\n<rect x=\"290\" y=\"120\" width=\"220\" height=\"120\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"155\" font-size=\"18\" font-weight=\"bold\">2. मंच का सुझाव</text><text x=\"400\" y=\"185\">Amazon/Flipkart अक्सर</text><text x=\"400\" y=\"207\">श्रेणी-चुनाव पर ख़ुद सुझाते</text>\n<rect x=\"540\" y=\"120\" width=\"220\" height=\"120\" rx=\"12\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"650\" y=\"155\" font-size=\"18\" font-weight=\"bold\">3. GST-पोर्टल से मिलान</text><text x=\"650\" y=\"185\">आधिकारिक HSN-सूची</text><text x=\"650\" y=\"207\">यही अंतिम पक्का जवाब</text>\n</g>\n<line x1=\"260\" y1=\"180\" x2=\"282\" y2=\"180\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><polygon points=\"290,180 274,170 274,190\" fill=\"#0B1F3A\"/>\n<line x1=\"510\" y1=\"180\" x2=\"532\" y2=\"180\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><polygon points=\"540,180 524,170 524,190\" fill=\"#0B1F3A\"/>\n<rect x=\"60\" y=\"290\" width=\"680\" height=\"220\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"324\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">HSN-सुधार पर्ची — नमूना</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"362\">उत्पाद: हाथ की कढ़ाई वाली कॉटन कुर्ती</text>\n<text x=\"90\" y=\"396\">AI-सुझाव HSN: 6204 (महिलाओं के परिधान)</text>\n<text x=\"90\" y=\"430\">GST-पोर्टल से मिलान: ✓ मेल खाता / जाँच जारी</text>\n<text x=\"90\" y=\"464\">GST-दर (श्रेणी अनुसार): 5% या 12% (दाम-सीमा पर निर्भर — पोर्टल देखें)</text>\n</g>\n<rect x=\"60\" y=\"530\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"562\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">ग़लत HSN = ग़लत टैक्स = जुर्माना/झंझट बाद में</text>\n<text x=\"400\" y=\"592\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">AI सुझाव भर देता है — पक्का फ़ैसला GST-पोर्टल/CA से</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## तीन कदम — AI से मंच तक, अंतिम पक्का GST-पोर्टल से\n**कदम-1:** AI से पूछिए \"मेरा उत्पाद (नाम, सामग्री, उपयोग) है — भारत में इसका सामान्य HSN कोड और GST-दर क्या हो सकती है?\" — AI एक सुझाव देगा, यह शुरुआती दिशा है। **कदम-2:** जब आप मंच पर लिस्टिंग बनाएँगे (खंड 9-11), वहाँ अक्सर श्रेणी चुनने पर मंच ख़ुद HSN का खाना दिखाता/सुझाता है — इसे भी नोट कीजिए। **कदम-3 (अंतिम, पक्का):** सरकार की आधिकारिक HSN/GST-दर सूची (GST-पोर्टल) पर अपने उत्पाद की श्रेणी खोजकर मिलाइए — जहाँ शक हो, GST-सुविधा-केंद्र या CA से पूछिए (पाठ-9 का वही नियम — ACS कर-सलाह नहीं देता, पुल है)। तीनों मिलें तो निश्चिंत रहिए; न मिलें तो कदम-3 का जवाब मानिए।\n\n## HSN-सुधार पर्ची — अपने उत्पाद-फ़ॉर्म में जोड़ें\nपाठ-15 के उत्पाद-जानकारी फ़ॉर्म में अब एक नया खाना जोड़िए — \"HSN कोड\" और \"GST-दर (अगर लागू)\"। यह पर्ची आगे हर मंच पर लिस्टिंग बनाते समय (खंड 9-11) और बिल बनाते समय (पाठ-31) बार-बार काम आएगी — एक बार सही ढूँढ लेने के बाद दोबारा खोजना नहीं पड़ता, जब तक उत्पाद-श्रेणी न बदले।\n\n## GST-दर बदलने पर क्या करें\nसरकार समय-समय पर GST-दरों में बदलाव करती है — कोई श्रेणी 12% से 5% हो सकती है, कोई नई श्रेणी जुड़ सकती है। इसलिए HSN-कोड एक बार तय होने के बाद भी, हर 6 महीने में एक बार GST-पोर्टल पर अपनी श्रेणी की दर दोबारा जाँचना अच्छी आदत है (पाठ-319 के \"तिमाही ताज़गी-जाँच\" काम-कार्ड में यह भी शामिल होगा)। अगर दर बदल गई हो, अपने मास्टर उत्पाद-शीट (पाठ-25) में और हर मंच की लिस्टिंग में इसे अपडेट करना ज़रूरी है — पुरानी दर पर बिल बनाना ग़लत हिसाब देता है।\n\n## एक असली उदाहरण — एक अंक की चूक, एक महीने की झंझट\nएक विक्रेता ने AI से HSN पूछा, जवाब बिना जाँचे मंच में डाला — कोड मिलते-जुलते उत्पाद-वर्ग का था, GST-दर अलग। महीने बाद कर-गणना में फ़र्क़, सुधार-दाख़िल, CA की फ़ीस, समय। दूसरी बार उसने AI का सुझाव लिया, फिर आधिकारिक HSN-सूची/GST-पोर्टल पर वही कोड खोजा, विवरण अपने उत्पाद से मिलाया, और CA से एक पंक्ति में पुष्टि — तब मंच में डाला। AI ने खोज दस मिनट की बचाई; आधिकारिक-मिलान ने महीने की झंझट रोकी। यही \"AI-सुझाव लो, आधिकारिक से मिलाओ\" का असली मतलब है।\n\n## HSN मास्टर-शीट में — एक बार सही, हर मंच पर वही\nपाठ-26 की मास्टर-शीट में HSN-स्तंभ, हर उत्पाद पर एक बार जाँचा हुआ कोड (स्रोत व तारीख़ साथ) — हर मंच/बिल (पाठ-65) उसी से पढ़े। दर बदले (सरकारी सूचना) तो शीट में बदलो, फिर सब जगह — एक चीज़ = एक जगह का कर-रूप। सेवा-सहायक HSN \"सुझा\" सकता है, \"तय\" CA/दुकानदार करे (पाठ-63 की सीमा)।\n\n## 3. आज का काम «काम-कार्ड»\nअपने उत्पाद के लिए AI से HSN-सुझाव माँगिए (कदम-1)। फिर GST-पोर्टल की आधिकारिक HSN-खोज सुविधा (कड़ी स्रोत में) पर अपनी श्रेणी खोजकर मिलाइए (कदम-3) — कॉपी में लिखिए AI का सुझाव और पोर्टल का जवाब, दोनों मेल खाते हैं या नहीं। अपने उत्पाद-फ़ॉर्म (पाठ-15) में \"HSN कोड\" और \"GST-दर\" का नया खाना जोड़कर भरिए। अगर मेल न खाए या शक हो, \"पक्का किससे करूँगा\" (CA/GST-केंद्र-नाम) एक पंक्ति में लिखिए। जाँच-सूची: ☐ AI-सुझाव लिया ☐ GST-पोर्टल से मिलान किया ☐ फ़ॉर्म में HSN-GST खाना जोड़ा ☐ शक होने पर पक्का-योजना लिखी ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = AI-सुझाव और पोर्टल-मिलान दोनों दर्ज (मेल खाने/न खाने की ईमानदार स्थिति सहित); फ़ॉर्म अपडेट हुआ; कोई भी \"मैंने अंदाज़ से लिख दिया\" वाला जवाब नहीं। समय: 30 मिनट।\n\n## 5. सबूत\nसबूत-खाते में AI-सुझाव, पोर्टल-स्क्रीनशॉट, अपडेटेड फ़ॉर्म। यह HSN-GST जानकारी खंड-3 (पाठ-63 GST विस्तार से) और खंड-9 (पाठ-77 HSN-GST शब्दावली विस्तार) में फिर गहराई से आएगी — आज सिर्फ़ अपने एक उत्पाद पर पहला अभ्यास।\n\n## 6. AI-सहायक\nयह पूरा पाठ AI-सहायक पर आधारित है (कदम-1)। ध्यान रखें — AI कई बार पुरानी GST-दर बता सकता है (दरें कभी-कभी बदलती हैं) — इसलिए कदम-3 (पोर्टल-मिलान) कभी न छोड़ें, यह HSN-दर के लिए ख़ासकर ज़रूरी नियम है।\n\n## 7. आम ग़लती\nपहली — AI का सुझाव सीधे लिस्टिंग/बिल में डाल देना बिना पोर्टल-मिलान के — ग़लत टैक्स भरा जा सकता है। दूसरी — \"पड़ोसी दुकानदार जो लिखता है वही लिख देता हूँ\" — हर उत्पाद की बारीक श्रेणी अलग हो सकती है। तीसरी — HSN को एक बार ढूँढकर हमेशा के लिए मान लेना — नियम/दर बदल सकते हैं, साल में एक बार दोबारा जाँचना अच्छी आदत। चौथी — GST-दर का मतलब न समझना कि यह अंतिम ग्राहक-दाम में जुड़ेगा या पहले से शामिल है — इसे अपने calculator (पाठ-67) में साफ़ रखें।\n\n## 8. सुरक्षा-पत्रक\nग़लत HSN/GST-दर से बचने के लिए जल्दबाज़ी न करें — यह पैसे-कानून का मामला है, अंतिम फ़ैसला हमेशा GST-पोर्टल या अधिकृत व्यक्ति (CA, GST-सुविधा-केंद्र) से। \"मैं आपका GST/HSN ठीक करवा दूँगा, पैसे दो\" कहने वाले अनजान लोगों से सावधान — यह जानकारी ख़ुद पोर्टल से मुफ़्त मिलती है, अधिकृत सेवा-शुल्क अलग और रसीद-सहित। ACS कर-सलाह नहीं देता — यह पाठ सिर्फ़ सही जगह तक पहुँचने का रास्ता दिखाता है।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। HSN/GST-दर सरकारी नियम है, बदल सकता है — ACS कर-सलाह नहीं देता। 📎 मूल-कोर्स-कड़ी: GST आधिकारिक पोर्टल (HSN खोज सुविधा) — https://www.gst.gov.in — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=hsn-gst-classification · platform=none · level=O · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं HSN कोड क्या है, सरल शब्दों में बता सकता हूँ।\n- [ ] मैंने AI-सुझाव और GST-पोर्टल दोनों से अपना HSN जाँचा है।\n- [ ] मेरे उत्पाद-फ़ॉर्म में HSN और GST-दर का खाना जुड़ा है।\n- [ ] मैं जानता हूँ कि पक्का फ़ैसला AI से नहीं, पोर्टल/CA से होता है।\n- [ ] मैं जानता हूँ कि HSN/GST-दर समय-समय पर दोबारा जाँचनी चाहिए।",
 "25": "═\n# पाठ-25: Product Data Feed — मशीन-पठनीय कैटलॉग (agentic-commerce की नींव)\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर O/S · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nपाठ-24 तक हमने इंसान के पढ़ने के लिए लिस्टिंग बनाई; आज सीखेंगे कि वही जानकारी \"मशीन के पढ़ने\" के लिए कैसे तैयार होती है — क्योंकि आज ख़रीदारी सिर्फ़ इंसान नहीं, AI-सहायक और आने वाले AI-agent भी करेंगे (पाठ-2, 315-316)। पाठ के बाद आप तीन बातें कर पाएँगे — \"Product Data Feed\" क्या है और यह साधारण लिस्टिंग से कैसे अलग है, बता पाएँगे; अपनी उत्पाद-जानकारी को मशीन-पठनीय रूप (structured fields) में सजा पाएँगे; और समझ पाएँगे कि आज की यह मेहनत आने वाले \"AI ख़ुद ख़रीदारी करे\" युग की नींव क्यों है।\n\n## 2. मुख्य बात\nइंसान लिस्टिंग \"पढ़ता\" है — वाक्य, कहानी, भाव समझकर; मशीन लिस्टिंग \"छाँटती\" है — हर जानकारी अपने तय खाने में चाहिए। एक-वाक्य बात — **Product Data Feed का मतलब है हर जानकारी (नाम, दाम, उपलब्धता, शिपिंग, वापसी-नीति, ब्रांड, गुण) को एक तय खाने (field) में, तय रूप में रखना — जैसे फ़ॉर्म का हर खाना अलग सवाल का जवाब — ताकि मशीन बिना ग़लती समझे, चुने, दिखाए।**\n\n## साधारण लिस्टिंग बनाम Data Feed — फ़र्क़ उदाहरण से\n**साधारण लिस्टिंग (इंसान के लिए):** \"यह ख़ूबसूरत नीली कुर्ती हाथ से कढ़ी हुई है, M साइज़ में उपलब्ध, कीमत मात्र ₹450, 5-7 दिन में डिलीवरी।\" यह पढ़ने में अच्छा है, पर मशीन के लिए उलझा हुआ — कहाँ दाम है, कहाँ रंग, कहाँ शिपिंग-समय, वाक्य में घुला हुआ। **Data Feed (मशीन के लिए):** हर जानकारी अलग खाने में — title: \"हाथ की कढ़ाई कॉटन कुर्ती नीली\", color: \"नीला\", size: \"M\", price: \"450\", currency: \"INR\", availability: \"in_stock\", shipping_days: \"5-7\", brand: \"(अगर है)\", GTIN/SKU: \"KURTI-NEELA-M\"। यही वह रूप है जो Merchant Center, बड़े मार्केटप्लेस के bulk-सिस्टम, और AI-agent तीनों समझते हैं — पाठ-26 की मास्टर-शीट असल में इसी data-feed सोच पर बनी थी, आज हम उसे औपचारिक रूप देंगे।\n\n## चित्र — वाक्य से खाने तक\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">Product Data Feed — वाक्य से खाने तक</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">बाएँ इंसान पढ़े · दाएँ मशीन छाँटे · सोना = agentic-commerce की नींव</text>\n<rect x=\"40\" y=\"120\" width=\"320\" height=\"180\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"200\" y=\"152\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\">साधारण लिस्टिंग</text>\n<text x=\"60\" y=\"185\" font-size=\"16\">\"यह ख़ूबसूरत नीली कुर्ती</text>\n<text x=\"60\" y=\"208\" font-size=\"16\">हाथ से कढ़ी, M साइज़,</text>\n<text x=\"60\" y=\"231\" font-size=\"16\">कीमत ₹450, 5-7 दिन में\"</text>\n<text x=\"60\" y=\"265\" font-size=\"16\" fill=\"#1565C0\">इंसान पढ़े, समझे, महसूस करे</text>\n<rect x=\"440\" y=\"120\" width=\"320\" height=\"440\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"600\" y=\"152\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\">Product Data Feed</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"460\" y=\"170\" width=\"280\" height=\"30\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/><text x=\"470\" y=\"190\">title: हाथ-कढ़ाई कुर्ती नीली</text>\n<rect x=\"460\" y=\"204\" width=\"280\" height=\"30\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/><text x=\"470\" y=\"224\">color: नीला</text>\n<rect x=\"460\" y=\"238\" width=\"280\" height=\"30\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/><text x=\"470\" y=\"258\">size: M</text>\n<rect x=\"460\" y=\"272\" width=\"280\" height=\"30\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/><text x=\"470\" y=\"292\">price: 450, INR</text>\n<rect x=\"460\" y=\"306\" width=\"280\" height=\"30\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/><text x=\"470\" y=\"326\">availability: in_stock</text>\n<rect x=\"460\" y=\"340\" width=\"280\" height=\"30\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/><text x=\"470\" y=\"360\">shipping_days: 5-7</text>\n<rect x=\"460\" y=\"374\" width=\"280\" height=\"30\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/><text x=\"470\" y=\"394\">SKU: KURTI-NEELA-M</text>\n<rect x=\"460\" y=\"408\" width=\"280\" height=\"30\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/><text x=\"470\" y=\"428\">return_policy: 7-दिन</text>\n<rect x=\"460\" y=\"442\" width=\"280\" height=\"30\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\"/><text x=\"470\" y=\"462\">image_url: /फ़ोटो-1/front.jpg</text>\n</g>\n<text x=\"600\" y=\"530\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">मशीन/AI-agent छाँटे, तुलना करे, सुझाए</text>\n<line x1=\"360\" y1=\"210\" x2=\"430\" y2=\"210\" stroke=\"#0B1F3A\" stroke-width=\"4\"/><polygon points=\"438,210 422,200 422,220\" fill=\"#0B1F3A\"/>\n<rect x=\"60\" y=\"590\" width=\"680\" height=\"90\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"622\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">यह अभी क्यों — भविष्य की तैयारी</text>\n<text x=\"400\" y=\"655\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">AI-agent (पाठ-315-316) ख़रीदारी करेंगे — साफ़ खाने वाला डेटा ही पढ़ पाएँगे</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## आम खाने (fields) — क्या-क्या शामिल हों\nहर Product Data Feed में आम तौर पर ये खाने होते हैं — **title** (शीर्षक, मशीन-पढ़ने-योग्य छोटा रूप), **description** (विवरण), **price + currency** (दाम, मुद्रा — भारत में INR), **availability** (उपलब्ध है/नहीं, कितनी मात्रा), **shipping** (कितने दिन, कहाँ तक), **returns** (वापसी-नीति कितने दिन), **GTIN/SKU** (विश्व-मानक बार-कोड अगर है, या अपना SKU — पाठ-27), **brand** (ब्रांड, या \"no-brand\" स्थानीय उत्पाद के लिए), **attributes** (रंग, नाप, सामग्री — हर एक अलग खाने में), **images/video** (फ़ोटो की सीधी कड़ी, वीडियो अगर है)। यह लगभग वही जानकारी है जो पाठ-15 के फ़ॉर्म और पाठ-26 (आगे) की मास्टर-शीट में है — आज सिर्फ़ इसे \"मशीन-मानक\" खानों के नाम से पहचानना और सजाना सीखेंगे।\n\n## यह अभी क्यों सीखें — agentic-commerce की तैयारी\nपाठ-2 में सीखा था कि ग्राहक अब AI-सहायक से बातचीत-खोज करता है; आगे (पाठ-315-316) सीखेंगे कि निकट भविष्य में AI-agent पूरी ख़रीदारी ख़ुद कर सकता है — ग्राहक कहेगा \"मेरे लिए एक अच्छी कॉटन कुर्ती ₹500 के अंदर ढूँढो और मँगवा दो\", और AI कई दुकानों का data-feed पढ़कर फ़ैसला करेगा। जिस दुकान का data साफ़-सजा-मशीन-पढ़ने-योग्य है, उसे AI आसानी से \"समझ\" पाएगा और सुझाएगा; जिसका डेटा सिर्फ़ सुंदर वाक्यों में उलझा है, उसे AI छोड़ सकता है। इसलिए आज सीखा यह हुनर \"भविष्य-निवेश\" है — अभी हर मंच पूरी तरह इसकी माँग नहीं करता, पर Google Merchant Center (खंड-8) पहले से इसी रूप में डेटा माँगता है, और यह चलन बढ़ेगा (इसीलिए यह पाठ MEDIUM-volatility है — माँग बढ़ती जाएगी)।\n\n## एक असली उदाहरण — एक ख़ाली खाना, एक अदृश्य उत्पाद\nएक विक्रेता के 30 उत्पादों में 8 में \"उपलब्धता\" खाना ख़ाली था — मंच का सिस्टम (और आगे AI-ख़रीदार, पाठ-315) उन्हें \"पता नहीं\" मानकर खोज में नीचे रखता; बाक़ी 22 आगे दिखते। खाना भरते ही आठों दिखने लगे। Feed में ख़ाली खाना = ग्राहक के लिए अदृश्य उत्पाद। नियम — हर खाना भरो, न पता हो तो पता करो, \"बाद में\" नहीं।\n\n## 3. आज का काम «काम-कार्ड»\nअपने उस एक उत्पाद (जो पाठ 13-24 में विस्तार से बनाया) की सारी जानकारी लीजिए — फ़ॉर्म (15), फ़ोटो-कड़ी (16-19), लिस्टिंग (20-22), कीवर्ड (23), HSN-GST (24)। इन्हें ऊपर बताए 10 \"खानों\" (title, description, price, currency, availability, shipping, returns, SKU, attributes जैसे color-size, image_url) में अलग-अलग, साफ़ रूप में कॉपी/Excel में सजाइए — हर खाना एक अलग पंक्ति या स्तंभ में, वाक्य नहीं, सीधा शब्द/संख्या। कॉपी में लिखिए — इनमें से किन खानों की जानकारी आपके पास पहले से पूरी थी, कौन-सी आज पहली बार सोचनी पड़ी (जैसे \"returns\" — वापसी-नीति शायद अभी तय नहीं थी)। जाँच-सूची: ☐ 10 खानों में जानकारी सजाई ☐ हर खाना साफ़-छोटा, वाक्य नहीं ☐ पुराना-नया की सूची ☐ SKU शामिल ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = सभी 10 खाने भरे (जो जानकारी नहीं मिली, वहाँ \"अभी तय नहीं\" ईमानदारी से लिखा, गढ़ा नहीं); हर खाना छोटा-सीधा (वाक्य नहीं); \"पुराना-नया\" सूची में कम-से-कम एक नई सोची गई जानकारी (अक्सर \"returns\" या \"shipping_days\")। समय: 30 मिनट।\n\n## 5. सबूत\nसबूत-खाते में भरे 10-खाने और \"पुराना-नया\" सूची। यह data-feed अगले पाठ (26 मास्टर-शीट) में सीधे उसी शीट के स्तंभों का आधार बनेगा — और खंड-8 (Google Merchant Center, पाठ-108) में इसी सजावट को असली मंच-फ़ॉर्म में डालना सीखेंगे।\n\n## 6. AI-सहायक\nAI से पूछिए — \"यह मेरी लिस्टिंग है (चिपकाइए) — इसे Product Data Feed के 10 आम खानों (title, description, price, currency, availability, shipping, returns, SKU, attributes, image) में अलग-अलग बाँट दो, कोई नई जानकारी मत जोड़ना\" — यह काम AI तेज़ी से कर सकता है क्योंकि यह सिर्फ़ मौजूदा जानकारी को अलग-अलग खानों में बाँटना है, नया गढ़ना नहीं (कम जोखिम-भरा AI-काम)। फिर भी पाँच-सवाल reality-check (पाठ-28) यहाँ भी लगाइए।\n\n## 7. आम ग़लती\nपहली — खानों में भी पूरे वाक्य लिख देना (\"price\" खाने में \"सिर्फ़ ₹450 में!\" लिखना) — मशीन को सिर्फ़ संख्या \"450\" चाहिए, बाक़ी शोर है। दूसरी — \"returns/shipping\" जैसे खाने ख़ाली छोड़ देना क्योंकि \"अभी तय नहीं\" — यह ठीक है लिखना, पर बिल्कुल ख़ाली छोड़ना मशीन को उलझाता है। तीसरी — SKU को हर मंच पर अलग रखना — पाठ-27 में सीखेंगे, एक SKU कई जगह इस्तेमाल करना बेहतर। चौथी — इस पाठ को \"अभी की ज़रूरत नहीं, आगे देखेंगे\" कहकर छोड़ देना — छोटी शुरुआत आज, बड़ा फ़ायदा कल (agentic-commerce बढ़ते ही)।\n\n## 8. सुरक्षा-पत्रक\nData Feed में ग़लत/गढ़ी जानकारी (जैसे \"availability: in_stock\" जबकि माल नहीं है) मशीन-स्तर पर तेज़ी से फैलती है — AI-agent और मंच दोनों इसी डेटा पर भरोसा करते हैं, इंसान की तरह \"शायद ग़लत होगा\" सोचकर दोबारा नहीं जाँचते। इसलिए यहाँ सच्चाई और भी ज़्यादा ज़रूरी है। SKU/डेटा-फ़ाइल में दुकानदार की निजी जानकारी न रखें — सिर्फ़ उत्पाद-जानकारी।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। Product Data Feed की माँग और मानक मंचों/AI-कंपनियों की ओर से बढ़ रहे हैं — तेज़ी से बदल सकते हैं। 📎 मूल-कोर्स-कड़ी: Google Merchant Center Product Data Specification — https://support.google.com/merchants — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=product-data-feed · platform=multi · level=O,S · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं Product Data Feed और साधारण लिस्टिंग का फ़र्क़ बता सकता हूँ।\n- [ ] मैंने अपने उत्पाद की जानकारी 10 खानों में सजाई है।\n- [ ] मेरे हर खाने में सीधा शब्द/संख्या है, वाक्य नहीं।\n- [ ] मैं जानता हूँ कि यह agentic-commerce की नींव क्यों है।\n- [ ] मैं जानता हूँ कि ग़लत data-feed मशीन-स्तर पर क्यों ज़्यादा जोखिम-भरा है।",
 "26": "═\n# पाठ-26: मास्टर उत्पाद-शीट (Excel) — एक स्रोत, हर मंच का रूप\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर O · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nअब तक जो कुछ अलग-अलग काग़ज़ों में बना — फ़ॉर्म (15), फ़ोटो (16-19), लिस्टिंग-तीन-रूप (20-21), कीवर्ड (23), HSN-GST (24) — आज सबको एक Excel-शीट में इकट्ठा करेंगे। पाठ के बाद आप तीन बातें कर पाएँगे — एक मास्टर उत्पाद-शीट बना पाएँगे जिसमें हर उत्पाद की पूरी जानकारी एक पंक्ति में हो; उसी शीट से किसी भी मंच के लिए जानकारी निकाल पाएँगे; और समझ पाएँगे कि यह शीट क्यों कोर्स के आगे हर हिस्से की \"एक जगह\" (single source of truth) बनेगी।\n\n## 2. मुख्य बात\nअलग-अलग काग़ज़ों में जानकारी बिखरी हो तो भूल-चूक होती है; एक शीट में सब कुछ हो तो हर मंच पर काम तेज़ और सटीक होता है। एक-वाक्य बात — **मास्टर उत्पाद-शीट = एक Excel-फ़ाइल, हर पंक्ति एक उत्पाद, हर स्तंभ एक जानकारी (नाम, फ़ोटो-फ़ोल्डर-कड़ी, दाम, HSN, कीवर्ड, विवरण, स्थिति) — बदलाव यहाँ एक जगह करो, हर मंच पर वही ताज़ा जानकारी दिखे।**\n\n## शीट के स्तंभ — क्या-क्या रखें\nउत्पाद-ID (अपना क्रम-नंबर) · उत्पाद-नाम · दुकानदार/स्रोत (संकेत) · सामग्री-बनावट · नाप-रंग-वेरिएशन · दाम (न्यूनतम-अधिकतम) · कितने दिन टिकता · HSN-कोड · GST-दर · कीवर्ड (5-8, अल्पविराम से अलग) · शीर्षक (मास्टर) · बुलेट-पॉइंट (मास्टर) · विवरण (मास्टर) · फ़ोटो-फ़ोल्डर का नाम/जगह · श्रेणी (हरा/पीला/लाल — पाठ-13) · स्थिति (तैयार/अधूरा/रुका हुआ) · आख़िरी अपडेट-तारीख़। यह ठीक वही जानकारी है जो पाठ 13-24 में अलग-अलग बनाई — आज सिर्फ़ जोड़ने का काम।\n\n## चित्र — मास्टर-शीट का ढाँचा\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">मास्टर उत्पाद-शीट — एक स्रोत, हर मंच का रूप</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">हर पंक्ति = एक उत्पाद · हर स्तंभ = पाठ 13-24 से एक जानकारी</text>\n<rect x=\"40\" y=\"120\" width=\"720\" height=\"240\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"55\" y=\"135\" width=\"70\" height=\"30\" fill=\"#F9A825\" stroke=\"#0B1F3A\"/><text x=\"90\" y=\"155\" text-anchor=\"middle\">ID</text>\n<rect x=\"125\" y=\"135\" width=\"140\" height=\"30\" fill=\"#F9A825\" stroke=\"#0B1F3A\"/><text x=\"195\" y=\"155\" text-anchor=\"middle\">नाम (पाठ-15)</text>\n<rect x=\"265\" y=\"135\" width=\"100\" height=\"30\" fill=\"#F9A825\" stroke=\"#0B1F3A\"/><text x=\"315\" y=\"155\" text-anchor=\"middle\">दाम-नाप (15)</text>\n<rect x=\"365\" y=\"135\" width=\"100\" height=\"30\" fill=\"#F9A825\" stroke=\"#0B1F3A\"/><text x=\"415\" y=\"155\" text-anchor=\"middle\">HSN-GST (24)</text>\n<rect x=\"465\" y=\"135\" width=\"120\" height=\"30\" fill=\"#F9A825\" stroke=\"#0B1F3A\"/><text x=\"525\" y=\"155\" text-anchor=\"middle\">कीवर्ड (23)</text>\n<rect x=\"585\" y=\"135\" width=\"100\" height=\"30\" fill=\"#F9A825\" stroke=\"#0B1F3A\"/><text x=\"635\" y=\"155\" text-anchor=\"middle\">फ़ोटो (16-19)</text>\n<rect x=\"685\" y=\"135\" width=\"60\" height=\"30\" fill=\"#F9A825\" stroke=\"#0B1F3A\"/><text x=\"715\" y=\"155\" text-anchor=\"middle\">रंग (13)</text>\n<rect x=\"55\" y=\"170\" width=\"70\" height=\"35\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/><text x=\"90\" y=\"192\" text-anchor=\"middle\">1</text>\n<rect x=\"125\" y=\"170\" width=\"140\" height=\"35\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/><text x=\"195\" y=\"192\" text-anchor=\"middle\">कढ़ाई-कुर्ती</text>\n<rect x=\"265\" y=\"170\" width=\"100\" height=\"35\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/><text x=\"315\" y=\"192\" text-anchor=\"middle\">₹450, M</text>\n<rect x=\"365\" y=\"170\" width=\"100\" height=\"35\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/><text x=\"415\" y=\"192\" text-anchor=\"middle\">6204, 5%</text>\n<rect x=\"465\" y=\"170\" width=\"120\" height=\"35\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/><text x=\"525\" y=\"192\" text-anchor=\"middle\">kurti,dress…</text>\n<rect x=\"585\" y=\"170\" width=\"100\" height=\"35\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/><text x=\"635\" y=\"192\" text-anchor=\"middle\">/फ़ोटो-1/</text>\n<rect x=\"685\" y=\"170\" width=\"60\" height=\"35\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\"/><text x=\"715\" y=\"192\" text-anchor=\"middle\">🟢</text>\n<rect x=\"55\" y=\"205\" width=\"690\" height=\"35\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-dasharray=\"3 3\"/><text x=\"400\" y=\"227\" text-anchor=\"middle\" fill=\"#1565C0\">पंक्ति-2: अगला उत्पाद (सर्वे-सूची पाठ-11 से)</text>\n<rect x=\"55\" y=\"240\" width=\"690\" height=\"35\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-dasharray=\"3 3\"/><text x=\"400\" y=\"262\" text-anchor=\"middle\" fill=\"#1565C0\">पंक्ति-3: …</text>\n<text x=\"400\" y=\"305\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">दाएँ और स्तंभ: शीर्षक · बुलेट · विवरण · स्थिति · अपडेट-तारीख़</text>\n<text x=\"400\" y=\"335\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">एक पंक्ति = एक उत्पाद की पूरी कहानी</text>\n</g>\n<rect x=\"60\" y=\"390\" width=\"680\" height=\"220\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"424\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">एक स्रोत का फ़ायदा</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"460\">दाम बदला? → शीट में एक जगह बदलो, हर मंच पर अपडेट याद रहे</text>\n<text x=\"90\" y=\"494\">नया उत्पाद? → एक नई पंक्ति, पुराना ढाँचा दोहराओ नहीं</text>\n<text x=\"90\" y=\"528\">कितने तैयार हैं? → \"स्थिति\" स्तंभ फ़िल्टर करके गिनो</text>\n<text x=\"90\" y=\"562\">bulk-लिस्टिंग (पाठ-27) → यही शीट सीधे इस्तेमाल होगी</text>\n</g>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## एक स्रोत का फ़ायदा — बदलाव, नए उत्पाद, गिनती\nजब दाम बदलता है (मौसम/त्योहार पर), आप शीट में एक जगह बदलते हैं और हर मंच पर जाकर अलग-अलग याद करने की ज़रूरत घटती है (मंच-अपडेट अभी भी अलग से करनी होगी, खंड 9-11 में — पर स्रोत एक जगह से पता चलता है)। नया उत्पाद जोड़ना = एक नई पंक्ति, पूरा ढाँचा (स्तंभ) पहले से तैयार। \"स्थिति\" स्तंभ (तैयार/अधूरा/रुका हुआ) फ़िल्टर करके आप एक नज़र में देख सकते हैं कितने उत्पाद कहाँ अटके हैं — यह सेवा-सहायक के लिए (कई दुकानों का काम) ख़ासकर ज़रूरी हो जाता है। यही शीट पाठ-27 (bulk-लिस्टिंग) और खंड-23 (Capstone की 20-उत्पाद मास्टर-शीट) में सीधे बड़े रूप में लौटेगी।\n\n## बनाना — Excel में, मोबाइल पर भी\nExcel/Google Sheets में पहली पंक्ति में स्तंभ-नाम टाइप कीजिए (ऊपर की सूची से)। फिर पाठ-11 के अपने सर्वे-सूची (ढेर-1, हरा-पीला वाले) से एक-एक उत्पाद की पंक्ति भरिए — पहला उत्पाद (जो पाठ 13-24 में विस्तार से बनाया) पूरा भरा होगा; बाक़ी उत्पाद अभी सिर्फ़ नाम-दाम-रंग जितना पता है उतना — \"स्थिति\" में \"अधूरा\" लिखिए, आगे के खंडों में पूरा करेंगे। मोबाइल पर Google Sheets ऐप से भी यह पूरा काम हो सकता है — कंप्यूटर ज़रूरी नहीं।\n\n## एक असली उदाहरण — तीन जगह तीन दाम, एक शीट से एक\nएक दुकानदार का एक ही उत्पाद WhatsApp पर ₹450, Meesho पर ₹430 (पुराना), Amazon पर ₹470 (बढ़ा था) — ग्राहक ने तीनों screenshot भेजकर पूछा \"कौन-सा सही?\" भरोसा वहीं हिला। उसने मास्टर-शीट बनाई — एक पंक्ति एक उत्पाद, दाम-स्तंभ एक; नियम: दाम बदलना = पहले शीट, फिर हर मंच उसी दिन; और शीट में \"अंतिम-अपडेट तारीख़\" स्तंभ। अगली बार दाम बदला तो तीनों जगह एक शाम में, एक-सा। शीट कोई अतिरिक्त काम नहीं थी — वह पहले से बिखरे काम को एक जगह लाना था।\n\n## शीट के स्तंभ — शुरुआत में बारह, बाद में बढ़ें\nSKU (27) · नाम · श्रेणी-रंग (13) · दाम · लागत (67 में विस्तार) · स्टॉक · HSN (24) · फ़ोटो-फ़ोल्डर-कड़ी (19) · कीवर्ड 5-8 (23) · छोटा-विवरण (21) · Collection (34) · स्थिति (शुरू/तैयारी, 29) · अंतिम-अपडेट। बाद में CM-स्तंभ (67), पहला-मंच (46), WhatsApp/Meesho ✅ (33) जुड़ेंगे — शीट कोर्स के साथ बढ़ती है, बदलती नहीं। हर स्तंभ का \"एकमात्र घर\" यही शीट — किसी मंच का खाना नहीं।\n\n## शीट की सुरक्षा — दो प्रतियाँ, एक सच\nशीट फ़ोन/कंप्यूटर में और एक cloud-प्रति (बैकअप) — पर संपादन एक ही जगह (एक \"जीवित\" फ़ाइल), वरना दो प्रतियाँ अलग हो जाती हैं और \"एक जगह\" का पूरा फ़ायदा जाता है। सेवा-सहायक हर दुकान की शीट दुकानदार के खाते/cloud में रखे, अपने में प्रति नहीं (पाठ-299) — दुकान बदले तो शीट वहीं रहे।\n\n## 3. आज का काम «काम-कार्ड»\nExcel/Google Sheets में मास्टर उत्पाद-शीट बनाइए — ऊपर के 17 स्तंभ। अपना पहला उत्पाद (पाठ 13-24 में बनाया) पूरी तरह भरिए — हर स्तंभ में सही जानकारी (अंदाज़ा नहीं, फ़ॉर्म-आधारित)। फिर पाठ-11 की सूची से 4 और उत्पाद पंक्तियों में जोड़िए (जितनी जानकारी अभी हो उतनी, बाक़ी \"अधूरा\")। शीट को साफ़ नाम से सहेजिए (\"master-utpad-sheet\")। जाँच-सूची: ☐ 17 स्तंभ बने ☐ पहला उत्पाद पूरा भरा ☐ 4 और पंक्तियाँ जोड़ीं ☐ स्थिति-स्तंभ भरा ☐ फ़ोटो/स्क्रीनशॉट सबूत-खाते में।\n\n## 4. नाप\nसफल = 17 स्तंभ मौजूद, नाम साफ़; पहली पंक्ति (पहला उत्पाद) में कोई भी स्तंभ ख़ाली नहीं और सब जानकारी पिछले पाठों से मेल खाती (गढ़ी नहीं); कुल 5 पंक्तियाँ (5 उत्पाद)। समय: 35 मिनट।\n\n## 5. सबूत\nसबूत-खाते में शीट का स्क्रीनशॉट। यह शीट अब पूरे कोर्स में आपका सबसे ज़रूरी दस्तावेज़ है — पाठ 26-30, खंड 3-4 (कैटलॉग), खंड 9-11 (लिस्टिंग), और खंड-23 (Capstone) — सब इसी से डेटा लेंगे। इसे हर हफ़्ते अपडेट करने की आदत डालिए।\n\n## 6. AI-सहायक\nAI से पूछिए — \"मुझे ई-कॉमर्स के लिए एक मास्टर उत्पाद-शीट बनानी है, Excel में; मेरे 17 स्तंभ (सूची दीजिए) ठीक हैं या कुछ और ज़रूरी है?\" — सुझाव मिलने पर अपनी शीट में जोड़ने लायक़ हो तो जोड़िए। शीट की असली जानकारी (दाम, दुकानदार-संकेत) AI को भेजने की ज़रूरत नहीं — यह सिर्फ़ ढाँचे की सलाह के लिए बातचीत है।\n\n## 7. आम ग़लती\nपहली — शीट बनाकर उसमें जानकारी बाद में भरने की सोचकर टाल देना — तुरंत, जो पता है वह भरिए। दूसरी — हर उत्पाद के लिए अलग-अलग शीट बना लेना — एक शीट, कई पंक्तियाँ, यही मास्टर-शीट का मतलब है। तीसरी — दाम/जानकारी बदलने पर शीट अपडेट करना भूल जाना — शीट \"आख़िरी अपडेट-तारीख़\" स्तंभ इसी के लिए है, हर बदलाव पर वह तारीख़ भी बदलिए। चौथी — शीट को सिर्फ़ कंप्यूटर पर रखना, फ़ोन पर न होना — दुकान पर काम करते समय फ़ोन पर ज़रूरत पड़ती है, Cloud में सहेजिए (Google Sheets अपने-आप होता है)।\n\n## 8. सुरक्षा-पत्रक\nशीट में दुकानदार का निजी फ़ोन-नाम \"दुकानदार/स्रोत\" स्तंभ में सिर्फ़ संकेत रूप में (जैसे \"दुकान-1\") रखें, सबूत-खाते में शेयर करते समय यह स्तंभ छुपाकर/काटकर भेजें। शीट Cloud में हो तो पासवर्ड/2-Step सुरक्षा (खंड-20) लगाइए — इसमें कई दुकानदारों/उत्पादों की जानकारी होगी, यह अमानत है। सेवा-सहायक: हर दुकानदार की जानकारी एक ही शीट में मिलाकर न रखें अगर वे अलग-अलग हैं और गोपनीयता चाहते हैं — अलग शीट या अलग टैब बेहतर।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। मास्टर-शीट ACS का अपना साँचा, DCA-2036 कोर्स के Excel-खंड (खंड-7) के हुनर पर आधारित। 📎 मूल-कोर्स-कड़ी: bulk-listing के लिए मंचों की खुद की टेम्पलेट-शीट (उदाहरण के लिए) — Amazon \"Inventory File Template\" — Seller University (Catalog/Bulk upload section) — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=master-product-sheet · platform=none · level=O · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मेरी मास्टर उत्पाद-शीट 17 स्तंभों के साथ बनी है।\n- [ ] मेरा पहला उत्पाद पूरी तरह, सच्ची जानकारी से भरा है।\n- [ ] शीट में 5 उत्पाद-पंक्तियाँ हैं।\n- [ ] मैं जानता हूँ कि \"स्थिति\" और \"आख़िरी अपडेट\" स्तंभ क्यों ज़रूरी हैं।\n- [ ] मैं जानता हूँ कि यह शीट आगे कहाँ-कहाँ इस्तेमाल होगी।",
 "27": "═\n# पाठ-27: bulk-लिस्टिंग की तैयारी — 50 उत्पाद एक शीट से\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर O/S · रास्ता A,B · volatility MEDIUM)*\n\n## 1. उद्देश्य\nपाठ-26 की मास्टर-शीट अभी 5 उत्पादों की है; असली दुकान या सेवा-सहायक के काम में यह 20, 50, 100 उत्पादों तक बढ़ती है। एक-एक करके हर मंच पर हाथ से डालना असंभव हो जाता है — इसलिए \"bulk\" (एक साथ कई) लिस्टिंग सीखेंगे। पाठ के बाद आप तीन बातें कर पाएँगे — bulk-लिस्टिंग क्या है और कब चाहिए, बता पाएँगे; अपनी मास्टर-शीट को bulk-अपलोड के लिए तैयार कर पाएँगे; और समझ पाएँगे कि 5 उत्पादों से 50 तक बढ़ने में क्या बदलता है, क्या नहीं।\n\n## 2. मुख्य बात\nएक-एक उत्पाद हाथ से डालना ठीक है जब 5-10 हों; 50 हों तो यह हफ़्तों का काम बन जाता है। एक-वाक्य बात — **bulk-लिस्टिंग का मतलब है एक शीट (Excel/CSV) में सारे उत्पाद भरकर मंच को एक बार में देना — मंच अपने-आप हर पंक्ति से एक लिस्टिंग बना देता है; तैयारी वही है जो पाठ-25-26 में सीखी, बस मात्रा और सफ़ाई ज़्यादा चाहिए।**\n\n## bulk कब चाहिए, कब नहीं\n**हाथ से (एक-एक) ठीक है:** 5-15 उत्पाद, अभी सीख रहे हैं, हर उत्पाद बहुत अलग (हस्तशिल्प जहाँ हर टुकड़ा अनोखा)। **bulk चाहिए:** 20+ उत्पाद, एक-जैसी श्रेणी के कई वेरिएशन (10 रंगों में एक कुर्ती = 10 पंक्ति एक शीट में), सेवा-सहायक जो एक दुकानदार के पूरे स्टॉक को एक साथ चढ़ाए, या मौसमी बड़ा स्टॉक (त्योहार से पहले 50 नए डिज़ाइन)। मात्रा जो भी हो, तैयारी की बुनियाद पाठ-25 (Data Feed) और पाठ-26 (मास्टर-शीट) ही है — बस अब हर स्तंभ को मंच के \"bulk-template\" (मंच अपनी ख़ुद की खाली शीट देता है, जिसमें उसके स्तंभ-नाम पहले से लिखे होते हैं) से मिलाना सीखेंगे।\n\n## चित्र — 5 से 50 तक, क्या बदलता है\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">5 से 50 उत्पाद — क्या बदलता, क्या नहीं</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">सोना = वही रहता है · बाक़ी = नया ध्यान चाहिए</text>\n<rect x=\"60\" y=\"120\" width=\"330\" height=\"220\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"225\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\">जो वही रहता है</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"190\">मास्टर-शीट के स्तंभ (26)</text>\n<text x=\"90\" y=\"220\">हर पंक्ति = एक सच्चा उत्पाद</text>\n<text x=\"90\" y=\"250\">फ़ोटो-मानक (पाठ-19)</text>\n<text x=\"90\" y=\"280\">HSN-GST-जाँच (पाठ-24)</text>\n<text x=\"90\" y=\"310\">reality-check ज़रूरी (पाठ-28)</text>\n</g>\n<rect x=\"410\" y=\"120\" width=\"330\" height=\"220\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"575\" y=\"155\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\">नया ध्यान चाहिए</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"440\" y=\"190\">मंच के bulk-template से मिलाना</text>\n<text x=\"440\" y=\"220\">फ़ाइल-फ़ॉर्मैट (CSV/Excel) सही</text>\n<text x=\"440\" y=\"250\">SKU-कोड हर उत्पाद का अलग</text>\n<text x=\"440\" y=\"280\">छोटी खेप में पहले जाँचना (5-10)</text>\n<text x=\"440\" y=\"310\">फिर पूरी bulk-फ़ाइल भेजना</text>\n</g>\n<rect x=\"60\" y=\"370\" width=\"680\" height=\"200\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"404\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">bulk-तैयारी के चार कदम</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"440\">1. मास्टर-शीट पूरी भरो (हर उत्पाद के स्तंभ)</text>\n<text x=\"90\" y=\"474\">2. मंच का ख़ाली bulk-template डाउनलोड करो</text>\n<text x=\"90\" y=\"508\">3. मास्टर-शीट से template में कॉपी/मिलाओ (स्तंभ-नाम अलग हो सकते)</text>\n<text x=\"90\" y=\"542\">4. पहले 3-5 पंक्ति से जाँच-अपलोड, ठीक लगे तो बाक़ी</text>\n</g>\n<rect x=\"60\" y=\"590\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"622\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#0B1F3A\">50 ग़लत लिस्टिंग एक साथ = 50 सुधार का काम</text>\n<text x=\"400\" y=\"648\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1565C0\">इसलिए छोटी जाँच पहले, पूरी bulk बाद में</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## SKU कोड — हर उत्पाद की अपनी पहचान\nbulk-लिस्टिंग में एक नई चीज़ ज़रूरी हो जाती है — SKU (Stock Keeping Unit) कोड, यानी हर उत्पाद (और हर वेरिएशन — रंग/साइज़) का अपना छोटा कोड, जैसे \"KURTI-NEELA-M\" (कुर्ती-नीला-मीडियम)। यह कोड पाठ-25 के Data Feed का एक खाना और मास्टर-शीट (26) का एक स्तंभ है। SKU का फ़ायदा — जब ऑर्डर आए, आप तुरंत जान जाते हैं कौन-सा ठीक-ठीक उत्पाद, बिना नाम का पूरा विवरण दोबारा पढ़े। SKU-कोड सादा, याद रखने-योग्य पैटर्न में बनाइए — हर मंच पर अलग-अलग रैंडम कोड न रखें, एक ही SKU हर मंच पर इस्तेमाल करें तो हिसाब आसान रहता है (खंड-19 रिपोर्ट में यही स्तंभ मिलाने का काम आएगा)।\n\n## जाँच-अपलोड का नियम — पहले छोटी खेप\n50 उत्पादों को एक साथ bulk-अपलोड करने से पहले, सिर्फ़ 3-5 पंक्तियों की छोटी फ़ाइल बनाकर पहले अपलोड कीजिए। मंच का नतीजा देखिए — कोई ग़लती/अस्वीकृति आई? स्तंभ सही जगह गए? फ़ोटो-कड़ी काम कर रही? यह ठीक लगे, तभी बाक़ी को जोड़कर पूरी फ़ाइल भेजिए। यह वैसा ही है जैसे बड़ा खाना बनाने से पहले एक चम्मच चख लेना — छोटी ग़लती बड़ी बनने से पहले पकड़ी जाती है।\n\n## एक असली उदाहरण — 50 पंक्ति, एक ग़लत स्तंभ, 50 अस्वीकृत\nएक विक्रेता ने मास्टर-शीट से 50 उत्पाद मंच के bulk-साँचे में डाले — पर \"दाम\" स्तंभ में उसने \"₹450\" (रुपया-चिह्न सहित) लिखा, मंच सिर्फ़ संख्या माँगता था — 50 की 50 पंक्तियाँ अस्वीकृत, त्रुटि-सूची में \"invalid price\"। पाँच पंक्ति से पहले परखा होता तो पाँच मिनट में पकड़ में आता। नियम — bulk से पहले \"छोटा bulk\": 5 पंक्ति चढ़ाओ, त्रुटि-सूची पढ़ो, ठीक करो, तब 50। मंच का साँचा (template) हर बार डाउनलोड करके ताज़ा — पुराने साँचे में स्तंभ बदल जाते हैं।\n\n## SKU-कोड का नियम — अर्थ-भरा, स्थिर, अनोखा\nSKU आपकी अपनी पहचान-संख्या है — जैसे \"KUR-BLU-M-01\" (कुर्ती-नीली-M-पहली) — पढ़ते ही पता चले; एक बार बना तो कभी न बदले (मंच, रजिस्टर, कैटलॉग सब इसी से जुड़ते हैं); दो उत्पादों का एक SKU कभी नहीं। शीट में पहला स्तंभ यही, फ़ोटो-फ़ोल्डर का नाम यही (पाठ-19), Cart/ऑर्डर-रजिस्टर में यही (पाठ-40) — 50 उत्पादों के बाद SKU के बिना दुकान अंधी हो जाती है।\n\n## मास्टर-शीट से मंच-साँचे तक — नक़्शा-पंक्ति\nहर मंच का साँचा अपने स्तंभ-नाम रखता है (\"item_name\", \"Product Title\"…) — मास्टर-शीट के स्तंभ बदलिए मत; एक \"नक़्शा-पंक्ति\" रखिए — मास्टर का कौन-सा स्तंभ मंच के किस खाने में जाता है — और कॉपी उसी नक़्शे से। तीन मंच = तीन नक़्शा-पंक्तियाँ, एक शीट। नया मंच = एक नई पंक्ति, नई शीट नहीं (पाठ-7)।\n\n## 3. आज का काम «काम-कार्ड»\nअपनी मास्टर उत्पाद-शीट (पाठ-26) में एक नया स्तंभ \"SKU-कोड\" जोड़िए और सभी 5 उत्पादों के लिए सादा, समझने-योग्य कोड बनाइए। फिर किसी एक मंच का आधिकारिक \"bulk upload template/sample file\" खोजिए और डाउनलोड कीजिए (कड़ी स्रोत में) — उसके स्तंभ-नाम अपनी मास्टर-शीट के स्तंभों से मिलाकर एक तालिका बनाइए। कॉपी में लिखिए — कौन-से स्तंभ मंच में हैं जो हमारी शीट में नहीं (जोड़ने होंगे)। जाँच-सूची: ☐ SKU-कोड स्तंभ जोड़ा ☐ मंच का bulk-template डाउनलोड किया ☐ स्तंभ-मिलान तालिका बनी ☐ छूटे स्तंभ लिखे ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = सभी 5 SKU-कोड सादे-अलग-समझने-योग्य; मंच का असली bulk-template डाउनलोड हुआ (AI का बनाया नहीं); मिलान-तालिका में कम-से-कम 8 स्तंभ जोड़े गए; छूटे स्तंभों की सूची ईमानदार। समय: 35 मिनट।\n\n## 5. सबूत\nसबूत-खाते में शीट का SKU-स्तंभ, मंच-टेम्पलेट का स्क्रीनशॉट, मिलान-तालिका। यह तैयारी खंड-9-11 में सीधे इस्तेमाल होगी, जब आपकी मास्टर-शीट 20+ उत्पादों तक बढ़ेगी (खंड-23 Capstone)।\n\n## 6. AI-सहायक\nAI से पूछिए — \"मेरी मास्टर उत्पाद-शीट के यह स्तंभ (सूची) हैं, और (मंच) के bulk-template में यह स्तंभ (सूची) हैं — कौन-सा किससे मिलता है, तालिका बनाओ\" — दोनों सूचियाँ ख़ुद टाइप करके दीजिए (असली शीट/फ़ाइल AI को अपलोड न करें अगर उसमें दुकानदार-जानकारी हो)। यह मिलान-काम AI बहुत तेज़ी से करता है और यहाँ गढ़ने का ख़तरा कम है।\n\n## 7. आम ग़लती\nपहली — बिना छोटी जाँच के सीधे 50 उत्पाद अपलोड करना — एक ग़लती (जैसे ग़लत स्तंभ-क्रम) पूरी फ़ाइल ख़राब कर देती है। दूसरी — हर मंच पर अलग-अलग बेतरतीब SKU रखना — बाद के रिपोर्ट-मिलान (खंड-19) में भ्रम। तीसरी — मंच के template के स्तंभ-नाम बदल देना — मंच सिर्फ़ अपने तय स्तंभ-नाम पढ़ता है। चौथी — bulk-template पुराना/बासी इस्तेमाल करना — हर बार ताज़ा डाउनलोड करना बेहतर।\n\n## 8. सुरक्षा-पत्रक\nbulk-फ़ाइल में कई उत्पादों/दुकानदारों की जानकारी एक साथ होगी — यह फ़ाइल पासवर्ड-सुरक्षित रखें, बिना ज़रूरत किसी को न भेजें। कोई \"bulk-listing service\" जो आपके मंच का पासवर्ड/लॉगिन माँगे — यह धोखा है; bulk-अपलोड आपके अपने सेलर-खाते से, मंच के अपने डैशबोर्ड से होता है, बाहर से नहीं। 20 से कम उत्पादों के लिए bulk सीखने की जल्दी न करें — पहले हाथ से 5-10 करके भरोसा बनाइए, फिर bulk।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। bulk-template हर मंच का अपना, समय-समय पर बदलता है। 📎 मूल-कोर्स-कड़ी: Amazon \"Bulk upload/Inventory File Template\" — Seller University (Catalog section) — https://sell.amazon.in/learn/seller-university — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=bulk-listing-preparation · platform=multi · level=O,S · path=A,B · volatility=MEDIUM · status=ACTIVE · next_review=11/2026)\n\n## 10. योग्यता-जाँच\n- [ ] मैं bulk-लिस्टिंग कब चाहिए, कब नहीं — बता सकता हूँ।\n- [ ] मेरी शीट में SKU-कोड स्तंभ जुड़ा है, सादा-समझने-योग्य।\n- [ ] मैंने एक मंच का असली bulk-template डाउनलोड करके मिलाया है।\n- [ ] मैं जानता हूँ कि पहले छोटी खेप से जाँचना क्यों ज़रूरी है।\n- [ ] मैं जानता हूँ कि bulk-फ़ाइल की सुरक्षा कैसी होनी चाहिए।",
 "28": "═\n# पाठ-28: AI reality-check — गढ़ा दाम, झूठा गुण, ग़लत आकार पकड़ना\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर O · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nखंड-2 में हर पाठ में \"AI मत गढ़े\" कहा गया — आज इसी पर एक पूरा, व्यवस्थित पाठ है, जहाँ आप अपने ही पिछले काम पर यह जाँच लगाएँगे। पाठ के बाद आप तीन बातें कर पाएँगे — किसी भी AI-मसौदे में गढ़ा-दाम, झूठा-गुण, ग़लत-आकार तीन तरह की सबसे आम ग़लतियाँ पकड़ पाएँगे; अपनी पूरी मास्टर-शीट और लिस्टिंग पर एक व्यवस्थित \"reality-check\" कर पाएँगे; और यह आदत हर आगे के AI-काम (खंड 4-19) में अपने-आप लगाना सीख पाएँगे।\n\n## 2. मुख्य बात\nAI बहुत भरोसेमंद आवाज़ में ग़लत बात भी कह सकता है — यही उसकी सबसे बड़ी ख़ूबी और सबसे बड़ा ख़तरा दोनों है। एक-वाक्य बात — **तीन जगह सबसे ज़्यादा गढ़ता है — दाम (जो आपने नहीं बताया, AI अंदाज़े से डाल देता है), गुण (जैसे \"वाटरप्रूफ़\", \"गारंटीड\" जो फ़ॉर्म में नहीं था), आकार-नाप (रंग-साइज़ उलट देना) — इन तीनों को हर बार अपने मूल फ़ॉर्म (पाठ-15) से मिलाकर जाँचना ही reality-check है।**\n\n## तीन सबसे आम गढ़ावट — पहचान कैसे करें\n**गढ़ा दाम** — आपने फ़ॉर्म में दाम-सीमा दी थी (₹400-₹500); AI मसौदे में अचानक \"₹299 में उपलब्ध\" जैसा एक ठोस, अलग नंबर आ जाए — यह गढ़ा है, हटाइए। **झूठा गुण** — फ़ॉर्म में \"कॉटन कपड़ा\" लिखा था; AI विवरण में \"वाटरप्रूफ़, दाग़-रोधी, प्रीमियम क्वालिटी\" जोड़ दे — इनमें से कोई फ़ॉर्म में नहीं तो हटाइए या दुकानदार से पूछकर फ़ॉर्म में जोड़िए। **ग़लत आकार/रंग** — फ़ॉर्म में \"नीला, M साइज़\" था; AI शीर्षक में \"लाल\" या \"L साइज़\" लिख दे — हर संख्या-रंग-नाप शब्द को अलग से फ़ॉर्म से मिलाइए।\n\n## चित्र — reality-check की पाँच-सवाल जाँच-सूची\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">AI Reality-Check — तीन जगह सबसे ज़्यादा गढ़ता है</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">हर बार मूल फ़ॉर्म (पाठ-15) से मिलाओ</text>\n<g font-size=\"16\" fill=\"#0B1F3A\" text-anchor=\"middle\">\n<rect x=\"40\" y=\"120\" width=\"230\" height=\"200\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"155\" y=\"152\" font-size=\"18\" font-weight=\"bold\">💰 गढ़ा दाम</text>\n<text x=\"155\" y=\"185\">फ़ॉर्म: ₹400-500</text>\n<text x=\"155\" y=\"215\">AI-मसौदा: \"₹299\"</text>\n<text x=\"155\" y=\"250\" font-weight=\"bold\">✗ हटाओ</text>\n<text x=\"155\" y=\"280\">दाम सिर्फ़ फ़ॉर्म से</text>\n<rect x=\"285\" y=\"120\" width=\"230\" height=\"200\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"152\" font-size=\"18\" font-weight=\"bold\">🏷️ झूठा गुण</text>\n<text x=\"400\" y=\"185\">फ़ॉर्म: \"कॉटन कपड़ा\"</text>\n<text x=\"400\" y=\"215\">AI: \"वाटरप्रूफ़\"</text>\n<text x=\"400\" y=\"250\" font-weight=\"bold\">✗ हटाओ/पूछो</text>\n<text x=\"400\" y=\"280\">दुकानदार से पक्का करो</text>\n<rect x=\"530\" y=\"120\" width=\"230\" height=\"200\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"645\" y=\"152\" font-size=\"18\" font-weight=\"bold\">📏 ग़लत नाप</text>\n<text x=\"645\" y=\"185\">फ़ॉर्म: नीला, M</text>\n<text x=\"645\" y=\"215\">AI: \"लाल, L\"</text>\n<text x=\"645\" y=\"250\" font-weight=\"bold\">✗ सुधारो</text>\n<text x=\"645\" y=\"280\">हर रंग-नाप शब्द मिलाओ</text>\n</g>\n<rect x=\"60\" y=\"360\" width=\"680\" height=\"230\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n<text x=\"400\" y=\"394\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"bold\" fill=\"#0B1F3A\">reality-check जाँच-सूची — हर AI-मसौदे पर</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<text x=\"90\" y=\"430\">☐ हर दाम/संख्या फ़ॉर्म से मिलाई?</text>\n<text x=\"90\" y=\"464\">☐ हर गुण-दावा (कॉटन, वाटरप्रूफ़, गारंटी) फ़ॉर्म से मिलाया?</text>\n<text x=\"90\" y=\"498\">☐ हर रंग-नाप-साइज़ शब्द सही जगह?</text>\n<text x=\"90\" y=\"532\">☐ कोई स्वास्थ्य/सुरक्षा-दावा है जो झूठा हो सकता?</text>\n<text x=\"90\" y=\"566\">☐ जो फ़ॉर्म में \"पता नहीं\" था, वहाँ AI ने कुछ भर तो नहीं दिया?</text>\n</g>\n<rect x=\"60\" y=\"610\" width=\"680\" height=\"70\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"400\" y=\"642\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"bold\" fill=\"#2E7D32\">यह जाँच हर बार, हर मंच पर, हर AI-काम पर — पूरे कोर्स-भर</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## पाँच-सवाल जाँच-सूची — कहीं भी इस्तेमाल करें\nयह जाँच-सूची सिर्फ़ आज के लिए नहीं है — पूरे कोर्स में AI-हुनर वाले हर पाठ (खंड 4-19) के अंत में यही पाँच सवाल लगेंगे। रट लीजिए — (1) हर दाम/संख्या फ़ॉर्म से मिली? (2) हर गुण-दावा फ़ॉर्म से मिला? (3) हर रंग-नाप सही? (4) कोई स्वास्थ्य/सुरक्षा-दावा झूठा तो नहीं? (5) जो \"पता नहीं\" था, वहाँ AI ने ख़ुद कुछ भर तो नहीं दिया? पाँचों \"हाँ\" तभी मसौदा सौंपने लायक़ है। यह पाठ-20 के \"पाँच-कड़ी नियम\" का \"जाँचो\" कदम है — विस्तार से, अभ्यास-सहित।\n\n## गढ़ावट क्यों होती है — समझ से डर कम\nAI \"अगला शब्द अनुमान\" से काम करता है — जब आपने कोई जानकारी नहीं दी, तो वह ख़ाली जगह भरने के लिए वही अनुमान लगाता है जो आमतौर पर ऐसी लिस्टिंग में होता है (\"प्रीमियम क्वालिटी\", \"बेस्ट प्राइस\")। यह जानबूझकर झूठ नहीं है, यह AI के काम करने का तरीक़ा है — इसलिए डरने की बजाय इसे समझकर जाँचना ज़्यादा असरदार है। जितनी पूरी, सटीक जानकारी आप शुरू में (फ़ॉर्म में) देंगे, उतना कम गढ़ावट का मौक़ा AI को मिलेगा — यही पाठ-15 और पाठ-25 (Data Feed) की असली अहमियत है।\n\n## एक असली उदाहरण — तीन पंक्तियाँ, तीन गढ़ावट\nएक सेवा-सहायक ने बुनकर की सूती साड़ी के लिए AI से विवरण माँगा। मसौदा आया — \"प्रीमियम हैंडलूम साड़ी, ₹1,499, रंग नहीं छूटता, फ़्री ब्लाउज़ पीस, 6.3 मीटर।\" फ़ॉर्म से मिलाया — दाम-सीमा फ़ॉर्म में ₹900-₹1,100 थी (गढ़ा दाम); \"रंग नहीं छूटता\" फ़ॉर्म में कहीं नहीं, बुनकर ने कहा था \"पहली धुलाई अलग करें\" (झूठा गुण); ब्लाउज़ पीस साथ नहीं आता (झूठा गुण); लंबाई 5.5 मीटर थी (ग़लत नाप)। पाँच पंक्तियों में चार गढ़ावट — पर सब भरोसेमंद आवाज़ में। सुधरा मसौदा — \"हाथ-करघे की सूती साड़ी, 5.5 मीटर, दाम ₹900-₹1,100 (दुकान पर पूछें), पहली धुलाई अलग करें, ब्लाउज़ पीस साथ नहीं।\" कम चमक, पूरा सच — और वापसी-झगड़ा शून्य।\n\n## reality-check कब-कब — तीन मौक़े\nसिर्फ़ मसौदा बनते समय नहीं — तीन बार जाँच लगती है। (1) **मसौदा आते ही** — ऊपर की पाँच-सवाल सूची; (2) **मंच पर चढ़ाने से पहले** — क्योंकि बीच में आपने या दुकानदार ने कुछ बदला हो सकता है; (3) **हर तीन महीने** — दाम, स्टॉक, गुण बदल जाते हैं, पुराना सच आज का झूठ बन सकता है। तीसरा मौक़ा सबसे ज़्यादा भुलाया जाता है — पाठ-30 का काम-कार्ड इसे आदत बनाता है।\n\n## संख्या-शब्दों की अलग सूची — सबसे तेज़ तरीक़ा\nमसौदे में हर संख्या-शब्द (दाम, नाप, वज़न, मात्रा, वारंटी-महीने) को एक अलग पंक्ति में निकालिए — फिर फ़ॉर्म की संख्याओं के बगल में रखिए। दस सेकंड में सारी नाप-गढ़ावट दिख जाती है, क्योंकि आँख पूरा अनुच्छेद पढ़ते हुए \"6.3\" और \"5.5\" का फ़र्क़ छोड़ देती है, पर अलग सूची में नहीं छोड़ती।\n\n## 3. आज का काम «काम-कार्ड»\nअपनी मास्टर-शीट (पाठ-26) और पाठ 20-22 की तीनों-रूप लिस्टिंग निकालिए। पाँच-सवाल जाँच-सूची से पूरी लिस्टिंग को एक बार फिर, ध्यान से पढ़िए — हर दाम, हर गुण, हर रंग-नाप को फ़ॉर्म से मिलाइए। जो कुछ भी गढ़ा/ग़लत मिले, कॉपी में एक \"पकड़ी गई ग़लतियाँ\" सूची बनाइए और लिस्टिंग में सुधारिए। अगर कुछ भी ग़लत न मिले, वह भी लिखिए — पर एक बार और ध्यान से दोबारा पढ़िए। जाँच-सूची: ☐ पाँच-सवाल जाँच पूरी लिस्टिंग पर ☐ पकड़ी-ग़लतियाँ सूची बनी ☐ सुधार किए ☐ दोबारा एक बार पढ़ा ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = पूरी लिस्टिंग पर पाँचों सवाल लगे; जो ग़लतियाँ मिलीं, वे कॉपी में दर्ज और लिस्टिंग में सुधरी हुई; कम-से-कम एक ईमानदार \"यहाँ मैंने पहले नहीं पकड़ा था\" वाला उदाहरण। समय: 30 मिनट।\n\n## 5. सबूत\nसबूत-खाते में \"पकड़ी-ग़लतियाँ\" सूची और सुधरी लिस्टिंग। यह जाँच-सूची अब आपके \"मेरे काम-कार्ड\" फ़ोल्डर (पाठ-8) में स्थायी रूप से रहनी चाहिए।\n\n## 6. AI-सहायक\nइस पाठ में उलटा काम कीजिए — AI से ख़ुद पूछिए \"मैंने यह लिस्टिंग (चिपकाइए) बनाई, इसे मेरी उत्पाद-जानकारी (फ़ॉर्म से चिपकाइए) से मिलाकर बताओ कहीं कोई ऐसी बात है जो जानकारी में नहीं थी\" — पर अंतिम भरोसा फिर भी अपनी आँख पर।\n\n## 7. आम ग़लती\nपहली — reality-check को एक बार का काम समझना — यह हर बार, हर नए मसौदे पर दोहराना है। दूसरी — सिर्फ़ दाम जाँचना, गुण-नाप छोड़ देना। तीसरी — \"AI ने लिखा है तो सही होगा\" सोचकर भरोसा कर लेना। चौथी — ग़लती पकड़ने के बाद सिर्फ़ वह एक जगह सुधारना, बाक़ी लिस्टिंग दोबारा न पढ़ना।\nपाँचवीं — जाँच सिर्फ़ शीर्षक-बुलेट पर करना और लंबे विवरण को \"ठीक ही होगा\" मानकर छोड़ना — गढ़ावट अक्सर लंबे विवरण के बीच छिपती है। छठी — जो शब्द फ़ॉर्म में नहीं, उसे \"अच्छा लग रहा है\" सोचकर रहने देना; न मिले तो हटाओ या दुकानदार से पूछकर फ़ॉर्म में जोड़ो — तीसरा रास्ता नहीं। सातवीं — reality-check को AI से ही करवाना (\"जाँच लो कुछ ग़लत तो नहीं\") — जाँच इंसान करे, फ़ॉर्म सामने रखकर।\n\n## 8. सुरक्षा-पत्रक\nगढ़ा-दाम या झूठा-गुण लिस्टिंग में रह जाना सिर्फ़ ग़लती नहीं — मंच-नीति में \"भ्रामक लिस्टिंग\" और उपभोक्ता-कानून दोनों का उल्लंघन बन सकता है, जिससे खाता-बंद और शिकायत दोनों हो सकते हैं (खंड-20)। स्वास्थ्य/सुरक्षा-दावों पर ख़ासतौर पर सख़्ती। सेवा-सहायक: दुकानदार को हर सुधार-सूची दिखाइए।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। reality-check की सोच AI के बुनियादी काम-करने के तरीक़े पर आधारित, LOW-volatility क्योंकि सिद्धांत नहीं बदलता। 📎 मूल-कोर्स-कड़ी: भ्रामक लिस्टिंग पर मंच-नीति — Amazon \"Accurate listings/Prohibited seller activities\" — Seller University — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=ai-reality-check · platform=none · level=O · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं तीन सबसे आम गढ़ावट (दाम, गुण, नाप) बता सकता हूँ।\n- [ ] मैंने पाँच-सवाल जाँच-सूची अपनी पूरी लिस्टिंग पर लगाई है।\n- [ ] मैंने कम-से-कम एक ग़लती पकड़कर सुधारी है (या ईमानदारी से \"कुछ नहीं मिला\" लिखा है)।\n- [ ] मैं समझता हूँ कि AI गढ़ता क्यों है।\n- [ ] मैं जानता हूँ कि यह जाँच-सूची पूरे कोर्स में बार-बार इस्तेमाल होगी।",
 "29": "═\n# पाठ-29: ★ Decision Lab — यह उत्पाद ऑनलाइन-योग्य है या नहीं, 10 उत्पादों पर फ़ैसला\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर O · रास्ता A,B · volatility LOW · Business Decision Lab)*\n\n## 1. उद्देश्य\nयह खंड-2 का पहला Decision Lab है — यानी feature सीखने की जगह, फ़ैसला-अभ्यास। पाठ-11 से 28 तक जो हुनर सीखे, आज उन सबको जोड़कर 10 असली/काल्पनिक उत्पादों पर एक व्यापार-फ़ैसला लेंगे। पाठ के बाद आप तीन बातें कर पाएँगे — किसी भी उत्पाद पर \"ऑनलाइन-योग्य या नहीं\" का पूरा फ़ैसला कुछ मिनटों में ले पाएँगे; अपने फ़ैसले को ठोस कारणों से सही ठहरा पाएँगे; और समझ पाएँगे कि Decision Lab feature-रटन से अलग, असली सोच की परीक्षा क्यों है।\n\n## 2. मुख्य बात\nअब तक हर पाठ में एक-एक हुनर सीखा; आज सब हुनर एक साथ, असली फ़ैसले में इस्तेमाल होंगे। एक-वाक्य बात — **किसी भी उत्पाद के लिए पाँच सवाल पूछो — रंग-श्रेणी क्या (13), प्रतिबंधित तो नहीं (14), फ़ोटो-लिस्टिंग बन सकती है (16-25), HSN-GST पता है (24), और सबसे बड़ा — क्या यह मेहनत के लायक़ है — पाँचों का जवाब मिलकर बताता है \"आज शुरू करो\" या \"अभी रुको\"।**\n\n## Decision Lab कैसे काम करता है — feature नहीं, फ़ैसला\nयह पाठ किसी नई तकनीक या मंच का बटन नहीं सिखाता — यह आपके दिमाग़ को खंड-2 के सारे हुनर एक साथ इस्तेमाल करने की कसरत देता है। असली दुनिया में दुकानदार/ग्राहक \"सीखने\" के लिए नहीं आते, फ़ैसले के लिए आते हैं — \"क्या मैं यह उत्पाद ऑनलाइन बेचूँ?\" यह पाठ ठीक वही सवाल है, बस सुरक्षित अभ्यास-कक्षा में। हर मुख्य खंड के अंत में ऐसा एक Decision Lab आएगा (कुल 8 पूरे कोर्स में) — यह \"feature-रटन\" से \"commerce-सोच\" की ओर बढ़ने का तरीक़ा है।\n\n## चित्र — पाँच-सवाल फ़ैसला-रास्ता\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">★ Decision Lab — ऑनलाइन-योग्य या नहीं?</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">पाँच सवाल, हर एक पिछले पाठों से</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"40\" y=\"120\" width=\"720\" height=\"55\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/>\n<text x=\"60\" y=\"153\" font-weight=\"bold\">1. रंग-श्रेणी क्या? (पाठ-13)</text><text x=\"450\" y=\"153\">हरा/पीला/लाल</text>\n<rect x=\"40\" y=\"185\" width=\"720\" height=\"55\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/>\n<text x=\"60\" y=\"218\" font-weight=\"bold\">2. प्रतिबंधित तो नहीं? (पाठ-14)</text><text x=\"450\" y=\"218\">मंच-नीति जाँची?</text>\n<rect x=\"40\" y=\"250\" width=\"720\" height=\"55\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/>\n<text x=\"60\" y=\"283\" font-weight=\"bold\">3. फ़ोटो-लिस्टिंग-डेटा बन सकती? (पाठ 16-25)</text><text x=\"450\" y=\"283\">5-कोण+शीर्षक+data-feed?</text>\n<rect x=\"40\" y=\"315\" width=\"720\" height=\"55\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"2\"/>\n<text x=\"60\" y=\"348\" font-weight=\"bold\">4. HSN-GST पता है? (पाठ-24)</text><text x=\"450\" y=\"348\">श्रेणी साफ़?</text>\n<rect x=\"40\" y=\"380\" width=\"720\" height=\"55\" rx=\"10\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"60\" y=\"413\" font-weight=\"bold\">5. मेहनत के लायक़? (कमाई vs मेहनत)</text><text x=\"450\" y=\"413\">कितना समय, कितनी उम्मीद?</text>\n</g>\n<rect x=\"60\" y=\"460\" width=\"330\" height=\"130\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"225\" y=\"494\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#2E7D32\">पाँचों हाँ → आज शुरू करो</text>\n<text x=\"225\" y=\"524\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">मास्टर-शीट में पंक्ति जोड़ो</text>\n<text x=\"225\" y=\"554\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">खंड-3 (WhatsApp) में इस्तेमाल करो</text>\n<rect x=\"410\" y=\"460\" width=\"330\" height=\"130\" rx=\"14\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"575\" y=\"494\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#0B1F3A\">कोई \"नहीं\" → रुको/सुधारो</text>\n<text x=\"575\" y=\"524\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">कौन-सा सवाल अटका, वहीं</text>\n<text x=\"575\" y=\"554\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0B1F3A\">तैयारी पूरी करके वापस आओ</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">पढ़ाई मुफ़्त — acslearn.com</text>\n</svg>\n```\n\n## पाँचवाँ सवाल — मेहनत बनाम कमाई की उम्मीद\nपहले चार सवाल तकनीकी हैं — पाँचवाँ व्यापारिक है, और अक्सर भुला दिया जाता है। हर उत्पाद के लिए पूछिए — फ़ोटो-लिस्टिंग-कैटलॉग बनाने में कितना समय लगेगा? दाम कितना है और मुनाफ़ा कितना बचेगा (यहाँ अभी अंदाज़ा, असली गणित खंड-5 में)? कितनी बार बिकने की उम्मीद है? अगर मेहनत ज़्यादा और उम्मीद कम है, शायद वह उत्पाद पहले नंबर पर नहीं, बाद में आना चाहिए — भले ही तकनीकी रूप से \"योग्य\" हो।\n\n## एक असली उदाहरण — तीन उत्पाद, तीन फ़ैसले\nगाँव के तीन उत्पाद लीजिए। **(क) अचार** — रंग-श्रेणी पीली (खाद्य, लेबल-नियम); प्रतिबंधित नहीं; फ़ोटो-लिस्टिंग आसान; HSN पता; मेहनत-कमाई — शीशी टूटने का जोखिम और FSSAI-लेबल चाहिए। फ़ैसला: \"रुको/सुधारो\" — पहले लेबल व पैकिंग तैयार करो, फिर शुरू। **(ख) हाथ का बुना पायदान** — हरा; प्रतिबंधित नहीं; फ़ोटो सादी; HSN पता; मेहनत कम, हर घर में माँग। फ़ैसला: \"आज शुरू करो\"। **(ग) घर का बना आयुर्वेदिक तेल** — लाल के पास (स्वास्थ्य-दावा, लाइसेंस); फ़ैसला: \"अभी नहीं\" — जब तक लाइसेंस व नियम साफ़ न हों। तीनों तकनीकी रूप से \"बेचे जा सकते\" थे — पर पाँच सवालों ने क्रम तय किया।\n\n## \"रुको\" का मतलब \"कभी नहीं\" नहीं है\nDecision Lab में \"रुको/सुधारो\" सूची असफलता-सूची नहीं — यह तैयारी-सूची है। हर \"रुको\" के आगे लिखिए क्या चाहिए (लेबल, लाइसेंस, बेहतर फ़ोटो, दाम-जानकारी) और कब तक। तीन महीने बाद वही तालिका दोबारा भरिए — कई \"रुको\" तब \"आज शुरू\" बन जाते हैं। यही असली दुकानदार-सोच है — जल्दबाज़ी नहीं, क्रम।\n\n## दुकानदार को फ़ैसला कैसे समझाएँ (सेवा-सहायक के लिए)\nअगर आप किसी दुकानदार के लिए यह Lab कर रहे हैं, उसे पाँच-सवाल तालिका दिखाइए, फ़ैसला नहीं थोपिए — \"आपके इन तीन उत्पादों में पायदान अभी सबसे तैयार है, अचार दो हफ़्ते की तैयारी के बाद, तेल पर अभी नियम देखना है\" — कारण-सहित, सादी भाषा में। फ़ैसला दुकानदार का, तालिका आपकी — यही भरोसा बनाता है।\n\n## 3. आज का काम «काम-कार्ड»\nपाठ-11 की अपनी 20-उत्पाद सर्वे-सूची से 10 उत्पाद चुनिए। हर एक के लिए पाँच-सवाल तालिका भरिए। जिनके पाँचों \"हाँ\" हैं, \"आज शुरू करो\" सूची में डालिए (मास्टर-शीट में जोड़िए); जिनमें कोई \"नहीं\" है, \"रुको/सुधारो\" सूची में डालकर लिखिए क्या तैयारी बाक़ी है। अंत में एक-पंक्ति फ़ैसला — अगले हफ़्ते किस उत्पाद पर सबसे पहले पूरा काम करेंगे। जाँच-सूची: ☐ 10 उत्पादों पर पाँच-सवाल तालिका ☐ \"आज शुरू\" व \"रुको\" सूची बनी ☐ मास्टर-शीट अपडेट हुई ☐ अगले हफ़्ते का फ़ैसला ☐ फ़ोटो सबूत-खाते में।\n\n## तालिका का नमूना — एक पंक्ति ऐसे भरें\n| उत्पाद | रंग-श्रेणी (13) | प्रतिबंधित? (14) | फ़ोटो-लिस्टिंग बनेगी? (16-25) | HSN-GST पता? (24) | मेहनत बनाम कमाई | फ़ैसला |\n|---|---|---|---|---|---|---|\n| बुना पायदान | हरा | नहीं | हाँ, सादी | हाँ | कम मेहनत, नियमित माँग | आज शुरू |\n| अचार | पीला | नहीं | हाँ | हाँ | लेबल-पैकिंग तैयारी | रुको — 2 हफ़्ते |\nहर पंक्ति में \"फ़ैसला\" के आगे एक शब्द कारण ज़रूर — बिना कारण का फ़ैसला अगले महीने ख़ुद को भी समझ नहीं आता।\n\n## 4. नाप\nसफल = 10 उत्पादों की पूरी तालिका; \"आज शुरू\" और \"रुको\" दोनों सूचियों में कम-से-कम एक-एक उत्पाद; अगले हफ़्ते का फ़ैसला तर्क-सहित। समय: 40 मिनट।\n\n## 5. सबूत\nसबूत-खाते में पाँच-सवाल तालिका और दोनों सूचियाँ। यह Decision Lab-अभ्यास खंड-13 (पाठ-204) और खंड-19 (277) में इसी तरह दोहराया जाएगा।\n\n## Decision Lab के बाद — मास्टर-शीट में क्या बदले\n\"आज शुरू\" वाले उत्पादों को पाठ-26 की मास्टर-शीट में एक नया खाना देकर दर्ज कीजिए — \"स्थिति: शुरू, तारीख़\"; \"रुको\" वालों को \"स्थिति: तैयारी, क्या बाक़ी, कब तक\"। इससे शीट सिर्फ़ उत्पाद-सूची नहीं, आपकी योजना-डायरी बन जाती है — खंड-3 में जब WhatsApp-कैटलॉग बनेगा, उसमें सिर्फ़ \"शुरू\" वाले उत्पाद जाएँगे, \"तैयारी\" वाले नहीं। यही एक चीज़ = एक जगह का पालन है — फ़ैसला यहाँ, अमल शीट से।\n\n## 6. AI-सहायक\nAI से पूछिए — \"मेरे पास यह 10 उत्पाद हैं (सूची — दाम-श्रेणी सहित); व्यापारिक नज़रिए से किसे पहले शुरू करना चाहिए और क्यों?\" — AI की राय अपनी पाँच-सवाल तालिका से मिलाइए।\nAI से एक तालिका बनवाने से पहले उसे पाँचों सवाल और आपके 10 उत्पादों के नाम दीजिए — पर उसका भरा \"फ़ैसला\" सिर्फ़ मसौदा है; अंतिम \"आज शुरू/रुको\" आप ख़ुद लिखें, क्योंकि पाँचवाँ सवाल (आपकी मेहनत, आपकी उम्मीद) AI को पता ही नहीं।\n\n## 7. आम ग़लती\nपहली — सिर्फ़ तकनीकी सवाल (1-4) पर रुक जाना, पाँचवाँ छोड़ देना। दूसरी — सब उत्पादों को \"हाँ\" दे देना। तीसरी — फ़ैसला ले लेना पर मास्टर-शीट में दर्ज न करना। चौथी — \"रुको\" सूची को हमेशा के लिए भूल जाना।\nपाँचवीं — पाँचवें सवाल (मेहनत-कमाई) को \"बाद में देखेंगे\" कहकर छोड़ना और चारों तकनीकी \"हाँ\" पर ही शुरू कर देना। छठी — दस की जगह दो-तीन उत्पादों पर तालिका भरकर \"समझ आ गया\" मान लेना — तुलना दस पर ही असली सीख देती है। सातवीं — \"रुको\" सूची पर तारीख़ न लिखना, जिससे वह हमेशा के लिए रुकी रह जाती है।\n\n## 8. सुरक्षा-पत्रक\nDecision Lab अभ्यास में इस्तेमाल उत्पाद अगर असली दुकानदारों के हैं, तो फ़ैसला उन्हें भी बताइए। \"आज शुरू करो\" सूची का मतलब असली बिक्री शुरू नहीं है अभी — यह सिर्फ़ प्राथमिकता-सूची है। 18 से कम विद्यार्थी यह पूरा अभ्यास काल्पनिक/परिवार-दुकान पर कर सकते हैं।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। Decision Lab ACS का अपना फ़ैसला-अभ्यास ढाँचा, किसी मंच की नीति नहीं। 📎 मूल-कोर्स-कड़ी: व्यापार-निर्णय के सामान्य ढाँचे के लिए Google के 7-कोर्स प्रमाणपत्र का परिचय-मॉड्यूल — https://grow.google/certificates/digital-marketing-ecommerce/ — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=decision-lab-product-eligibility · platform=none · level=O · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैं पाँच-सवाल फ़ैसला-रास्ता बिना देखे बोल सकता हूँ।\n- [ ] मैंने 10 उत्पादों पर पूरी तालिका भरी है।\n- [ ] मेरे पास \"आज शुरू\" और \"रुको\" दोनों सूचियाँ हैं, ईमानदार मिश्रण के साथ।\n- [ ] मैंने अगले हफ़्ते के लिए एक तर्क-सहित फ़ैसला लिया है।\n- [ ] मैं जानता हूँ कि Decision Lab feature-रटन नहीं, फ़ैसला-अभ्यास है।",
 "30": "═\n# पाठ-30: खंड-2 दोहराव — औज़ार-सूची (छह-सवाल छलनी) व अभ्यास-परीक्षा\n═══════════════════════════════════════════════════\n*(ई-कॉमर्स मास्टरी · खंड-2 · generator-input मसौदा v1.0 · स्तर O · रास्ता A,B · volatility LOW)*\n\n## 1. उद्देश्य\nखंड-2 के 18 पाठ पूरे — उत्पाद-जाँच से लेकर Data Feed, मास्टर-शीट और पहले Decision Lab तक। आज दोहराव, \"छह-सवाल छलनी\" (हर AI/फ़ोटो-औज़ार चुनने का तरीक़ा) और 20-प्रश्न अभ्यास-परीक्षा। पाठ के बाद आप तीन बातें कर पाएँगे — खंड-2 की पूरी यात्रा को एक नक़्शे में देख पाएँगे; किसी भी नए मुफ़्त औज़ार (फ़ोटो/AI) को छह सवालों से परख पाएँगे; और खंड-3 (WhatsApp) में जाने से पहले अपनी तैयारी पक्की पाएँगे।\n\n## 2. मुख्य बात\nखंड-2 में एक धागा बार-बार चला — \"AI मसौदा दे, आप जाँचें, फ़ॉर्म ही सच का स्रोत।\" एक-वाक्य बात — **18 पाठों में हमने एक उत्पाद को कच्ची जानकारी से लेकर मशीन-पढ़ने-योग्य, bulk-तैयार, reality-checked रूप तक पहुँचाया — यह पूरा रास्ता अब आपके पास हर नए उत्पाद के लिए एक टेम्पलेट है, हर बार शून्य से नहीं सोचना।**\n\n## छह-सवाल छलनी — कोई भी नया औज़ार चुनने का तरीक़ा\nखंड-2-भर में \"मुफ़्त AI/फ़ोटो-औज़ार\" का ज़िक्र आया, पर कोई एक नाम स्थायी नहीं रखा गया (Δ-पाठ इसलिए)। नया औज़ार आज़माने से पहले छह सवाल पूछिए — **(1) मुफ़्त है** (या शुरुआत के लिए मुफ़्त हिस्सा काफ़ी)? **(2) हिंदी/अपनी भाषा** में इस्तेमाल हो सकता है? **(3) मोबाइल पर** चलता है (कंप्यूटर ज़रूरी नहीं)? **(4) खाता बनाते समय क्या माँगता है** — सिर्फ़ ईमेल, या आधार-पैन जैसी संवेदनशील चीज़ (माँगे तो शक)? **(5) नीति में क्या लिखा है** मेरी अपलोड फ़ाइल/फ़ोटो के बारे में — वे रखते हैं या मिटाते हैं? **(6) कोई विकल्प है** अगर यह औज़ार बंद/पैसे वाला हो जाए (कभी भी एक ही औज़ार पर पूरी तरह निर्भर न रहें)। यह छलनी हर आगे के खंड (3-19) में हर नए औज़ार पर लगाइए।\n\n## चित्र — खंड-2 का पूरा नक़्शा\n```svg\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Noto Sans Devanagari, Inter\">\n<rect width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"52\" text-anchor=\"middle\" font-size=\"27\" font-weight=\"bold\" fill=\"#0B1F3A\">खंड-2 का नक़्शा — कच्चे उत्पाद से मशीन-तैयार तक</text>\n<text x=\"400\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" fill=\"#1565C0\">नीचे से ऊपर पढ़ो · सोना = जहाँ सबसे ज़्यादा AI-सावधानी चाहिए</text>\n<g font-size=\"16\" fill=\"#0B1F3A\">\n<rect x=\"60\" y=\"650\" width=\"680\" height=\"60\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"80\" y=\"678\" font-weight=\"bold\">13-15 · उत्पाद-जाँच</text><text x=\"330\" y=\"678\">हरा-पीला-लाल · प्रतिबंधित · सहमति-फ़ॉर्म</text>\n<rect x=\"60\" y=\"580\" width=\"680\" height=\"60\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"80\" y=\"608\" font-weight=\"bold\">16-19 · फ़ोटो</text><text x=\"330\" y=\"608\">पाँच-कोण · AI-सफ़ाई · lifestyle/infographic · मंच-मानक</text>\n<rect x=\"60\" y=\"510\" width=\"680\" height=\"60\" rx=\"10\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"80\" y=\"538\" font-weight=\"bold\">20-23 · लिस्टिंग-लेखन</text><text x=\"330\" y=\"538\">AI-मसौदा · तीन-ढंग · AI-ख़रीदार-भाषा · कीवर्ड</text>\n<rect x=\"60\" y=\"440\" width=\"680\" height=\"60\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"80\" y=\"468\" font-weight=\"bold\">24-25 · तकनीकी-नींव</text><text x=\"330\" y=\"468\">HSN-GST · Product Data Feed</text>\n<rect x=\"60\" y=\"370\" width=\"680\" height=\"60\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n<text x=\"80\" y=\"398\" font-weight=\"bold\">26-27 · संगठन</text><text x=\"330\" y=\"398\">मास्टर-शीट · bulk-तैयारी</text>\n<rect x=\"60\" y=\"290\" width=\"680\" height=\"60\" rx=\"10\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<text x=\"80\" y=\"318\" font-weight=\"bold\">28 · reality-check</text><text x=\"330\" y=\"318\">पाँच-सवाल जाँच — पूरे कोर्स-भर इस्तेमाल</text>\n<rect x=\"60\" y=\"220\" width=\"680\" height=\"60\" rx=\"10\" fill=\"#FFFFFF\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n<text x=\"80\" y=\"248\" font-weight=\"bold\">29 · ★ Decision Lab</text><text x=\"330\" y=\"248\">10 उत्पादों पर असली फ़ैसला</text>\n</g>\n<line x1=\"400\" y1=\"650\" x2=\"400\" y2=\"642\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><line x1=\"400\" y1=\"580\" x2=\"400\" y2=\"572\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><line x1=\"400\" y1=\"510\" x2=\"400\" y2=\"502\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><line x1=\"400\" y1=\"440\" x2=\"400\" y2=\"432\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><line x1=\"400\" y1=\"370\" x2=\"400\" y2=\"362\" stroke=\"#0B1F3A\" stroke-width=\"3\"/><line x1=\"400\" y1=\"290\" x2=\"400\" y2=\"282\" stroke=\"#0B1F3A\" stroke-width=\"3\"/>\n<rect x=\"150\" y=\"140\" width=\"500\" height=\"50\" rx=\"25\" fill=\"#2E7D32\"/>\n<text x=\"400\" y=\"172\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"bold\" fill=\"#F5F7FA\">✓ उत्पाद तैयार — आगे खंड-3 WhatsApp दुकान</text>\n<text x=\"400\" y=\"770\" text-anchor=\"middle\" font-size=\"16\" fill=\"#2E7D32\">एक उत्पाद पूरा सीखा = हर अगला उत्पाद तेज़ · acslearn.com</text>\n</svg>\n```\n\n## एक असली उदाहरण — छह-सवाल छलनी ने एक \"मुफ़्त\" औज़ार रोका\nएक सीखने वाला एक चमकदार \"मुफ़्त AI-लिस्टिंग-ऐप\" लेने वाला था। छह-सवाल छलनी लगाई — (1) कौन बनाता है? (अनजान); (2) मेरा डेटा कहाँ जाता है? (नीति में नहीं); (3) मुफ़्त क्यों? (साफ़ नहीं); (4) कब से चल रहा? (तीन महीने); (5) कोई असली-दुकानदार इस्तेमाल करता? (कोई नहीं मिला); (6) न मिले तो पुराना तरीक़ा चलेगा? (हाँ — पाठ-20 का AI-सहायक + फ़ॉर्म)। छह में चार लाल — नहीं लिया। दो हफ़्ते बाद वह ऐप बंद हो गया, कई लोगों की लिस्टिंग-सामग्री साथ। छलनी ने पैसा नहीं, समय और डेटा बचाया — यही खंड-2 के \"औज़ार-सूची\" पाठ का मक़सद है।\n\n## खंड-2 की औज़ार-सूची — छह-सवाल छलनी पास वाले ही\nकैमरा (फ़ोन) · रोशनी (खिड़की) · AI-सफ़ाई (पाठ-17 — छलनी-पास) · AI-लेखन-सहायक (पाठ-20) · Excel/शीट (26) · मंच का bulk-साँचा (27) · आधिकारिक HSN-सूची (24) · Feed-साँचा (25)। हर औज़ार के आगे \"छलनी: पास, तारीख़\" — नया औज़ार सूची में तभी जब छह सवाल पास (पाठ-62 में भुगतान-ऐप पर वही छलनी)।\n\n## कमज़ोर-कड़ी सूची — पाठ-12 वाले तीन स्तंभ, आगे बढ़ती हुई\nप्रश्न-पाठ / क्या भूला / कब दोबारा — खंड-1 की सूची में खंड-2 की पंक्तियाँ जोड़िए, नई सूची न बनाइए; पाठ-47 (खंड-3) में यही आगे बढ़ेगी।\n\n## अभ्यास-परीक्षा — 20 प्रश्न, 30 मिनट\nकॉपी में जवाब लिखें, फिर कोष्ठक के पाठ से मिलाएँ। **(1)** हरा-पीला-लाल तीन सवाल क्या हैं? (13) **(2)** पाँच आम ग़लतफ़हमी में से दो उदाहरण? (14) **(3)** सहमति-फ़ॉर्म के चार भाग? (15) **(4)** पाँच फ़ोटो-कोण के नाम? (16) **(5)** \"साफ़ करना\" बनाम \"झूठ बनाना\" — दो-दो उदाहरण? (17) **(6)** disclosure कब, कैसे लिखें? (18) **(7)** मंच-वार फ़ोटो के तीन मानक? (19) **(8)** पाँच-कड़ी नियम (AI-लिस्टिंग) के पाँच कदम? (20) **(9)** Amazon-Flipkart-Meesho शीर्षक का फ़र्क़? (21) **(10)** keyword-भराई बनाम प्राकृतिक-भाषा? (22) **(11)** कीवर्ड ढूँढने के तीन मुफ़्त तरीक़े? (23) **(12)** HSN क्या है, तीन कदम में कैसे जाँचें? (24) **(13)** Product Data Feed के 10 खाने में से पाँच? (25) **(14)** मास्टर-शीट के स्तंभ क्यों एक जगह? (26) **(15)** bulk कब चाहिए, कब नहीं? (27) **(16)** SKU कोड क्या है, क्यों? (27) **(17)** reality-check के पाँच सवाल? (28) **(18)** AI गढ़ता क्यों है? (28) **(19)** Decision Lab के पाँच सवाल? (29) **(20)** छह-सवाल छलनी के छह सवाल? (30)\n\n## आगे क्या — खंड-3 से पहले तीन जाँच\nखंड-3 (WhatsApp Business ऐप) शुरू करने से पहले तीन चीज़ें पास होनी चाहिए — (क) आपकी मास्टर-शीट में कम-से-कम एक उत्पाद पूरी तरह तैयार है (फ़ोटो, लिस्टिंग, HSN, सब)? (ख) आपका Decision Lab (पाठ-29) \"आज शुरू करो\" सूची में कम-से-कम एक उत्पाद है? (ग) छह-सवाल छलनी याद है (अगला खंड में नए औज़ार आएँगे)? तीनों \"हाँ\" तो खंड-3 आज ही शुरू कीजिए — वहाँ आपका यही तैयार उत्पाद पहली बार असली WhatsApp-कैटलॉग में जाएगा।\n\n## 3. आज का काम «काम-कार्ड»\n20-प्रश्न परीक्षा 30 मिनट में, उत्तर मिलाइए, अंक लिखिए। फिर एक पन्ने का \"खंड-2 सार\" बनाइए — छह हिस्से (उत्पाद-जाँच, फ़ोटो, लिस्टिंग-लेखन, तकनीकी-नींव, संगठन, reality-check+Decision Lab), हर एक की एक पंक्ति सीख, अंक, कमज़ोर-कड़ी सूची। ऊपर के तीन जाँच-सवालों के जवाब भी लिखिए। जाँच-सूची: ☐ 20-प्रश्न परीक्षा ☐ अंक + कमज़ोर-कड़ी सूची ☐ खंड-2 सार-पन्ना ☐ 3 जाँच (उत्पाद/Decision-Lab/छलनी) ☐ फ़ोटो सबूत-खाते में।\n\n## 4. नाप\nसफल = परीक्षा बिना पाठ खोले दी गई; अंक ईमानदारी से; सार-पन्ना बना; तीनों जाँच \"हाँ\" (या आज ही पूरी की गई)। असली संकेत — क्या आप एक नए उत्पाद को शुरू से लेकर मशीन-तैयार तक ले जा सकते हैं, बिना बार-बार पाठ खोले? हाँ = खंड-2 पूरा।\n\n## 5. सबूत\nसबूत-खाते में परीक्षा-उत्तरों की फ़ोटो, अंक, सार-पन्ना, तीन जाँच के जवाब। यह सार पोर्टफ़ोलियो में खंड-1 के सार के बाद दूसरा पन्ना बनेगा।\n\n## 6. AI-सहायक\nपरीक्षा के बाद (उत्तर मिलाकर) AI से — \"मुझसे खंड-2 के इन विषयों (सूची) पर 10 और प्रश्न पूछो, उत्तर छिपाकर, अंत में मेरी ग़लतियाँ समझाओ\" — जो अटके, वह भी कमज़ोर-कड़ी सूची में।\n\n## 7. आम ग़लती\nपहली — परीक्षा पाठ खोलकर देना। दूसरी — कम अंक पर हिम्मत हारकर कोर्स छोड़ना। तीसरी — ज़्यादा अंक पर तीन जाँच-सवाल छोड़ देना। चौथी — छह-सवाल छलनी को सिर्फ़ आज याद रखना, आगे भूल जाना — यह अगले हर खंड में औज़ार चुनते समय काम आएगी।\n\n## 8. सुरक्षा-पत्रक\nपरीक्षा-सार-कमज़ोर-कड़ी सूची में दुकानदारों के नाम-फ़ोन नहीं। नाबालिग विद्यार्थी अपने अंक अभिभावक को दिखाएँ। खंड-3 से पहले अपनी दस्तावेज़-थैली और सुरक्षा-पर्ची (पाठ 9-10) की याद ताज़ा कर लीजिए — वहाँ फ़ोटो-अनुमति और AI-निजता के नियम वहाँ फिर काम आएँगे, और अब खंड-3 में यह असली WhatsApp-खाते पर लागू होंगे।\n\n## 9. स्रोत\nइस पाठ की जानकारी ACS पाठ्यक्रम-दल ने तैयार की है: acslearn.com — देखा गया 17-08-2026। बीस प्रश्न खंड-2 के पाठ 13-29 पर; हर प्रश्न के आगे लिखा पाठ-नंबर ही उत्तर-कुंजी है। छह-सवाल छलनी ACS का स्थायी नियम — हर आगे के AI/फ़ोटो-औज़ार-चुनाव पर लागू। 📎 मूल-कोर्स-कड़ी: दोहराव-तरीक़े की झलक के लिए Amazon Seller University का structure — https://sell.amazon.in/learn/seller-university — जाँच-तारीख़ 08/2026। बाहरी site — जानकारी ख़ुद verify करें। (metadata: core_skill=review-khand2 · platform=none · level=O · path=A,B · volatility=LOW · status=ACTIVE · next_review=02/2027)\n\n## 10. योग्यता-जाँच\n- [ ] मैंने 20-प्रश्न परीक्षा बिना पाठ खोले दी है।\n- [ ] मैंने अंक ईमानदारी से लिखे और कमज़ोर-कड़ी सूची बनाई है।\n- [ ] मैंने एक पन्ने का खंड-2 सार बनाया है।\n- [ ] मेरी तीनों जाँच (उत्पाद/Decision-Lab/छलनी) \"हाँ\" हैं।\n- [ ] मैं छह-सवाल छलनी बिना देखे बोल सकता हूँ।"
};
module.exports = { LESSONS };
